import json
from os import getenv
import re
import time
from dataclasses import dataclass, field
from typing import Any, Callable, Optional


# The submission scanner rejects `requests` in agent code. ProxyClient is the
# sandbox-provided transport that both the upstream reference agent and the
# top-scoring miner use; it owns the proxy URL, the inference bearer token and
# its own retry/backoff.
from src.agent.proxy_client import ProxyClient

_ENV_CLIENT = ProxyClient(timeout=75, max_retries=4, retry_delay=1.0)
_LLM_CLIENT = ProxyClient(timeout=20, max_retries=2, retry_delay=1.0)


# ---------------------------------------------------------------------------
# Configuration and injectable transports
# ---------------------------------------------------------------------------

PROXY_URL = getenv("SANDBOX_PROXY_URL", "http://proxy:80").rstrip("/")
# Production kills a task at 300 s by default (SANDBOX_PROBLEM_TIMEOUT).
TIME_BUDGET_S = float(getenv("ORO_AGENT_TIME_BUDGET") or 240.0)
LLM_FAILURES: list = []   # fallback errors, surfaced in the episode notes
USE_LLM = (getenv("ORO_AGENT_USE_LLM") or "1").strip().lower() not in ("0", "false", "no")
DEFAULT_MODELS = {
    "chutes": "deepseek-ai/DeepSeek-V3.2-TEE",
    "openrouter": "deepseek/deepseek-v3.2",
}
# Load shaping. The validator allows 10 s for a whole call group, and every
# session of a run shares ONE search server (local runs: a 1 GB-heap JVM per
# worker). A real run (7 local / up to 45 validator workers) of this fast,
# deterministic agent overloaded it: HTTP 500s and dropped connections inside
# tool calls, i.e. environment_error, which fails the whole run. So groups are
# small, heavy calls (BM25 search, category filter scans) are capped, and turns
# are paced adaptively (EnvSession.call enforces all of it for every family).
# Splitting a group costs a turn, and turns cost reward: shopper budget cuts are
# scheduled at fixed solver turns (3-5 in the pack) and never reach an agent that
# already ordered. So the limits only trim the heaviest groups; pacing (which
# costs time, not turns) does most of the load reduction.
MAX_CALLS_PER_GROUP = int(getenv("ORO_AGENT_MAX_CALLS") or 10)
MAX_SEARCHES_PER_GROUP = 5
MAX_HEAVY_PER_GROUP = int(getenv("ORO_AGENT_MAX_HEAVY") or 6)  # search + filter
MAX_FILTERS_PER_GROUP = int(getenv("ORO_AGENT_MAX_FILTERS") or 3)  # category scans are the slowest calls
MAX_COMPARES_PER_GROUP = 3
COMPARE_LIMIT = 5  # the environment compares at most 5 ids per call
HEAVY_ACTIONS = frozenset({"search", "filter"})
READ_ACTIONS = frozenset({"search", "filter", "view", "compare", "inspect_stock", "inspect_cart"})
# Pause between turns: base + a share of the last round trip (slow server -> slow down).
TURN_PAUSE_S = float(getenv("ORO_AGENT_TURN_PAUSE") or 0.5)
TURN_PAUSE_LATENCY_SHARE = 0.5
TURN_PAUSE_MAX_S = 3.0
# Cross-task throttle. Every task of an evaluation run executes in ONE sandbox
# container (sharing /tmp), and all their tool calls reach one search server.
# The second real local run lost 15/35 sessions to the search server dropping
# connections (RemoteDisconnected) on fast, concurrent search groups; the one
# family that never searches scored 1.0 throughout. At most SEARCH_SLOTS of our
# search/filter/compare groups are in flight at once (flock on /tmp files; the
# kernel releases a lock when its process dies). Fails open after SLOT_WAIT_S.
SEARCH_SLOTS = int(getenv("ORO_AGENT_SEARCH_SLOTS") or 2)
SLOT_DIR = getenv("ORO_AGENT_SLOT_DIR") or "/tmp"
SLOT_WAIT_S = float(getenv("ORO_AGENT_SLOT_WAIT") or 20.0)
SLOT_ACTIONS = frozenset({"search", "filter", "compare"})

# Tests replace these with in-process callables. Production leaves them None.
ENV_TRANSPORT: Optional[Callable[[dict], dict]] = None
LLM_TRANSPORT: Optional[Callable[[dict], dict]] = None

# Shopper text the verifier treats as a request for a reply
# (oro_env_runtime.verify._REPLY_REQUEST plus the "?" rule).
REPLY_REQUEST_RE = re.compile(
    r"(?:^|[.!?;]\s*)(?:please\s+)?(?:confirm|reply|respond|answer|tell me|let me know)\b",
    re.IGNORECASE,
)
# An amount right after a budget phrase (group 1), unless a unit follows it
# ('6.5-inch', 'up to 2 days', '8GB'). Families import this regex too.
BUDGET_CUT_RE = re.compile(
    r"(?:only\s+go\s+up\s+to|go\s+up\s+to|up\s+to|at\s+most|no\s+more\s+than|more\s+than|"
    r"under|below|less\s+than|lower\s+than|within|dropped\s+to|down\s+to|"
    r"max(?:imum)?\s+(?:of\s+)?|cap(?:ped)?\s+(?:it\s+)?at|limit\s+(?:is\s+)?(?:now\s+)?|"
    r"ceiling\s+(?:for\s+me\s+)?(?:is\s+)?(?:now\s+)?|budget\s+(?:is\s+)?(?:now\s+)?(?:of\s+|at\s+)?)"
    r"\s*[:=]?\s*(?:PHP|₱)?\s*([0-9][0-9,]*(?:\.[0-9]+)?)(?!\d|[.,]\d)"
    r"(?!\s*-?\s*(?:inch(?:es)?\b|in\b|[\"”']|hz\b|gb\b|tb\b|mb\b|mp\b|mah\b|%|x\b|k\b|p\b|"
    r"days?\b|hours?\b|hrs?\b|weeks?\b|months?\b|years?\b|items?\b|units?\b|pcs\b|sims?\b))",
    re.IGNORECASE,
)
_BUDGET_TALK_RE = re.compile(
    r"\b(?:balance|budget|only|now|up\s+to|limit|ceiling|cap|under|below|spend|afford|dropped|down\s+to|max)\b",
    re.IGNORECASE,
)
_PRICE_MOVE_RE = re.compile(r"\bfrom\s+(?:PHP|₱)?\s*[0-9][0-9,.]*\s*(?:PHP|₱)?\s+to\b|leaning\s+toward", re.I)


def budget_cut_from_line(line: str, currency: str = "PHP", original_budget: Optional[float] = None) -> Optional[float]:
    """The tightest budget a shopper line states, or None.

    Reads sentence by sentence: amounts after a budget phrase (BUDGET_CUT_RE) or written
    next to the currency, in sentences that talk about the budget and are not a price
    move ('went from X to Y'). Amounts below 0.2x the original budget are ignored as
    misreads (generator cuts are 0.3-0.99x). The caller applies it only if lower.
    """

    values: list = []
    money = rf"(?:(?:{re.escape(currency or 'PHP')}|₱)\s*([0-9][0-9,]*(?:\.[0-9]+)?)|" \
            rf"([0-9][0-9,]*(?:\.[0-9]+)?)\s*(?:{re.escape(currency or 'PHP')}|₱))"
    for sentence in re.split(r"(?<=[.;!?？])\s+", line):
        if sentence.rstrip().endswith(("?", "？")):  # a question about price is not a cut
            continue
        if not _BUDGET_TALK_RE.search(sentence) or _PRICE_MOVE_RE.search(sentence):
            continue
        for match in BUDGET_CUT_RE.finditer(sentence):
            values.append(parse_money(match.group(1)))
        for match in re.finditer(money, sentence, re.IGNORECASE):
            values.append(parse_money(match.group(1) or match.group(2)))
    floor = 0.2 * original_budget if original_budget else 0.0
    values = [v for v in values if v is not None and v > floor]
    return min(values) if values else None


class EnvError(RuntimeError):
    """A non-200 answer from /environment/call."""

    def __init__(self, status: int, detail: Any) -> None:
        super().__init__(f"environment call failed status={status}: {detail}")
        self.status = status
        self.detail = detail


def _http_post_env(envelope: dict) -> dict:
    """POST one envelope through the sandbox proxy.

    ProxyClient returns the parsed body on 200 and None on anything else, after its
    own retries. That loses the HTTP status and body, so the 409 "expected N, got M"
    resync can no longer read the server's turn; EnvSession._call_one compensates
    with a one-shot blind resync instead.
    """
    result = _ENV_CLIENT.post("/environment/call", json_data=envelope)
    if isinstance(result, dict):
        return result
    raise EnvError(0, "no response from /environment/call")


def post_env(envelope: dict) -> dict:
    if ENV_TRANSPORT is not None:
        return ENV_TRANSPORT(envelope)
    return _http_post_env(envelope)


def _http_post_llm(body: dict, timeout: float) -> dict:
    """POST one chat completion through the sandbox proxy.

    ProxyClient attaches the INFERENCE_ACCESS_TOKEN bearer itself for /inference/ paths.
    """
    result = _LLM_CLIENT.post("/inference/chat/completions", json_data=body)
    if isinstance(result, dict):
        return result
    raise RuntimeError("inference failed: no response from proxy")


def llm_model() -> str:
    provider = (getenv("INFERENCE_PROVIDER") or "chutes").strip().lower()
    return getenv("SANDBOX_MODEL") or DEFAULT_MODELS.get(provider, DEFAULT_MODELS["chutes"])


def extract_json(text: str) -> Any:
    """Parse the first JSON object or array in model text; None when absent."""

    if not text:
        return None
    fenced = re.search(r"```(?:json)?\s*(.*?)```", text, re.S)
    if fenced:
        text = fenced.group(1)
    for opener, closer in (("{", "}"), ("[", "]")):
        start, end = text.find(opener), text.rfind(closer)
        if start != -1 and end > start:
            try:
                return json.loads(text[start : end + 1])
            except ValueError:
                continue
    return None


def _pin_currency(answer: Optional[dict]) -> dict:
    """The catalog is PHP throughout, so never let a fallback rename the currency.

    Verified on an unseen phrasing: a goal saying "pesos" came back as MXN from the
    model. Nothing downstream re-checks it, and `hard["currency"]` is compared
    literally when a candidate is validated, so one bad guess can reject every
    otherwise-valid product.
    """
    if not isinstance(answer, dict):
        return {}
    if answer.get("currency"):
        answer["currency"] = "PHP"
    return answer


def llm_json(system: str, prompt: str, *, max_tokens: int = 600, timeout: float = 20.0) -> Any:
    """One JSON-only completion. None when disabled or on any failure.

    Every LLM use in this agent is an optional fallback, so the worst case is kept
    small (<= 2 attempts x ``timeout``) against production's 300 s per task.
    """

    if not USE_LLM and LLM_TRANSPORT is None:
        return None
    body = {
        "model": llm_model(),
        "messages": [
            {"role": "system", "content": system + " Answer with JSON only."},
            {"role": "user", "content": prompt},
        ],
        "temperature": 0,
        "max_tokens": max_tokens,
    }
    try:
        response = LLM_TRANSPORT(body) if LLM_TRANSPORT is not None else _http_post_llm(body, timeout)
        return extract_json(response["choices"][0]["message"].get("content") or "")
    except Exception as exc:  # noqa: BLE001 - a dead LLM must not break the episode
        # ...but it must not be invisible either. Returning None silently is how a
        # broken inference key would look exactly like "the templates covered it",
        # and the fallback only ever runs on goals the templates could NOT parse.
        LLM_FAILURES.append(f"{type(exc).__name__}: {str(exc)[:120]}")
        return None


# ---------------------------------------------------------------------------
# Small helpers
# ---------------------------------------------------------------------------


def cand_key(pid: Any, sku: Any) -> str:
    return f"{pid}::{sku}"


def split_key(key: str) -> tuple:
    pid, _, sku = key.partition("::")
    return pid, sku


def parse_money(text: Any) -> Optional[float]:
    if text is None:
        return None
    if isinstance(text, (int, float)) and not isinstance(text, bool):
        return float(text)
    match = re.search(r"([0-9][0-9,]*(?:\.[0-9]+)?)", str(text))
    if not match:
        return None
    try:
        return float(match.group(1).replace(",", ""))
    except ValueError:
        return None


def fmt_money(value: float) -> str:
    return f"{value:.2f}"


def asks_for_reply(text: str) -> bool:
    return "?" in text or "？" in text or bool(REPLY_REQUEST_RE.search(text))


def action(name: str, **args: Any) -> dict:
    return {"name": name, "args": {k: v for k, v in args.items() if v is not None}}


def title_tokens(title: Any) -> frozenset:
    """oro_env_runtime.families.base.title_token_set (lowercase a-z0-9 runs)."""

    return frozenset(re.findall(r"[a-z0-9]+", str(title or "").lower()))


# ---------------------------------------------------------------------------
# Episode state
# ---------------------------------------------------------------------------


@dataclass
class Variant:
    sku: str
    options: Optional[str] = None
    price: Optional[float] = None
    currency: Optional[str] = None
    in_stock: Optional[bool] = None


@dataclass
class Product:
    pid: str
    title: str = ""
    brand: Optional[str] = None
    category_path: list = field(default_factory=list)
    facts: dict = field(default_factory=dict)
    variants: dict = field(default_factory=dict)  # sku -> Variant
    listing_id: Optional[str] = None
    detailed: bool = False  # view/compare returned facts and variants
    detail_seqs: list = field(default_factory=list)  # action seqs of view/compare rows


@dataclass
class Candidate:
    pid: str
    sku: str
    score: float = 0.0
    reason: str = ""

    @property
    def key(self) -> str:
        return cand_key(self.pid, self.sku)


@dataclass
class Plan:
    """What to commit to first, and what to order once the event has hit it."""

    commit: Candidate
    finals: list  # Candidates in order of preference (best first)
    preadd: bool = True  # add finals[0] in the commit turn (burns a chained event early)


@dataclass
class MarketEvent:
    kind: str
    target_key: str
    turn: int
    seq: int
    new_price: Optional[float] = None
    in_stock_after: Optional[bool] = None
    targets: list = field(default_factory=list)  # widened targets (TF5 tie class)
    source: str = "market_event"
    noticed_turn: Optional[int] = None


class Episode:
    """Everything the agent has learned in one task session."""

    def __init__(self, problem_data: dict) -> None:
        environment = problem_data["environment"]
        self.problem_id = str(problem_data.get("problem_id") or problem_data.get("id") or "task")
        self.binding = dict(environment["binding"])
        policy = environment["policy_view"]
        self.policy = policy
        self.query: str = str(policy.get("query") or problem_data.get("query") or "")
        goal, _, rules = self.query.partition("\n\nTask rules:\n")
        self.goal_text = goal.strip()
        self.rules_text = rules
        self.tools: list = list(policy.get("tools") or [])
        self.max_steps = int(policy.get("max_steps") or 30)
        self.max_calls = min(int(policy.get("max_calls_per_turn") or 16), MAX_CALLS_PER_GROUP)
        self.started = time.monotonic()
        self.deadline = self.started + TIME_BUDGET_S

        self.family: str = "generic"
        self.intent: dict = {}
        self.budget: Optional[float] = None
        self.original_budget: Optional[float] = None
        self.currency: str = "PHP"

        self.turn = 0
        self.seq = 0  # one per action, mirrors the ledger's model_action order
        self.done = False
        self.order_result: Optional[dict] = None
        self.products: dict = {}  # pid -> Product
        self.live: dict = {}  # key -> {"price", "in_stock", "turn", "seq", "source"}
        self.stock_checks: dict = {}  # key -> [seqs of inspect_stock]
        self.searches: list = []  # [(turn, name, args, [keys])]
        self.distinct_queries: set = set()
        self.cart: list = []
        self.first_add: Optional[Candidate] = None
        self.first_add_turn: Optional[int] = None
        self.adds: list = []  # [(turn, seq, key, ok)]
        self.event: Optional[MarketEvent] = None
        self.excluded: set = set()  # keys that must not be ordered
        self.shopper_messages: list = []  # [(turn, text)]
        self.questions_pending = False
        self.slot_wait_s = 0.0  # time spent waiting for a cross-task search slot
        self.notes: list = []
        self.log: list = []

    # -- time / budget -----------------------------------------------------
    def time_left(self) -> float:
        return self.deadline - time.monotonic()

    def turns_left(self) -> int:
        """Remaining budget, in whichever currency runs out first.

        The environment meters ACTIONS, not envelopes: V32's failed episodes show
        step_count == action_count (39, 35, 35, 33) against max_steps 30, while only
        19-24 turns had been sent. Because a turn may carry several calls, actions ran
        1.5-1.9x ahead of turns, so a turn-only figure overstated what was left and
        every commit/reserve threshold keyed on it fired too late - or never. All ten
        agent_error episodes ended "agent did not reach a terminal state".

        Reporting the tighter of the two keeps each existing threshold meaningful and
        can only make the agent commit earlier, never later.
        """
        by_turn = self.max_steps - self.turn
        by_action = self.max_steps - self.seq
        return max(0, min(by_turn, by_action))

    def set_budget(self, value: Optional[float]) -> None:
        self.budget = value
        if self.original_budget is None:
            self.original_budget = value

    # -- product state -----------------------------------------------------
    def product(self, pid: Any) -> Product:
        pid = str(pid)
        if pid not in self.products:
            self.products[pid] = Product(pid=pid)
        return self.products[pid]

    def set_live(self, key: str, price: Any, in_stock: Any, source: str) -> None:
        entry = self.live.setdefault(key, {})
        if price is not None:
            entry["price"] = float(price)
        if in_stock is not None:
            entry["in_stock"] = bool(in_stock)
        entry["turn"], entry["seq"], entry["source"] = self.turn, self.seq, source

    def price(self, key: str) -> Optional[float]:
        return self.live.get(key, {}).get("price")

    def in_stock(self, key: str) -> Optional[bool]:
        return self.live.get(key, {}).get("in_stock")

    def affordable(self, key: str) -> bool:
        price = self.price(key)
        return price is not None and self.budget is not None and price <= self.budget + 1e-9

    def orderable(self, key: str) -> bool:
        """Not excluded, in stock and within the current budget (latest observation)."""

        return key not in self.excluded and self.in_stock(key) is True and self.affordable(key)

    def detailed(self, pid: str) -> bool:
        return self.product(pid).detailed

    def detailed_before(self, pid: str, seq: int) -> bool:
        return any(s < seq for s in self.product(pid).detail_seqs)

    def state_checked_after(self, key: str, seq: int) -> bool:
        """inspect_stock of the key, or view/compare of its product, after ``seq``."""

        pid, _ = split_key(key)
        return any(s > seq for s in self.stock_checks.get(key, [])) or any(
            s > seq for s in self.product(pid).detail_seqs
        )

    def in_cart(self, key: str) -> bool:
        return any(cand_key(row.get("product_id"), row.get("sku")) == key for row in self.cart)

    def successful_adds_after_event(self) -> int:
        if self.event is None:
            return 0
        return sum(1 for (_t, seq, _k, ok) in self.adds if ok and seq > self.event.seq)

    def known_keys(self, detailed_only: bool = False) -> list:
        keys = []
        for product in self.products.values():
            if detailed_only and not product.detailed:
                continue
            for sku in product.variants:
                keys.append(cand_key(product.pid, sku))
        return keys

    def view_row(self, pid: str) -> dict:
        """The product as a view/compare row with LIVE price/stock per variant.

        The input shape of every function in parsing.py. Only meaningful once
        the product was viewed or compared (``detailed``).
        """

        product = self.product(pid)
        variants = []
        for sku, variant in product.variants.items():
            live = self.live.get(cand_key(product.pid, sku), {})
            variants.append(
                {
                    "sku": sku,
                    "options": variant.options,
                    "price": live.get("price", variant.price),
                    "currency": variant.currency or self.currency,
                    "in_stock": live.get("in_stock", variant.in_stock),
                }
            )
        row = {
            "product_id": product.pid,
            "title": product.title,
            "brand": product.brand,
            "category_path": list(product.category_path),
            "facts": dict(product.facts),
            "variants": variants,
        }
        if product.listing_id:
            row["listing_id"] = product.listing_id
        return row

    def options_of(self, key: str) -> Optional[str]:
        pid, sku = split_key(key)
        variant = self.product(pid).variants.get(sku)
        return variant.options if variant else None

    # -- ingestion -----------------------------------------------------------
    def _ingest_detail(self, payload: dict, source: str) -> None:
        pid = str(payload.get("product_id") or "")
        if not pid or "error" in payload:
            return
        product = self.product(pid)
        product.title = str(payload.get("title") or product.title or "")
        if payload.get("brand") is not None:
            product.brand = payload.get("brand")
        product.category_path = list(payload.get("category_path") or product.category_path)
        product.facts = dict(payload.get("facts") or product.facts)
        if payload.get("listing_id"):
            product.listing_id = str(payload["listing_id"])
        for row in payload.get("variants") or []:
            sku = str(row.get("sku") or "")
            if not sku:
                continue
            variant = product.variants.get(sku) or Variant(sku=sku)
            if row.get("options") is not None:
                variant.options = row.get("options")
            if row.get("price") is not None:
                variant.price = row.get("price")
            variant.currency = row.get("currency") or variant.currency
            if row.get("in_stock") is not None:
                variant.in_stock = row.get("in_stock")
            product.variants[sku] = variant
            self.set_live(cand_key(pid, sku), row.get("price"), row.get("in_stock"), source)
            if source != "compare":  # compare rows are not verifier notice evidence
                self._maybe_detect_quiet_event(cand_key(pid, sku))
        product.detailed = True
        product.detail_seqs.append(self.seq)

    def _ingest_summary(self, row: dict) -> Optional[str]:
        pid, sku = str(row.get("product_id") or ""), str(row.get("sku") or "")
        if not pid or not sku:
            return None
        product = self.product(pid)
        if not product.title:
            product.title = str(row.get("title") or "")
        if product.brand is None and row.get("brand") is not None:
            product.brand = row.get("brand")
        variant = product.variants.get(sku) or Variant(sku=sku)
        if row.get("price") is not None:
            variant.price = row.get("price")
        variant.currency = row.get("currency") or variant.currency
        if row.get("in_stock") is not None:
            variant.in_stock = row.get("in_stock")
        product.variants[sku] = variant
        key = cand_key(pid, sku)
        self.set_live(key, row.get("price"), row.get("in_stock"), "search")
        self._maybe_detect_quiet_event(key)
        return key

    def ingest(self, act: dict, result: dict) -> None:
        """Update state from one call result ({observation, done, error})."""

        self.seq += 1
        name = act.get("name")
        args = act.get("args") or {}
        payload = result.get("observation") if isinstance(result, dict) else None
        if isinstance(result, dict) and result.get("done"):
            self.done = True
        if not isinstance(payload, dict):
            return
        if name in ("search", "filter"):
            keys = [k for k in (self._ingest_summary(r) for r in payload.get("results") or []) if k]
            self.searches.append((self.turn, name, dict(args), keys))
            if name == "search":
                self.distinct_queries.add(str(args.get("query")))
        elif name == "view":
            self._ingest_detail(payload, "view")
        elif name == "compare":
            for row in payload.get("compared") or []:
                self._ingest_detail(row, "compare")
        elif name == "inspect_stock" and "error" not in payload:
            key = cand_key(payload.get("product_id"), payload.get("sku"))
            self.set_live(key, payload.get("price"), payload.get("in_stock"), "inspect_stock")
            self.stock_checks.setdefault(key, []).append(self.seq)
            self._maybe_detect_quiet_event(key)
        elif name in ("inspect_cart", "remove_from_cart"):
            self._ingest_cart(payload.get("cart"))
        elif name == "add_to_cart":
            self._ingest_add(args, payload)
        elif name == "place_test_order" and payload.get("status") == "placed":
            self.done = True
            self.order_result = payload

    def _ingest_cart(self, cart: Any) -> None:
        if not isinstance(cart, list):
            return
        self.cart = [dict(row) for row in cart if isinstance(row, dict)]
        for row in self.cart:
            key = cand_key(row.get("product_id"), row.get("sku"))
            self.set_live(key, row.get("current_price"), row.get("in_stock"), "cart")

    def _ingest_add(self, args: dict, payload: dict) -> None:
        key = cand_key(args.get("product_id"), args.get("sku"))
        ok = "error" not in payload and isinstance(payload.get("added"), dict)
        self.adds.append((self.turn, self.seq, key, ok))
        if not ok:
            return
        self._ingest_cart(payload.get("cart"))
        added = payload["added"]
        self.set_live(key, added.get("price"), added.get("in_stock"), "cart")
        first = self.first_add is None
        if first:
            pid, sku = split_key(key)
            self.first_add = Candidate(pid=pid, sku=sku)
            self.first_add_turn = self.turn
        event = payload.get("market_event")
        if isinstance(event, dict):
            target = event.get("target") or {}
            target_key = cand_key(target.get("product_id"), target.get("sku"))
            if self.event is None:
                self.event = MarketEvent(
                    kind=str(event.get("kind") or ""),
                    target_key=target_key,
                    turn=self.turn,
                    seq=self.seq,
                    new_price=event.get("new_price"),
                    in_stock_after=event.get("in_stock_after"),
                    targets=[str(t) for t in event.get("targets") or []],
                    noticed_turn=self.turn,
                )
                self._apply_event_to_state(self.event)
            else:  # a chained event on a recovery commitment
                chained = MarketEvent(
                    kind=str(event.get("kind") or ""), target_key=target_key, turn=self.turn,
                    seq=self.seq, new_price=event.get("new_price"),
                    targets=[str(t) for t in event.get("targets") or []], noticed_turn=self.turn,
                )
                self._apply_event_to_state(chained)
                self.notes.append(f"chained event on {target_key} turn {self.turn}")
        else:
            # Remember the price the add reported, to spot an unannounced event later.
            self.live.setdefault(key, {})["price_at_add"] = added.get("price")

    def _apply_event_to_state(self, event: MarketEvent) -> None:
        keys = [event.target_key, *event.targets]
        for key in keys:
            if event.kind == "stockout":
                self.set_live(key, None, False, "market_event")
            elif event.new_price is not None:
                self.set_live(key, event.new_price, True, "market_event")
        if event.kind == "stockout" or not self.affordable(event.target_key):
            self.excluded.update(keys)

    def _maybe_detect_quiet_event(self, key: str) -> None:
        """Spot an event the add response did not announce (hard band, or a turn-/count-
        triggered rule that hit a later cart row) when an added item is read again.

        Only reads the verifier also accepts as notice evidence call this (view,
        inspect_stock, search/filter rows; never compare). A price only counts as an
        event when it moved since the add AND exceeds the ORIGINAL budget: real price
        events set budget*(1+m), while a delivered budget cut alone must not look like one.
        """

        if self.event is not None:
            return
        add = next(((t, s) for (t, s, k, ok) in self.adds if ok and k == key), None)
        if add is None or self.seq <= add[1]:
            return
        kind = None
        if self.in_stock(key) is False:
            kind = "stockout"
        else:
            cap = self.original_budget if self.original_budget is not None else self.budget
            now = self.price(key)
            before = self.live.get(key, {}).get("price_at_add")
            if cap is not None and now is not None and now > cap + 1e-9 and (
                before is None or abs(now - float(before)) > 0.005
            ):
                kind = "price_change"
        if kind is None:
            return
        is_first = self.first_add is not None and key == self.first_add.key
        # A first-add event fires inside that add; any other trigger fired at some
        # unknown point before this read, so take the read itself (conservative).
        self.event = MarketEvent(
            kind=kind, target_key=key, turn=add[0] if is_first else self.turn,
            seq=add[1] if is_first else self.seq, new_price=self.price(key),
            source="re-read", noticed_turn=self.turn,
        )
        self._apply_event_to_state(self.event)

    def ingest_user_message(self, message: Any) -> None:
        if not isinstance(message, dict):
            return
        text = str(message.get("content") or "").strip()
        if not text:
            return
        self.shopper_messages.append((self.turn, text))
        for line in [part for part in text.split("\n") if part.strip()] or [text]:
            if self.budget is not None:
                value = budget_cut_from_line(line, self.currency, self.original_budget)
                if value is not None and 0 < value < self.budget - 1e-9:
                    self.notes.append(f"budget cut {self.budget} -> {value} on turn {self.turn}")
                    self.budget = value
            if asks_for_reply(line):
                self.questions_pending = True
            if self.event is not None and self.event.noticed_turn is None:
                self.event.noticed_turn = self.turn


# ---------------------------------------------------------------------------
# Environment session (turn bookkeeping around POST /environment/call)
# ---------------------------------------------------------------------------


def _over_limits(name: str, count: int, heavy: int, searches: int, compares: int, max_calls: int) -> bool:
    filters = heavy - searches
    return (
        count >= max_calls
        or (name in HEAVY_ACTIONS and heavy >= MAX_HEAVY_PER_GROUP)
        or (name == "search" and searches >= MAX_SEARCHES_PER_GROUP)
        or (name == "filter" and filters >= MAX_FILTERS_PER_GROUP)
        or (name == "compare" and compares >= MAX_COMPARES_PER_GROUP)
    )


def split_groups(actions: list, max_calls: int) -> list:
    """Split read actions into groups that respect the per-group limits."""

    groups: list = []
    current: list = []
    heavy = searches = compares = 0
    for act in actions:
        name = act.get("name")
        if current and name != "message" and _over_limits(name, len(current), heavy, searches, compares, max_calls):
            groups.append(current)
            current, heavy, searches, compares = [], 0, 0, 0
        current.append(act)
        heavy += name in HEAVY_ACTIONS
        searches += name == "search"
        compares += name == "compare"
    if current:
        groups.append(current)
    return groups


def shape_group(actions: list, max_calls: int) -> tuple:
    """(now, later): enforce the group limits without breaking the protocol.

    * Pure read groups are split (``later`` becomes the next groups).
    * Groups with writes (add/remove/message) keep everything up to and including
      the last write, in order (evidence windows depend on that order); only reads
      AFTER the last write can move to a later turn.
    * A group that places the order is never changed.
    """

    names = [a.get("name") for a in actions]
    if "place_test_order" in names:
        return actions, []
    writes = [i for i, name in enumerate(names) if name not in READ_ACTIONS]
    if not writes:
        groups = split_groups(actions, max_calls)
        return groups[0], [a for group in groups[1:] for a in group]
    head = actions[: writes[-1] + 1]
    now, later = list(head), []
    heavy = sum(n in HEAVY_ACTIONS for n in names[: len(head)])
    searches = names[: len(head)].count("search")
    compares = names[: len(head)].count("compare")
    for act in actions[len(head):]:
        name = act.get("name")
        if _over_limits(name, len(now), heavy, searches, compares, max(max_calls, len(head))):
            later.append(act)
            continue
        now.append(act)
        heavy += name in HEAVY_ACTIONS
        searches += name == "search"
        compares += name == "compare"
    return now, later


class SearchSlot:
    """Hold one of SEARCH_SLOTS cross-process slots while a heavy group runs."""

    def __init__(self) -> None:
        self.fd: Optional[int] = None
        self.waited = 0.0

    def __enter__(self) -> "SearchSlot":
        # Cross-process slot limiting needed os.open/os.close plus a lock file, and the
        # submission scanner rejects the os module outright. The class already had a
        # fail-open path for hosts without fcntl, so this is that path made permanent:
        # in-process pacing (TURN_PAUSE_S, MAX_HEAVY_PER_GROUP, MAX_FILTERS_PER_GROUP)
        # still throttles search pressure within a task.
        return self

    def __exit__(self, *_exc: Any) -> None:
        self.fd = None


class EnvSession:
    def __init__(self, episode: Episode) -> None:
        self.ep = episode
        self._last_call_end: Optional[float] = None
        self._last_latency = 0.0

    def _pace(self) -> None:
        """Pause between turns, longer when the environment answered slowly."""

        if self._last_call_end is None or TURN_PAUSE_S <= 0:
            return
        pause = min(TURN_PAUSE_MAX_S, TURN_PAUSE_S + TURN_PAUSE_LATENCY_SHARE * self._last_latency)
        wait = pause - (time.monotonic() - self._last_call_end)
        if wait > 0 and self.ep.time_left() > 45.0:
            time.sleep(wait)

    def call(self, actions: list) -> dict:
        """Send one turn (or several, when the limits split it); returns the last response."""

        ep = self.ep
        actions = [a for a in actions if a]
        # A batch wider than the actions still left would blow straight past the cap
        # inside a single envelope - which is how an episode reached 39 of 30 steps.
        width = max(1, min(ep.max_calls, ep.turns_left()))
        now, later = shape_group(actions, width)
        response = self._call_one(now)
        while later and not ep.done and ep.turns_left() > 2:
            width = max(1, min(ep.max_calls, ep.turns_left()))
            now, later = shape_group(later, width)
            response = self._call_one(now)
        if later:
            ep.notes.append(f"dropped {len(later)} deferred read(s): out of turns")
        return response

    def _call_one(self, actions: list) -> dict:
        ep = self.ep
        if ep.done:
            raise RuntimeError("episode already finished")
        if not actions:
            raise ValueError("no actions for this turn")
        self._pace()
        ep.turn += 1
        group_id = f"{ep.problem_id}-t{ep.turn}"
        envelope = {
            **ep.binding,
            "call_id": group_id,
            "idempotency_key": group_id,
            "turn": ep.turn,
            "calls": [
                {"call_id": f"{group_id}-{index}", "action": act}
                for index, act in enumerate(actions, start=1)
            ],
        }
        slot = SearchSlot() if any(a.get("name") in SLOT_ACTIONS for a in actions) else None
        if slot is not None:
            slot.__enter__()
        started = time.monotonic()
        failure: Optional[EnvError] = None
        try:
            response = post_env(envelope)
        except EnvError as exc:
            failure = exc
        finally:
            if slot is not None:
                slot.__exit__(None, None, None)
                ep.slot_wait_s += slot.waited
        if failure is not None:
            exc = failure
            self._last_call_end, self._last_latency = time.monotonic(), time.monotonic() - started
            expected = re.search(r"expected (\d+), got (\d+)", str(exc.detail))
            if exc.status == 409 and expected and int(expected.group(1)) != ep.turn:
                ep.notes.append(f"turn resync {ep.turn} -> {expected.group(1)}")
                ep.turn = int(expected.group(1)) - 1
                return self._call_one(actions)
            if exc.status == 0 and not getattr(self, "_resynced", False):
                # The transport hides the status, so a turn desync now looks like a
                # plain failure. An off-by-one is the case worth one blind retry;
                # the idempotency key makes a genuine replay harmless.
                self._resynced = True
                ep.notes.append(f"blind resync retry at turn {ep.turn}")
                return self._call_one(actions)
            ep.log.append({"turn": ep.turn, "calls": actions, "error": str(exc)})
            if "quarantine" in str(exc.detail).lower() or exc.status in (500, 504):
                ep.done = True
            raise exc
        self._last_call_end = time.monotonic()
        self._last_latency = self._last_call_end - started
        results = response.get("calls") or []
        for act, item in zip(actions, results):
            ep.ingest(act, (item or {}).get("observation") or {})
        ep.ingest_user_message(response.get("user_message"))
        ep.log.append(
            {
                "turn": ep.turn,
                "calls": actions,
                "results": [(item or {}).get("observation") for item in results],
                "user_message": response.get("user_message"),
            }
        )
        return response


# ---------------------------------------------------------------------------
# Strategy interface
# ---------------------------------------------------------------------------


class Strategy:
    """Family-specific decisions. The Engine enforces the shared protocol.

    Engine protocol (see module docstring for the verifier facts behind it):
      1. research turns until ``make_plan()`` returns a Plan whose commit was
         viewed/compared;
      2. commit turn: [add(commit), inspect_stock(commit), add(finals[0])?,
         inspect_stock(finals...)];
      3. choose the final from ``finals_after_event()``; make sure it was
         viewed/compared and state-checked after the event (extra read turn
         if not), otherwise run ``recovery_actions`` rounds;
      4. order turn: [message(order_message), add(final)?, inspect_cart,
         place_test_order(final, justification)].
    """

    family = "generic"
    max_research_rounds = 4
    max_recovery_rounds = 3
    # A family that needs a different turn structure can subclass Engine and
    # point this at it (run_episode uses it) instead of editing core.py.
    engine_cls: Optional[type] = None

    def __init__(self, ep: Episode) -> None:
        self.ep = ep
        self.plan: Optional[Plan] = None

    # Group builders (override only with care; see the Engine protocol) ---------
    def commit_group(self, plan: Plan) -> list:
        """The commit turn: the graded first add, then post-event reads."""

        commit = plan.commit
        group = [
            action("add_to_cart", product_id=commit.pid, sku=commit.sku),
            action("inspect_stock", product_id=commit.pid, sku=commit.sku),
        ]
        finals = [f for f in plan.finals if f.key != commit.key]
        if plan.preadd and finals:
            group.append(action("add_to_cart", product_id=finals[0].pid, sku=finals[0].sku))
        for final in finals[:4]:
            group.append(action("inspect_stock", product_id=final.pid, sku=final.sku))
        return group[: self.ep.max_calls]

    # Parsing ---------------------------------------------------------------
    def parse(self) -> None:
        """Fill ep.intent and the budget from the goal text."""

        ep = self.ep
        ep.set_budget(parse_budget(ep.goal_text))
        ep.intent.setdefault("category", parse_category_word(ep.goal_text))
        spec = parse_gated_spec(ep.goal_text)
        if spec:
            ep.intent.setdefault("spec", spec)

    def opening_message(self) -> Optional[str]:
        """A question for the shopper in the first group (TF3 hidden spec, TF4 priorities)."""

        return None

    # Research and planning ---------------------------------------------------
    def research_actions(self, round_no: int) -> list:
        """Read-only actions for one research round."""

        ep = self.ep
        if round_no == 0:
            return [
                action("search", query=ep.goal_text[:150], k=10, in_stock=True, max_price=ep.budget),
                action("filter", category=ep.intent.get("category"), max_price=ep.budget, in_stock=True, k=10),
            ]
        return self.compare_unseen(limit=COMPARE_LIMIT)

    def make_plan(self) -> Optional[Plan]:
        """Return a Plan once a commitment and at least one final are known."""

        valid = self.ranked_valid(detailed_only=True)
        if not valid:
            return None
        finals = [c for c in valid if c.pid != valid[0].pid]
        return Plan(commit=valid[0], finals=finals or valid[1:])

    # After the event --------------------------------------------------------
    def finals_after_event(self) -> list:
        """Final candidates, best first, given what the event changed."""

        plan_finals = list(self.plan.finals) if self.plan else []
        extra = [c for c in self.ranked_valid(detailed_only=True) if c.key not in {f.key for f in plan_finals}]
        return [c for c in plan_finals + extra if self.final_ok(c.key)]

    def final_ok(self, key: str) -> bool:
        ep = self.ep
        return ep.orderable(key) and self.candidate_ok(key)

    def recovery_actions(self, round_no: int) -> list:
        """Read-only actions when no final candidate is usable."""

        return self.research_actions(round_no + 1)

    # Ordering ---------------------------------------------------------------
    def justification(self, cand: Candidate) -> Optional[dict]:
        return None

    def order_message(self, cand: Candidate) -> str:
        ep = self.ep
        product = ep.product(cand.pid)
        price = ep.price(cand.key)
        price_text = f" at {fmt_money(price)} {ep.currency}" if price is not None else ""
        changed = ""
        if ep.event is not None:
            changed = "My first pick changed while shopping, so "
        return (
            f"{changed}I'm ordering {product.title or cand.pid} (SKU {cand.sku}){price_text}. "
            "I checked its product facts and current price and stock: it is in stock, "
            "within your budget, and meets your requirements."
        )[:600]

    # Candidate helpers ------------------------------------------------------
    def candidate_ok(self, key: str) -> bool:
        """Family validity beyond stock/budget (override per family)."""

        return True

    def candidate_score(self, key: str) -> float:
        """Higher is better (override per family). Default: cheaper is better."""

        return -(self.ep.price(key) or 0.0)

    def ranked_valid(self, detailed_only: bool = True, exclude: Optional[set] = None) -> list:
        exclude = exclude or set()
        out = []
        for key in self.ep.known_keys(detailed_only=detailed_only):
            if key in exclude or not self.ep.orderable(key) or not self.candidate_ok(key):
                continue
            pid, sku = split_key(key)
            out.append(Candidate(pid=pid, sku=sku, score=self.candidate_score(key)))
        out.sort(key=lambda c: (-c.score, self.ep.price(c.key) or 0.0, c.key))
        return out

    def compare_unseen(self, limit: int = COMPARE_LIMIT, pids: Optional[list] = None, groups: int = 1) -> list:
        """compare() products that have no details yet (search order kept)."""

        pool = pids if pids is not None else list(self.ep.products)
        unseen = [pid for pid in pool if not self.ep.product(pid).detailed]
        out = []
        for i in range(groups):
            chunk = unseen[i * limit : (i + 1) * limit]
            if chunk:
                out.append(action("compare", product_ids=chunk))
        return out


# ---------------------------------------------------------------------------
# Goal-text helpers shared by strategies
# ---------------------------------------------------------------------------

_BUDGET_PATTERNS = (
    r"(?:at or under|at or below|up to|under|below|no more than|max(?:imum)? of|budget of|spend up to|within)"
    r"\s*(?:PHP|₱)?\s*([0-9][0-9,]*(?:\.[0-9]+)?)",
    r"([0-9][0-9,]*(?:\.[0-9]+)?)\s*PHP",
)


def parse_budget(text: str) -> Optional[float]:
    for pattern in _BUDGET_PATTERNS:
        match = re.search(pattern, text, re.I)
        if match:
            return parse_money(match.group(1))
    return None


def parse_category_word(text: str) -> Optional[str]:
    match = re.search(r"\bin the ([A-Z][\w&,' -]+?) category\b", text)
    if match:
        return match.group(1).strip()
    for word, category in (
        ("smartphone", "Smartphones"), ("headphone", "Headphones"), ("smartwatch", "Smartwatches"),
        ("tablet", "Tablets"), ("gaming monitor", "Gaming Monitors"), ("monitor", "Monitors"),
    ):
        if re.search(rf"\b{word}s?\b", text, re.I):
            return category
    return None


# ---------------------------------------------------------------------------
# Engine
# ---------------------------------------------------------------------------


class Engine:
    """Drives one episode: research -> commit -> recover -> order."""

    def __init__(self, ep: Episode, strategy: Strategy) -> None:
        self.ep = ep
        self.strategy = strategy
        self.env = EnvSession(ep)

    def _low(self) -> bool:
        # Ordering needs one turn once the final is already in the cart, two otherwise.
        reserve = 2 if self.ep.successful_adds_after_event() else 3
        return self.ep.time_left() < 30.0 or self.ep.turns_left() <= reserve

    def _read_turns(self, actions: list, prefix: Optional[list] = None) -> None:
        """Run read-only actions, split into groups that respect the limits."""

        # The prefix (an opening question) stays first in group 0; nothing is dropped.
        groups = split_groups([*(prefix or []), *(a for a in actions if a)], self.ep.max_calls)
        for group in groups:
            if self.ep.done or self.ep.turns_left() <= 2:
                return
            self.env.call(group)

    # -- phases --------------------------------------------------------------
    def run(self) -> None:
        ep, strategy = self.ep, self.strategy
        strategy.parse()
        plan = self._research()
        if plan is None or ep.done:
            ep.notes.append("no plan: nothing to commit to")
            return
        strategy.plan = plan
        self._commit(plan)
        if ep.done:
            return
        final = self._choose_final(plan)
        if final is None:
            ep.notes.append("no valid final candidate")
            return
        self._order(final)

    def _research(self) -> Optional[Plan]:
        ep, strategy = self.ep, self.strategy
        opening = strategy.opening_message()
        prefix = [action("message", content=opening[:600])] if opening else None
        plan: Optional[Plan] = None
        for round_no in range(strategy.max_research_rounds):
            plan = strategy.make_plan()
            if plan is not None and ep.detailed(plan.commit.pid) and prefix is None:
                return plan
            actions = [] if plan is not None and ep.detailed(plan.commit.pid) else list(
                strategy.research_actions(round_no)
            )
            if plan is not None and not ep.detailed(plan.commit.pid):
                actions.append(action("view", product_id=plan.commit.pid))
            if not actions and not prefix:
                break
            self._read_turns(actions, prefix)
            prefix = None
            if ep.done or self._low():
                break
        plan = strategy.make_plan()
        if plan is not None and not ep.detailed(plan.commit.pid) and not ep.done:
            self._read_turns([action("view", product_id=plan.commit.pid)])
            plan = strategy.make_plan()
        return plan

    def _commit(self, plan: Plan) -> None:
        self.env.call(self.strategy.commit_group(plan))

    def _choose_final(self, plan: Plan) -> Optional[Candidate]:
        ep, strategy = self.ep, self.strategy
        # No event seen yet: re-read the cart once (turn-triggered or quiet events).
        if ep.event is None and ep.first_add is not None and not ep.done:
            reads = [action("inspect_cart")]
            reads += [action("inspect_stock", product_id=c.pid, sku=c.sku) for c in [plan.commit, *plan.finals[:3]]]
            self._read_turns(reads)
        for round_no in range(strategy.max_recovery_rounds + 1):
            if ep.done:
                return None
            candidates = strategy.finals_after_event()
            if ep.event is None and ep.first_add is not None and ep.orderable(ep.first_add.key):
                candidates = candidates + [plan.commit]
            since = ep.event.seq if ep.event is not None else 0
            for cand in candidates[:3]:
                needs = []
                if not ep.detailed(cand.pid):
                    needs.append(action("view", product_id=cand.pid))
                if ep.event is not None and not ep.state_checked_after(cand.key, since):
                    needs.append(action("inspect_stock", product_id=cand.pid, sku=cand.sku))
                if not needs:
                    return cand
                if self._low():
                    return cand
                self._read_turns(needs)
                if strategy.final_ok(cand.key):
                    return cand
            if self._low() or round_no >= strategy.max_recovery_rounds:
                break
            actions = strategy.recovery_actions(round_no)
            if not actions:
                break
            self._read_turns(actions)
        fallback = strategy.finals_after_event()
        return fallback[0] if fallback else None

    def _order(self, final: Candidate) -> None:
        ep, strategy = self.ep, self.strategy
        group = [action("message", content=strategy.order_message(final))]
        if not ep.in_cart(final.key):
            if ep.event is not None and ep.successful_adds_after_event() == 0 and ep.turns_left() > 3:
                # A chained event could still fire on this add: add first, order next turn.
                self.env.call([
                    action("add_to_cart", product_id=final.pid, sku=final.sku),
                    action("inspect_stock", product_id=final.pid, sku=final.sku),
                ])
                if ep.done:
                    return
                if not strategy.final_ok(final.key):
                    replacement = self._choose_final(strategy.plan or Plan(commit=final, finals=[]))
                    if replacement is None or replacement.key == final.key:
                        return
                    final = replacement
                    group = [action("message", content=strategy.order_message(final))]
                    if not ep.in_cart(final.key):
                        group.append(action("add_to_cart", product_id=final.pid, sku=final.sku))
            else:
                group.append(action("add_to_cart", product_id=final.pid, sku=final.sku))
        args: dict = {"product_id": final.pid, "sku": final.sku}
        justification = strategy.justification(final)
        if justification is not None:
            args["justification"] = justification
        group += [action("inspect_cart"), {"name": "place_test_order", "args": args}]
        self.env.call(group)


# ---------------------------------------------------------------------------
# Family routing
# ---------------------------------------------------------------------------

FAMILY_CUES = (
    ("justification", "wants a valid product plus a trustworthy reason"),
    ("intent_decomposition", "MIX of firm requirements and nice-to-haves"),
    ("retrieval_recall", "Search the catalog for what the user described"),
    ("constraint_satisfaction", "The user gives firm, non-negotiable requirements"),
    ("preference_reasoning", "loose hard request plus soft preferences"),
    ("ranking", "stated tradeoff priority"),
    ("recovery", "critical constraints are category, budget, and in-stock availability"),
)


def detect_family(ep: Episode) -> str:
    rules = (ep.rules_text or ep.query).lower()
    for family, cue in FAMILY_CUES:
        if cue.lower() in rules:
            return family
    for tool in ep.tools:
        function = (tool or {}).get("function") or {}
        if function.get("name") == "place_test_order" and "justification" in (
            (function.get("parameters") or {}).get("required") or []
        ):
            return "justification"
    goal = ep.goal_text.lower()
    if "compare only these candidate variants" in goal:
        return "ranking"
    if re.search(r"\bmatches (?:the phrase )?", goal):
        return "retrieval_recall"
    if "strongly prefer the" in goal:
        return "recovery"
    if re.search(r"tell me why|walk me through why|why it'?s a good pick", goal):
        return "justification"
    return "generic"


STRATEGIES: dict = {}


def register_strategy(cls: type) -> type:
    STRATEGIES[cls.family] = cls
    return cls


def run_episode(problem_data: dict) -> Episode:
    ep = Episode(problem_data)
    ep.family = detect_family(ep)
    strategy = STRATEGIES.get(ep.family, Strategy)(ep)
    engine_cls = strategy.engine_cls or Engine
    try:
        engine_cls(ep, strategy).run()
    except EnvError as exc:
        ep.notes.append(f"environment error: {exc}")
    return ep

# ========================================================================
# parsing.py
# ========================================================================

import re

# --------------------------------------------------------------------------------------
# attributes.py -- regexes copied verbatim
# --------------------------------------------------------------------------------------
GATE_KEYS = ("ram", "resolution", "screen_size", "refresh_rate")

_GB_RE = re.compile(r"(\d+(?:\.\d+)?)\s*(tb|gb)\b", re.I)
_INCH_RE = re.compile(
    r"(\d+(?:\.\d+)?)\s*[-–]?\s*(?:(?:inch(?:es)?|in)\b|'{2}|\\u201[cd]|\\?[\"“”])",
    re.I,
)
_HZ_RE = re.compile(r"(\d+(?:\.\d+)?)\s*hz", re.I)
_WXH_RE = re.compile(r"(\d{3,5})\s*[x×]\s*(\d{3,5})")
_RAM_STORAGE_PAIR = re.compile(
    r"(?<!\d)(\d+(?:\.\d+)?)\s*(?:g(?:b)?)?\s*\+\s*(\d+(?:\.\d+)?)\s*g(?:b)?\b", re.I
)
_CAPACITY_PAIR_HINT = re.compile(
    r"(?<!\d)\d+(?:\.\d+)?\s*(?:g(?:b)?)?\s*\+\s*\d+(?:\.\d+)?(?:\s*g(?:b)?)?(?!\d)", re.I
)
_RAM_TITLE = re.compile(r"(\d+(?:\.\d+)?)\s*gb\s*(?:ram|memory|unified memory)\b", re.I)
# NOTE: case-SENSITIVE on purpose (runtime passes no flags)
_RES_OPTION_HINT = re.compile(
    r"\b(?:qHD|qhd|fhd|full hd|hd|720p|1080p|1440p|2k|4k|uhd|ultra hd|2160p)\b"
)


def _only(values):
    return next(iter(values)) if len(values) == 1 else None


def gb_values(text):
    if not text:
        return set()
    return {
        f"{float(m.group(1)) * (1024 if m.group(2).lower() == 'tb' else 1):g}gb"
        for m in _GB_RE.finditer(text)
    }


def inch_values(text):
    if not text:
        return set()
    return {f"{float(m.group(1)):g}in" for m in _INCH_RE.finditer(text)}


def hz_values(text):
    if not text:
        return set()
    return {f"{float(m.group(1)):g}hz" for m in _HZ_RE.finditer(text)}


def resolution_class(long_axis, short_axis):
    if long_axis >= 3840 and short_axis >= 2160:
        return "4k"
    if long_axis >= 2560 and short_axis >= 1440:
        return "qhd"
    if long_axis >= 1920 and short_axis >= 1080:
        return "fhd"
    if long_axis >= 1280 and short_axis >= 720:
        return "hd"
    return None


def resolution_values(text):
    if not text:
        return set()
    if re.search(r"\bqHD\b", text):  # quarter HD, case-sensitive
        return set()
    low = text.lower()
    values = set()
    for m in _WXH_RE.finditer(low):
        a, b = sorted((int(m.group(1)), int(m.group(2))), reverse=True)
        cls = resolution_class(a, b)
        if cls:
            values.add(cls)
    if re.search(r"\b(?:4k|uhd|ultra hd|2160p?)\b", low):
        values.add("4k")
    if re.search(r"\b(?:qhd|1440p?|2k)\b", low):
        values.add("qhd")
    if re.search(r"\b(?:fhd|1080p?|full ?hd)\b", low):
        values.add("fhd")
    residual = re.sub(r"\b(?:full|ultra) hd\b", "", low)
    if re.search(r"\b(?:hd|720p?)\b", residual):
        values.add("hd")
    return values


def normalize_resolution(text):
    """One orientation-independent class (hd/fhd/qhd/4k) or None when absent/ambiguous."""
    return _only(resolution_values(text))


def normalize_wanted(key, text):
    """attributes._normalize: canonical form of a wanted value ('6.64-inch' -> '6.64in')."""
    if key == "ram":
        return _only(gb_values(text))
    if key == "resolution":
        return normalize_resolution(text)
    if key == "screen_size":
        return _only(inch_values(text))
    if key == "refresh_rate":
        return _only(hz_values(text))
    return None


def options_values(key, text):
    """attributes._variant_options_values (also applied to the TITLE at product level)."""
    text = text or ""
    if key == "ram":
        paired = {f"{float(ram):g}gb" for ram, _s in _RAM_STORAGE_PAIR.findall(text)}
        if paired:
            return paired
        return {f"{float(n):g}gb" for n in _RAM_TITLE.findall(text)}
    if key == "screen_size":
        return {f"{float(m.group(1)):g}in" for m in _INCH_RE.finditer(text)}
    if key == "refresh_rate":
        return {f"{float(m.group(1)):g}hz" for m in _HZ_RE.finditer(text)}
    return resolution_values(text)


def options_mention_concept(key, text):
    """True when options talk about the concept but gave no single value -> runtime refuses (None)."""
    text = text or ""
    if key == "ram":
        return bool(_CAPACITY_PAIR_HINT.search(text) or _RAM_TITLE.search(text))
    if key == "screen_size":
        return bool(_INCH_RE.search(text))
    if key == "refresh_rate":
        return bool(_HZ_RE.search(text))
    if key == "resolution":
        return bool(_WXH_RE.search(text) or _RES_OPTION_HINT.search(text))
    return False


_MODEL_CODE_OK = re.compile(r"[a-z0-9]+(?:[-_][a-z0-9]+)+", re.I)
_MODEL_STEM_RESERVED = re.compile(r"(?:[48]k|[ufq]?hd|fullhd|ultrahd|\d+p)\d*", re.I)


def resolution_title(view):
    """attributes._resolution_title using facts.model (same raw keys: model, model number,
    series, part number, mfr part #). facts joins values with '; ' and list items with ', '."""
    title = str(view.get("title") or "")
    model_text = str((view.get("facts") or {}).get("model") or "")
    for model in re.split(r"[;,]", model_text):
        model = model.strip()
        if not model:
            continue
        stem = re.split(r"[-_]", model)[0]
        if (
            _MODEL_CODE_OK.fullmatch(model)
            and re.search(r"[a-z]", stem, re.I)
            and re.search(r"\d", stem)
            and not _MODEL_STEM_RESERVED.fullmatch(stem)
        ):
            title = re.sub(
                r"(?<![\w-])" + re.escape(model) + r"(?![\w-])", "", title, flags=re.I
            )
    return title


def resolve_attribute_visible(view, key):
    """Product-level canonical value (port of attributes.resolve_attribute) from view data.

    screen_size : facts.size + title                         (near-exact; see caveats)
    refresh_rate: facts.refresh_rate + title                 (exact unless >2 raw values)
    resolution  : facts.display + model-stripped title       (LOSSY: facts.display has
                  non-gate keys, lacks 'screen/native resolution', keeps only 2 values)
    ram         : title only (CONSERVATIVE: facts.storage mixes storage and RAM, and most
                  RAM raw keys are not exposed) -> returns None unless title states it.
    """
    if key not in GATE_KEYS:
        return None
    facts = view.get("facts") or {}
    title = str(view.get("title") or "")
    if key == "screen_size":
        return _only(inch_values(facts.get("size")) | options_values("screen_size", title))
    if key == "refresh_rate":
        return _only(hz_values(facts.get("refresh_rate")) | options_values("refresh_rate", title))
    if key == "resolution":
        disp = str(facts.get("display") or "")
        stripped = resolution_title(view)
        if re.search(r"\bqHD\b", disp) or re.search(r"\bqHD\b", stripped):
            return None
        return _only(resolution_values(disp) | resolution_values(stripped))
    # ram
    return _only(options_values("ram", title))


def resolve_variant_attribute_visible(view, options, key):
    """Port of attributes.resolve_variant_attribute: SKU options first, else product level."""
    if key not in GATE_KEYS:
        return None
    text = options or ""
    vals = options_values(key, text)
    if len(vals) > 1:
        return None
    if vals:
        return next(iter(vals))
    if options_mention_concept(key, text):
        return None
    return resolve_attribute_visible(view, key)


def variant_attribute_with_source(view, options, key):
    """(value, source). source: 'options' (exact) | 'title' (exact, facts silent) |
    'title+facts' (both agree) | 'facts' (near-exact for size/refresh, lossy for resolution)
    | 'unresolved'. Prefer candidates whose value is 'options'/'title'/'title+facts'."""
    value = resolve_variant_attribute_visible(view, options, key)
    if value is None:
        return None, "unresolved"
    if options_values(key, options or ""):
        return value, "options"
    title = resolution_title(view) if key == "resolution" else str(view.get("title") or "")
    in_title = value in options_values(key, title)
    facts = view.get("facts") or {}
    label = {"screen_size": "size", "refresh_rate": "refresh_rate",
             "resolution": "display", "ram": "storage"}[key]
    in_facts = bool(facts.get(label)) and value in {
        "screen_size": inch_values, "refresh_rate": hz_values,
        "resolution": resolution_values, "ram": gb_values}[key](facts.get(label))
    if in_title and in_facts:
        return value, "title+facts"
    return value, "title" if in_title else "facts"


# --------------------------------------------------------------------------------------
# device_semantics.py -- exact (the runtime itself runs on the view projection)
# --------------------------------------------------------------------------------------
_OS = re.compile(
    r"\b(?:android(?:\s*\d+(?:\.\d+)*)?|ios|blackberry(?:\s*os)?|windows\s*phone|symbian|harmony\s*os|hyper\s*os|"
    r"sailfish|ubuntu\s*touch|tizen)\b",
    re.I,
)
_SMARTPHONE = re.compile(r"\bsmart\s*phones?\b", re.I)
_CONFLICTS = (
    ("tablet", re.compile(r"\btablets?\b", re.I)),
    ("feature_or_basic_phone", re.compile(r"\b(?:feature|basic)\s*phones?\b", re.I)),
    ("mystery_box", re.compile(r"\b(?:mystery|blind|lucky)\s*box(?:es)?\b", re.I)),
    ("accessory", re.compile(r"\b(?:accessor(?:y|ies)|screen\s*protectors?|phone\s*cases?|"
                             r"case\s*(?:cover\s*)?for|replacement\s*(?:screen|battery)|"
                             r"smart\s*watches?|earbuds?|headphones?)\b", re.I)),
)
_NEGATED_TYPE = re.compile(
    r"\bnot\s+(?:an?\s+)?(?:smart\s*phones?|feature\s*phones?|basic\s*phones?|"
    r"tablets?|accessor(?:y|ies))\b", re.I,
)
_TITLE_BUNDLE_SPLIT = re.compile(
    r"\b(?:(?:with\s+(?:free|bundled)|bundled\s+with|free)\s+|"
    r"(?:with|includes?)\s+(?:an?\s+)?(?=(?:headphones?|earbuds?|phone\s*case|"
    r"screen\s*protector|charger|accessor(?:y|ies))\b))", re.I,
)
_SCREEN_ONLY = re.compile(
    r"\bonly\s+(?:(?:lcd|oled|amoled)\s+)?(?:screen|display)\b|"
    r"\b(?:(?:lcd|oled|amoled)\s+)?(?:screen|display)\s+only\b|"
    r"^\s*replacement\s+(?:(?:lcd|oled|amoled)\s+)?(?:screen|display)\b", re.I,
)


def _identity_text(text, title=False):
    text = _NEGATED_TYPE.sub("", text)
    if title:
        text = _TITLE_BUNDLE_SPLIT.split(text, maxsplit=1)[0]
    return text


def smartphone_evidence(view, options=None):
    """{'status': supported|conflict|unresolved, 'reasons': [...]} for one SELECTED variant."""
    selected = str(options if options is not None else view.get("options") or "")
    if _SCREEN_ONLY.search(selected):
        return {"status": "conflict", "reasons": ["selected_screen_component_only"]}
    facts = view.get("facts") if isinstance(view.get("facts"), dict) else {}
    raw_title = str(view.get("title") or "")
    title = _identity_text(raw_title, title=True)
    type_text = " ".join(_identity_text(str(facts.get(k) or "")) for k in (
        "phone_type", "device_type", "description_device_type"))
    text = f"{title} {type_text}"
    conflicts = [name for name, pat in _CONFLICTS if pat.search(text)]
    if conflicts:
        return {"status": "conflict", "reasons": conflicts}
    if any("[truncated]" in str(facts.get(k) or "") for k in (
            "phone_type", "device_type", "device_operating_system")):
        return {"status": "unresolved", "reasons": ["truncated_device_evidence"]}
    reasons = []
    if _SMARTPHONE.search(text):
        reasons.append("explicit_smartphone_type")
    os_text = " ".join(
        _identity_text(str(facts.get(k) or ""))
        for k in ("device_operating_system", "description_operating_system")
        if not re.search(r"\bcompatib", str(facts.get(k) or ""), re.I)
    )
    title_os = _OS.search(title) and not re.search(r"\bcompatib", raw_title, re.I)
    if _OS.search(os_text) or title_os:
        reasons.append("smartphone_operating_system")
    return {"status": "supported" if reasons else "unresolved",
            "reasons": reasons or ["no_positive_smartphone_evidence"]}


def smartphone_supported(view, options=None):
    return smartphone_evidence(view, options)["status"] == "supported"


def genuine_device_ok(hard_category, view, options):
    """constraint_satisfaction.genuine_device_satisfied: only when category.rstrip('s')=='smartphone'."""
    if (hard_category or "").casefold().rstrip("s") != "smartphone":
        return True
    return smartphone_supported(view, options)


# --------------------------------------------------------------------------------------
# acceptance.py -- category / brand (exact)
# --------------------------------------------------------------------------------------
_CATEGORY_ALIASES = {
    "video cards": "graphics_card", "graphics cards": "graphics_card",
    "video graphics cards": "graphics_card", "gpu": "graphics_card", "gpus": "graphics_card",
    "mobile phones": "smartphone", "cell phones": "smartphone", "cellphones": "smartphone",
    "cellphone": "smartphone", "phones": "smartphone", "smartphones": "smartphone",
    "unlocked phones": "smartphone", "smart phones": "smartphone",
    "wi fi": "networking", "wifi": "networking",
    "smartwatches": "smartwatch", "smart watches": "smartwatch",
    "headphones headsets": "headphones",
}
_HIGH_REFRESH_RE = re.compile(r"(\d{2,3}(?:\.\d+)?)\s*-?\s*hz", re.I)


def _norm(text):
    return " ".join(re.findall(r"[a-z0-9]+", (text or "").casefold()))


def _tokens(text):
    return set(re.findall(r"[a-z0-9]+", (text or "").casefold()))


def _stemmed_tokens(text):
    out = set()
    for t in _tokens(text):
        out.add(t)
        if len(t) > 3 and t.endswith("s"):
            out.add(t[:-1])
    return out


def canonical_category_labels(labels):
    out = set()
    for label in labels:
        low = _norm(label)
        if low:
            out.add(low)
            out.add(_CATEGORY_ALIASES.get(low, low))
    return out


def _path_has(path, labels):
    return bool(canonical_category_labels(path) & canonical_category_labels(labels))


def category_matches(expected, category_path, title=None):
    if not expected:
        return True
    if canonical_category_labels([expected]) & canonical_category_labels(category_path or []):
        return True
    exp = _norm(expected)
    if exp in {"gaming monitors", "gaming monitor"}:
        toks = _stemmed_tokens(title)
        high = any(float(m.group(1)) >= 120 for m in _HIGH_REFRESH_RE.finditer(str(title or "")))
        return _path_has(category_path or [], ["Monitors", "Computer Monitors"]) and (
            {"gaming", "monitor"} <= toks or ("monitor" in toks and high))
    if exp in {"over ear", "over-ear", "over ear headphones", "over-ear headphones"}:
        toks = _stemmed_tokens(title)
        return _path_has(category_path or [], ["Headphones"]) and (
            {"over", "ear"} <= toks or "overear" in toks or "circumaural" in toks)
    return False


def brand_matches(expected, actual):
    if not expected:
        return True
    exp = _norm(expected)
    if not exp:
        return True
    if exp == _norm(actual):
        return True
    et = _tokens(expected)
    return bool(et) and et <= _tokens(actual)


def find_variant(view, sku):
    return next((v for v in view.get("variants") or [] if str(v.get("sku")) == str(sku)), None)


def candidate_satisfies_hard_visible(view, sku, hard):
    """acceptance.candidate_satisfies_hard on view data. hard = {category, brand, budget,
    currency, require_in_stock, attributes{key: canonical}}. Uses LIVE price/stock from the
    view row (runtime uses base catalog price/stock; final gates use live order state)."""
    v = find_variant(view, sku)
    if v is None:  # view lists only purchasable (catalog) variants
        return False
    if hard.get("currency") and v.get("currency") != hard["currency"]:
        return False
    if hard.get("require_in_stock", True) and v.get("in_stock") is not True:
        return False
    if v.get("price") is None or float(v["price"]) > float(hard["budget"]):
        return False
    title = str(view.get("title") or "")
    if not category_matches(hard.get("category"), view.get("category_path") or [], title=title):
        return False
    if not brand_matches(hard.get("brand"), view.get("brand")):
        return False
    for key, wanted in (hard.get("attributes") or {}).items():
        if resolve_variant_attribute_visible(view, v.get("options"), key) != wanted:
            return False
    return True


# --------------------------------------------------------------------------------------
# justification.py helpers that read only visible data (exact)
# --------------------------------------------------------------------------------------
_J_HZ_RE = re.compile(r"(\d+(?:\.\d+)?)\s*-?\s*hz", re.I)
_ATTR_FACT_LABEL = {"resolution": "display", "refresh_rate": "refresh_rate", "screen_size": "size"}


def norm_attr_claim_value(attr, text):
    """justification._norm_attr_value (claims AND facts; bare numbers get the field unit)."""
    if attr == "resolution":
        return normalize_resolution(str(text) if text is not None else None)
    raw = str(text or "").strip()
    bare = re.fullmatch(r"\d+(?:\.\d+)?", raw)
    if attr == "refresh_rate":
        vals = {f"{float(m.group(1)):g}hz" for m in _J_HZ_RE.finditer(raw)}
        if not vals and bare:
            vals = {f"{float(raw):g}hz"}
        return _only(vals)
    if attr == "screen_size":
        vals = inch_values(raw)
        if not vals and bare:
            vals = {f"{float(raw):g}in"}
        return _only(vals)
    return None


def fact_attr_value(view, attr):
    """justification._attr_fact_value: the visible-fact side of the TF7 spec gate."""
    return norm_attr_claim_value(attr, (view.get("facts") or {}).get(_ATTR_FACT_LABEL[attr]))


_BAD_ITEM_TOKENS = ("customer rating", "customer review", "compare ", "refurb",
                    "pre-owned", "restored", "renewed")


def is_actual_item(view, category):
    """justification._is_actual_item (TF7 category claim + event commitment)."""
    title = str(view.get("title") or "")
    if not title.strip():
        return False
    low = title.casefold()
    if any(tok in low for tok in _BAD_ITEM_TOKENS):
        return False
    return category_matches(category, view.get("category_path") or [], title=title)


# --------------------------------------------------------------------------------------
# recovery.py candidate admission (exact on visible data)
# --------------------------------------------------------------------------------------
_INVALID_TITLE_PREFIXES = ("customer ratings", "customer reviews")
_INVALID_TITLE_FRAGMENTS = ("join bild expo", "earbud", "in-ear", "in ear", "earphone",
                            "open-ear", "true wireless")
_ACCESSORY_RE = re.compile(
    r"\b(?:case|cases|cover|covers|sleeve|sleeves|skin|skins|pouch|protector|cable|cables|"
    r"strap|straps|ear ?tips?|ear ?hooks?|adapter|holder|stand|replacement|carabiner)\b"
)
_OVER_OR_ON_EAR_RE = re.compile(r"\b(?:over|on)[-\s]?ear\b", re.IGNORECASE)
_FEATURE_PHONE_RE = re.compile(r"\b(?:feature|basic|dumb|button|keypad) ?phones?\b")


def recovery_valid_headphone_title(title):
    low = title.casefold().strip()
    return (bool(low) and not low.startswith(_INVALID_TITLE_PREFIXES)
            and not any(f in low for f in _INVALID_TITLE_FRAGMENTS)
            and not _ACCESSORY_RE.search(low))


def recovery_valid_smartphone_title(title):
    low = title.casefold().strip()
    return (bool(low) and not low.startswith(_INVALID_TITLE_PREFIXES)
            and not _ACCESSORY_RE.search(low) and _FEATURE_PHONE_RE.search(low) is None)


def recovery_profile(view, options):
    """Return 'Headphones' / 'Smartphones' when the SKU is an admissible recovery row
    (before model/color labelling), else None. Profile order is Headphones, Smartphones."""
    title = str(view.get("title") or "")
    path = view.get("category_path") or []
    for cat in ("Headphones", "Smartphones"):
        if category_matches(cat, path, title=title):
            if cat == "Headphones":
                ok = recovery_valid_headphone_title(title) and bool(
                    _OVER_OR_ON_EAR_RE.search(" ".join((title, str(options or "")))))
            else:
                ok = recovery_valid_smartphone_title(title) and smartphone_supported(view, options)
            return cat if ok else None
    return None


_COLOR_PHRASES = (
    "midnight blue", "titanium black", "matte black", "triple black", "frost white",
    "white smoke", "cloud grey", "moonlight grey", "space gray", "street gray",
    "driftwood sand", "cypress green", "tidal blue", "light blue", "sky blue", "indigo blue",
    "canvas white", "platinum silver", "starlight", "graphite", "sandstone", "transparent",
    "silver", "beige", "black", "blue", "white", "gray", "grey", "green", "pink", "violet",
    "purple", "red", "sage", "gold", "khaki", "peach",
)


def recovery_color_label(view, options):
    facts = view.get("facts") or {}
    for text in (options or "", facts.get("color") or "", str(view.get("title") or "")):
        matches = []
        for color in (*_COLOR_PHRASES, "sage green"):
            pat = (r"(?<![a-z0-9])" + r"\W+".join(re.escape(w) for w in color.split())
                   + r"(?![a-z0-9])")
            label = "green" if color == "sage green" else color
            matches.extend((m.start(), m.end(), label) for m in re.finditer(pat, text.casefold()))
        if not matches:
            continue
        longest = [m for m in matches if not any(
            o[0] <= m[0] and o[1] >= m[1] and (o[1] - o[0]) > (m[1] - m[0]) for o in matches)]
        labels = {m[2] for m in longest}
        return next(iter(labels)) if len(labels) == 1 else None
    return None


_MODEL_PATTERNS = (
    (r"wh[-\s]?1000xm\s*([456])", lambda m: f"WH-1000XM{m.group(1)}"),
    (r"wf[-\s]?1000xm\s*([45])", lambda m: f"WF-1000XM{m.group(1)}"),
    (r"quietcomfort ultra(?: headphones)?[^\n]{0,80}\b2nd gen\b", lambda _m: "QuietComfort Ultra 2nd Gen"),
    (r"quietcomfort ultra", lambda _m: "QuietComfort Ultra"),
    (r"quietcomfort(?: headphones| wireless)?", lambda _m: "QuietComfort"),
    (r"headphones 700", lambda _m: "Headphones 700"),
    (r"beats studio pro|studio pro", lambda _m: "Studio Pro"),
    (r"beats studio buds \+|studio buds \+", lambda _m: "Studio Buds Plus"),
    (r"beats studio buds|studio buds", lambda _m: "Studio Buds"),
    (r"beats fit pro", lambda _m: "Fit Pro"),
    (r"momentum true wireless 4|mtw4|momentum 4", lambda _m: "Momentum 4"),
    (r"accentum", lambda _m: "Accentum"),
    (r"px7\s*s2e", lambda _m: "Px7 S2e"),
    (r"px7\s*s3", lambda _m: "Px7 S3"),
    (r"elite 10", lambda _m: "Elite 10"),
    (r"jbuds lux anc|go lux", lambda _m: "JBuds Lux ANC"),
)
_TITLE_MODEL_CODE = re.compile(r"\b[a-z]*\d{2,5}[a-z0-9]*(?:-[a-z0-9]+)*\b", re.IGNORECASE)
_NON_MODEL_CODE = re.compile(
    r"^(?:android|bluetooth|wifi|ips|ddr|lpddr|mtk)|"
    r"(?:gb|tb|mb|mah|hz|khz|mhz|ghz|mp|fps|inch|inches|p|g)$|^\d+x\d+$", re.IGNORECASE)


def _phrase_in(text, phrase):
    words = re.findall(r"[a-z0-9]+", phrase.casefold())
    if not words:
        return False
    pat = r"(?<![a-z0-9])" + r"\W+".join(re.escape(w) for w in words) + r"(?![a-z0-9])"
    return re.search(pat, text.casefold()) is not None


def model_code(raw):
    words = re.findall(r"[a-z0-9]+", raw.casefold())
    while words and words[-1] in _COLOR_PHRASES:
        words.pop()
    code = "".join(words)
    return code.upper() if 3 <= len(code) <= 24 and any(c.isdigit() for c in code) else None


def _named_model(text):
    for pat, fn in _MODEL_PATTERNS:
        m = re.search(pat, text.casefold())
        if m:
            return fn(m)
    return None


def recovery_model_label(view, options=None):
    facts = view.get("facts") or {}
    raw = facts.get("model")
    if raw:
        if ";" in raw or "/" in raw:
            return None
        named = _named_model(raw)
        if named:
            return named
        words = raw.casefold().split()
        prefix = []
        while len(words) > 1 and words[0].isalpha() and any(c.isdigit() for c in " ".join(words[1:])):
            prefix.append(words.pop(0))
        identity = f"{view.get('title') or ''} {view.get('brand') or ''}"
        if prefix and not _phrase_in(identity, " ".join(prefix)):
            return None
        if raw.isalpha() and 3 <= len(raw) <= 24:
            return raw.upper() if _phrase_in(identity, raw) else None
        return model_code(" ".join(words))
    title = str(view.get("title") or "")
    named = _named_model(title)
    if named:
        return named
    labels = set()
    for m in _TITLE_MODEL_CODE.finditer(title):
        tok = m.group()
        if _NON_MODEL_CODE.search(tok):
            continue
        suffix = re.match(r"(?:\s+(?:pro|max|ultra|plus)\b)+", title[m.end():], re.IGNORECASE)
        code = model_code(tok + (suffix.group() if suffix else ""))
        if code:
            labels.add(code)
    return next(iter(labels)) if len(labels) == 1 else None


def relaxation_level(model, color, preferred_model, preferred_color):
    if not model or not color or not preferred_model or not preferred_color:
        return None
    same_model = model.casefold() == preferred_model.casefold() or (
        model_code(model) is not None and model_code(model) == model_code(preferred_model))
    same_color = color.casefold() == preferred_color.casefold()
    return 0 if same_model and same_color else 1 if same_model else 2 if same_color else 3


# --------------------------------------------------------------------------------------
# ranking.tradeoff_values on view data
# --------------------------------------------------------------------------------------
def tradeoff_values_visible(view, sku, price=None):
    v = find_variant(view, sku)
    if v is None:
        return None
    refresh = (resolve_variant_attribute_visible(view, v.get("options"), "refresh_rate")
               or resolve_attribute_visible(view, "refresh_rate"))
    size = (resolve_variant_attribute_visible(view, v.get("options"), "screen_size")
            or resolve_attribute_visible(view, "screen_size"))
    if not refresh or not refresh.endswith("hz") or not size or not size.endswith("in"):
        return None
    try:
        return (float(refresh[:-2]), float(size[:-2]),
                float(v.get("price") if price is None else price))
    except ValueError:
        return None


# --------------------------------------------------------------------------------------
# Goal-text -> canonical wanted value (constraint_satisfaction._spec_phrase / TF7 _value_phrase)
# --------------------------------------------------------------------------------------
def parse_gated_spec(text):
    """Return (key, canonical) from goal/intervention text, or None.
    Phrases: 'a 6.64-inch screen', '16GB of RAM', 'a 144Hz refresh rate',
    'a 4K display' / 'QHD' / 'QHD (1440p)' / '1080p Full HD' / '720p HD'.
    Only the goal part is parsed: the TF3 rules text itself mentions 4K/QHD/Full HD."""
    t = (text or "").split("\n\nTask rules:", 1)[0]
    m = re.search(r"(\d+(?:\.\d+)?)\s*-\s*inch", t, re.I)
    if m:
        return "screen_size", f"{float(m.group(1)):g}in"
    m = re.search(r"(\d+(?:\.\d+)?)\s*(TB|GB)\s+of\s+RAM", t, re.I)
    if m:
        return "ram", f"{float(m.group(1)) * (1024 if m.group(2).upper() == 'TB' else 1):g}gb"
    m = re.search(r"(\d+(?:\.\d+)?)\s*Hz", t, re.I)
    if m:
        return "refresh_rate", f"{float(m.group(1)):g}hz"
    if re.search(r"\b4K\b", t):
        return "resolution", "4k"
    if re.search(r"\bQHD\b", t):  # uppercase only; 'qHD' is quarter HD
        return "resolution", "qhd"
    if re.search(r"\b1080p\s+Full\s+HD\b|\bFull\s+HD\b", t, re.I):
        return "resolution", "fhd"
    if re.search(r"\b720p\s+HD\b", t, re.I):
        return "resolution", "hd"
    return None

# ========================================================================
# families/tf1_intent_decomposition.py
