import re
from typing import Optional


# ---------------------------------------------------------------------------
# Goal / shopper-text parsing
# ---------------------------------------------------------------------------

_TF1_REVISION_NOTICE = "I will give you one requirement update"
_TF1_RESOLUTION_WORDS = {
    "4k": "4k", "uhd": "4k", "ultra hd": "4k", "2160p": "4k",
    "qhd": "qhd", "1440p": "qhd", "2k": "qhd",
    "1080p full hd": "fhd", "full hd": "fhd", "fhd": "fhd", "1080p": "fhd",
    "720p hd": "hd", "720p": "hd", "hd": "hd",
}
_TF1_SPEC_PATTERNS = (
    ("screen_size", re.compile(r"(\d+(?:\.\d+)?)\s*-?\s*inch(?:es)?\b", re.I)),
    ("ram", re.compile(r"(\d+(?:\.\d+)?)\s*(GB|TB)\s+(?:of\s+)?(?:RAM|memory)\b", re.I)),
    ("refresh_rate", re.compile(r"(\d+(?:\.\d+)?)\s*-?\s*Hz\b", re.I)),
    ("resolution", re.compile(
        r"\b(1080p\s+Full\s+HD|720p\s+HD|Ultra\s+HD|Full\s+HD|4K|UHD|2160p|QHD|1440p|2K|FHD|1080p|720p|HD)\b",
        re.I,
    )),
)
_TF1_MONEY_RE = re.compile(r"(?:PHP|₱)?\s*([0-9][0-9,]*(?:\.[0-9]+)?)\s*([A-Z]{3})?")
_TF1_UNIT_AFTER_RE = re.compile(
    r"\s*-?\s*(?:inch(?:es)?\b|in\b|[\"”']|hz\b|gb\b|tb\b|mb\b|mp\b|mah\b|%|x\b|k\b|p\b|"
    r"(?:days?|hours?|hrs?|weeks?|months?|years?|yrs?|items?|units?|pieces?|pcs|times?|sims?|"
    r"cards?|colou?rs?|ports?|cameras?|cores?)\b)", re.I
)
_TF1_BUDGET_WORDS = re.compile(
    r"\b(?:up\s+to|budget|balance|spend|afford|max(?:imum)?|at\s+most|no\s+more\s+than|more\s+than|"
    r"under|below|less\s+than|lower\s+than|within|limit|ceiling|cap)\b", re.I
)
# An amount right after a budget phrase is money even without a currency code or decimals.
_TF1_BUDGET_ANCHOR_RE = re.compile(
    r"\b(?:up\s+to|at\s+most|no\s+more\s+than|more\s+than|under|below|less\s+than|lower\s+than|"
    r"within|max(?:imum)?(?:\s+of)?|cap(?:ped)?(?:\s+(?:it\s+)?at)?|limit(?:\s+is)?(?:\s+now)?|"
    r"ceiling(?:\s+is)?(?:\s+now)?|budget(?:\s+is)?(?:\s+now)?(?:\s+(?:of|at))?)"
    r"\s*[:=]?\s*(?:(?:PHP|₱)\s*)?([0-9][0-9,]*(?:\.[0-9]+)?)",
    re.I,
)
# Goal budget: '<phrase> 20000.00 PHP' (the currency group stays case-sensitive).
_TF1_GOAL_BUDGET_RE = re.compile(
    r"(?i:\b(?:up\s+to|at\s+most|no\s+more\s+than|not\s+more\s+than|under|below|less\s+than|within|"
    r"max(?:imum)?(?:\s+of)?|budget(?:\s+is)?(?:\s+of)?|spend))\s*(?:PHP\s*|₱\s*)?"
    r"([0-9][0-9,]*(?:\.[0-9]+)?)\s*([A-Z]{3})?\b"
)
_TF1_BRAND_PATTERNS = (
    re.compile(r"\bpreferred\s+brand\s*(?:is|would\s+be|[:=])\s*(.+?)"
               r"(?:\s*,|\s*;|\.(?:\s|$)|\s+but\b|\s+if\b|$)", re.I),
    re.compile(r"\bI\s+(?:would\s+)?prefer\s+(.+?)(?:\s*,|\s*;|\.(?:\s|$)|\s+but\b|\s+if\b|$)"),
    re.compile(r"\b([A-Z][\w&'+-]*(?:\s+[A-Z][\w&'+-]*)*)\s+is\s+my\s+"
               r"(?:preferred|favou?rite|first[- ]choice)\s+brand\b"),
    re.compile(r"\bprefer(?:ably|red|s)?\s+(?:the\s+)?(.+?)"
               r"(?:\s*,|\s*;|\.(?:\s|$)|\s+but\b|\s+if\b|$)", re.I),
)
# Goal-template words that can never be the preferred brand (brand inference fallback).
_TF1_GOAL_WORDS = frozenset(
    "i im need a an with and can spend up to ideally prefer preferably preferred but the firm "
    "requirements requirement matter more my brand is of for no than at most budget looking "
    "shopping want screen display refresh rate ram memory inch php usd hz after your first cart "
    "choice will give you one update read it before placing order".split()
)


def _tf1_spec_value(key: str, match: "re.Match") -> Optional[str]:
    if key == "screen_size":
        return f"{float(match.group(1)):g}in"
    if key == "ram":
        return f"{float(match.group(1)) * (1024 if match.group(2).upper() == 'TB' else 1):g}gb"
    if key == "refresh_rate":
        return f"{float(match.group(1)):g}hz"
    word = match.group(1)
    if word == "qHD":  # quarter HD is not a resolution class
        return None
    return _TF1_RESOLUTION_WORDS.get(re.sub(r"\s+", " ", word.lower()))


def _tf1_parse_spec(text: str) -> Optional[tuple]:
    """(gate key, canonical value) of the earliest spec phrase in ``text``."""

    best = None
    for key, pattern in _TF1_SPEC_PATTERNS:
        for match in pattern.finditer(text or ""):
            value = _tf1_spec_value(key, match)
            if value is None:
                continue
            if best is None or match.start() < best[0]:
                best = (match.start(), key, value)
            break
    return (best[1], best[2]) if best else None


def _tf1_parse_goal(goal: str) -> dict:
    """Template: 'I need a {cat} with {spec}, and I can spend up to {B} {CUR}. Ideally, I
    prefer {Brand}, but the firm requirements matter more.[ <revision notice>]'"""

    out: dict = {"cat_word": None, "gated_key": None, "gated_value": None, "budget": None,
                 "currency": None, "brand": None,
                 "revision_announced": _TF1_REVISION_NOTICE.lower() in goal.lower()}
    match = (re.search(r"\bI\s+need\s+an?\s+(.+?)\s+(?:with|that\s+has|having)\b", goal, re.I)
             or re.search(r"\b(?:want|looking\s+for|shopping\s+for|buy|need)\s+an?\s+(.+?)\s+"
                          r"(?:with|that\s+has|that|having)\b", goal, re.I))
    if match:
        out["cat_word"] = match.group(1).strip().lower()
    else:
        category = parse_category_word(goal)
        if category:
            low = category.lower()
            out["cat_word"] = low[:-1] if low.endswith("s") else low
    spec_zone = re.search(r"\bwith\s+(.+?)(?:,\s*and\b|\.\s|$)", goal, re.I)
    spec = _tf1_parse_spec(spec_zone.group(1)) if spec_zone else None
    if spec is None:
        spec = _tf1_parse_spec(goal) or parse_gated_spec(goal)
    if spec:
        out["gated_key"], out["gated_value"] = spec
    match = (re.search(r"\bup\s+to\s+(?:PHP|₱)?\s*([0-9][0-9,]*(?:\.[0-9]+)?)\s*([A-Z]{3})?\b", goal)
             or _TF1_GOAL_BUDGET_RE.search(goal))
    if match:
        out["budget"] = parse_money(match.group(1))
        out["currency"] = match.group(2) if match.group(2) not in ("RAM",) else None
    if out["budget"] is None:
        out["budget"] = parse_budget(goal)
    if out["budget"] is None:  # '20000.00 USD' anywhere
        amount = re.search(r"([0-9][0-9,]*\.[0-9]{2})\s*([A-Z]{3})\b", goal)
        if amount:
            out["budget"] = parse_money(amount.group(1))
    if not out["currency"]:
        cur = re.search(r"[0-9][0-9,]*(?:\.[0-9]+)?\s*([A-Z]{3})\b", goal)
        out["currency"] = cur.group(1) if cur and cur.group(1) not in ("RAM",) else None
    for pattern in _TF1_BRAND_PATTERNS:
        match = pattern.search(goal)
        brand = _tf1_clean_brand(match.group(1)) if match else None
        if brand:
            out["brand"] = brand
            break
    return out


def _tf1_clean_brand(text: str) -> Optional[str]:
    brand = re.sub(r"^(?:(?:the\s+)?brand\s+(?:is|would\s+be)\s+|brand\s*[:=]\s*|the\s+|an?\s+)", "",
                   str(text or "").strip(), flags=re.I)
    brand = re.sub(r"\s+(?:brand|products?|phones?|items?|devices?|models?)$", "", brand, flags=re.I)
    brand = brand.strip(" '\"")
    return brand or None


def _tf1_llm_goal(goal: str) -> dict:
    """Optional fallback for an unseen goal template (None fields when the LLM is off)."""

    try:
        answer = llm_json(
            "Extract the shopping request. Keys: category (plural catalog category), spec_key "
            "(one of ram, screen_size, resolution, refresh_rate), spec_value (as written), "
            "budget (number), currency (ISO code), preferred_brand (or null).",
            goal[:1200], max_tokens=200,
        )
    except Exception:  # noqa: BLE001 - the fallback must never break the episode
        answer = None
    return _pin_currency(answer) if isinstance(answer, dict) else {}


def _tf1_parse_revision(line: str) -> Optional[tuple]:
    """TF1 replace_constraint: 'it must now have {new} instead of {old}' / 'To restate ...'."""

    match = (re.search(r"must\s+now\s+have\s+(.+?)\s+instead\s+of\b", line, re.I)
             or re.search(r"restate\s+my\s+requirement:\s*it\s+must\s+have\s+(.+?)(?:\.\s|\.$|$)", line, re.I)
             or re.search(r"\b(?:now\s+)?(?:needs?|must\s+have)\s+(.+?)\s+instead\s+of\b", line, re.I))
    return _tf1_parse_spec(match.group(1)) if match else None


def _tf1_parse_budget_cut(line: str, currency: Optional[str], floor: float = 0.0) -> Optional[float]:
    """Smallest amount stated in a budget-like shopper line (add_constraint utterance).

    Money-looking amounts (a currency code, or decimals/thousands separators) anywhere in a line
    with budget words, plus any amount right after a budget phrase ('up to 12000', 'under
    15,000.00', 'my limit is now 9500'). Spec values ('6.5-inch', '120Hz', '8GB', '4K',
    '1080p') and amounts below ``floor`` (a sanity bound, e.g. '2 items') never count.
    """

    if not _TF1_BUDGET_WORDS.search(line):
        return None
    amounts = []

    def consider(raw: str, end: int, cur: Optional[str], anchored: bool) -> None:
        if cur and currency and cur != currency:
            return
        if _TF1_UNIT_AFTER_RE.match(line, end):
            return  # a spec value ('6.5-inch', '120Hz', '8GB'), not money
        if not anchored and not cur and "." not in raw and "," not in raw:
            return  # unanchored bare integers ('2 items') are not money
        value = parse_money(raw)
        if value is not None and value > 0 and value >= floor:
            amounts.append(value)

    for match in _TF1_MONEY_RE.finditer(line):
        consider(match.group(1), match.end(1), match.group(2), False)
    for pattern in (_TF1_BUDGET_ANCHOR_RE, BUDGET_CUT_RE):
        for match in pattern.finditer(line):
            tail = re.match(r"\s*([A-Z]{3})\b", line[match.end(1):])
            consider(match.group(1), match.end(1), tail.group(1) if tail else None, True)
    return min(amounts) if amounts else None


# ---------------------------------------------------------------------------
# Spec rendering and small ranking helpers
# ---------------------------------------------------------------------------


def _tf1_display_value(key: str, value: str) -> str:
    """constraint_satisfaction._display_value."""

    if key == "ram":
        return value.upper()
    if key == "refresh_rate":
        return value[:-2] + "Hz"
    if key == "screen_size":
        return value.replace("in", "-inch")
    return {"4k": "4K", "qhd": "QHD", "fhd": "1080p Full HD", "hd": "720p HD"}.get(value, value.upper())


def _tf1_spec_phrase(key: Optional[str], value: Optional[str]) -> str:
    """constraint_satisfaction._spec_phrase (used in the reply text)."""

    if not key or not value:
        return "the required spec"
    shown = _tf1_display_value(key, value)
    return {"ram": f"{shown} of RAM", "resolution": f"a {shown} display",
            "screen_size": f"a {shown} screen", "refresh_rate": f"a {shown} refresh rate"}.get(key, shown)


def _tf1_spec_terms(key: Optional[str], value: Optional[str]) -> tuple:
    """(primary, alternate, extra) search phrasings of a canonical gate value."""

    if not key or not value:
        return ("", "", "")
    if key == "screen_size":
        num = value[:-2]
        return (f"{num} inch", f'{num}"', f"{num} inches display")
    if key == "ram":
        num = value[:-2]
        return (f"{num}GB RAM", f"{num}GB", f"{num}GB memory")
    if key == "refresh_rate":
        num = value[:-2]
        return (f"{num}Hz", f"{num} Hz", f"{num}Hz display")
    return {
        "4k": ("4K", "UHD 2160p", "4K UHD display"),
        "qhd": ("QHD", "1440p", "QHD 2K display"),
        "fhd": ("Full HD", "1080p", "FHD 1080p display"),
        "hd": ("HD 720p", "720p", "HD display"),
    }.get(value, (value, value, value))


def _tf1_norm(text) -> str:
    return " ".join(re.findall(r"[a-z0-9]+", str(text or "").casefold()))


def _tf1_brand_rank(expected: Optional[str], actual) -> int:
    """0 exact normalized brand, 1 acceptance.brand_matches token subset, 2 other brand."""

    if not expected or not _tf1_norm(expected):
        return 2
    if _tf1_norm(expected) == _tf1_norm(actual):
        return 0
    return 1 if actual and brand_matches(expected, actual) else 2


def _tf1_title_spec_rank(title, key: Optional[str], value: Optional[str]) -> int:
    """0 title states exactly the wanted value, 1 title is silent, 2 title states another value."""

    if not key or not value:
        return 1
    values = options_values(key, str(title or ""))
    if not values:
        return 1
    return 0 if values == {value} else 2


def _tf1_strength(source: str) -> int:
    """variant_attribute_with_source provenance -> 0 options, 1 title(+facts), 2 facts only."""

    if source == "options":
        return 0
    if source in ("title", "title+facts"):
        return 1
    return 2


# ---------------------------------------------------------------------------
# Strategy
# ---------------------------------------------------------------------------


@register_strategy
class IntentDecompositionStrategy(Strategy):
    family = "intent_decomposition"
    max_research_rounds = 7
    max_recovery_rounds = 6

    def __init__(self, ep) -> None:
        super().__init__(ep)
        self._tf1_msgs_seen = 0
        self._tf1_issued: set = set()
        self._tf1_stages: set = set()
        self._tf1_exhausted = False
        self._tf1_last_round = -1
        self._tf1_alt_waits = 0
        self._tf1_cut: Optional[float] = None  # lowest budget the shopper stated after the goal
        self._tf1_brand_seen = 0  # product count at the last brand-fallback check

    # -- parsing -------------------------------------------------------------
    def parse(self) -> None:
        ep = self.ep
        info = _tf1_parse_goal(ep.goal_text)
        if info["gated_key"] is None or info["budget"] is None or info["cat_word"] is None:
            extra = _tf1_llm_goal(ep.goal_text)
            key = str(extra.get("spec_key") or "").strip().lower()
            if info["gated_key"] is None and key in ("ram", "screen_size", "resolution", "refresh_rate"):
                value = normalize_wanted(key, str(extra.get("spec_value") or ""))
                if value:
                    info["gated_key"], info["gated_value"] = key, value
            if info["budget"] is None:
                info["budget"] = parse_money(extra.get("budget"))
            if info["cat_word"] is None and extra.get("category"):
                low = str(extra["category"]).strip().lower()
                info["cat_word"] = low[:-1] if low.endswith("s") else low
            if info["brand"] is None and extra.get("preferred_brand"):
                info["brand"] = str(extra["preferred_brand"]).strip() or None
            if not info["currency"] and extra.get("currency"):
                info["currency"] = str(extra["currency"]).strip().upper()[:3] or None
        ep.set_budget(info["budget"] if info["budget"] else 1e12)
        if info["currency"]:
            ep.currency = info["currency"]
        cat_word = info["cat_word"]
        ep.intent.update({
            "category": (cat_word + "s") if cat_word else None,
            "cat_word": cat_word,
            "brand": info["brand"],
            "gated_key": info["gated_key"],
            "gated_value": info["gated_value"],
            "orig_key": info["gated_key"],
            "orig_value": info["gated_value"],
            "revision_announced": info["revision_announced"],
        })

    def _tf1_sync(self) -> None:
        """Absorb new shopper lines: budget cuts (min) and a TF1 requirement revision.

        The module owns the budget: ep.budget = min(goal budget, every cut this parser accepts).
        That also undoes a core-level misparse (core's generic regex has no sanity floor), while
        this parser accepts every phrase core's regex does.
        """

        ep = self.ep
        original = ep.original_budget
        # Sanity floor: observed add_constraint cuts are 0.32-0.99x the goal budget.
        floor = 0.2 * original if original is not None and original < 1e11 else 0.0
        while self._tf1_msgs_seen < len(ep.shopper_messages):
            _turn, text = ep.shopper_messages[self._tf1_msgs_seen]
            self._tf1_msgs_seen += 1
            for line in [part for part in str(text).split("\n") if part.strip()]:
                revision = _tf1_parse_revision(line)
                if revision is None and ep.intent.get("revision_announced") and re.search(
                        r"\b(?:requirement|instead\s+of|must\s+now|now\s+(?:needs?|must))\b", line, re.I):
                    revision = _tf1_parse_spec(line)  # unseen wording: earliest spec phrase
                if revision is not None and ep.intent.get("orig_key") in (None, revision[0]):
                    if (ep.intent.get("gated_key"), ep.intent.get("gated_value")) != revision:
                        ep.notes.append(f"tf1 revision {ep.intent.get('gated_value')} -> {revision[1]}")
                    ep.intent["gated_key"], ep.intent["gated_value"] = revision
                    ep.intent["revised"] = True
                cut = _tf1_parse_budget_cut(line, ep.currency, floor)
                if cut is not None and (self._tf1_cut is None or cut < self._tf1_cut):
                    ep.notes.append(f"tf1 budget cut -> {cut}")
                    self._tf1_cut = cut
        if original is not None:
            ep.budget = original if self._tf1_cut is None else min(original, self._tf1_cut)
        self._tf1_refresh_brand()

    def _tf1_refresh_brand(self) -> None:
        """Brand fallback for an unseen goal phrasing: before the commit, when the parsed brand
        matches no listing seen so far, use a seen listing brand that the goal text names."""

        ep = self.ep
        if ep.first_add is not None or not ep.searches or len(ep.products) == self._tf1_brand_seen:
            return
        self._tf1_brand_seen = len(ep.products)
        parsed = ep.intent.get("brand")
        if parsed and any(_tf1_brand_rank(parsed, p.brand) < 2 for p in ep.products.values()):
            return
        goal = f" {_tf1_norm(ep.goal_text)} "
        skip = _TF1_GOAL_WORDS | set(_tf1_norm(ep.intent.get("cat_word")).split())
        best = None
        for product in ep.products.values():
            name = _tf1_norm(product.brand)
            if len(name) < 2 or set(name.split()) <= skip or f" {name} " not in goal:
                continue
            if best is None or len(name) > len(_tf1_norm(best)):
                best = str(product.brand)
        if best and _tf1_norm(best) != _tf1_norm(parsed):
            ep.notes.append(f"tf1 brand {parsed!r} -> {best!r} (named in the goal)")
            ep.intent["brand"] = best

    def _tf1_spec(self) -> tuple:
        return self.ep.intent.get("gated_key"), self.ep.intent.get("gated_value")

    def _tf1_orig_spec(self) -> tuple:
        return self.ep.intent.get("orig_key"), self.ep.intent.get("orig_value")

    def _tf1_low(self) -> bool:
        ep = self.ep
        return ep.time_left() < 80.0 or ep.turns_left() <= 10

    # -- candidate evaluation --------------------------------------------------
    def _tf1_category_ok(self, view: dict) -> bool:
        cat_word = self.ep.intent.get("cat_word")
        if not cat_word:
            return True
        path = view.get("category_path") or []
        title = view.get("title")
        return category_matches(cat_word + "s", path, title=title) or category_matches(cat_word, path, title=title)

    def _tf1_eval(self, key: str, *, budget: Optional[float], spec: tuple) -> Optional[dict]:
        """Agent-side candidate_satisfies_hard on one detailed variant (live price/stock)."""

        ep = self.ep
        pid, sku = split_key(key)
        if key in ep.excluded or not ep.detailed(pid):
            return None
        view = ep.view_row(pid)
        variant = next((v for v in view["variants"] if str(v.get("sku")) == sku), None)
        if variant is None or variant.get("in_stock") is not True:
            return None
        price = variant.get("price")
        if price is None or (budget is not None and float(price) > budget + 1e-9):
            return None
        currency = variant.get("currency")
        if currency and ep.currency and currency != ep.currency:
            return None
        if not self._tf1_category_ok(view):
            return None
        gate_key, gate_value = spec
        strength = 1
        if gate_key and gate_value:
            value, source = variant_attribute_with_source(view, variant.get("options"), gate_key)
            if value != gate_value:
                return None
            strength = _tf1_strength(source)
        return {"price": float(price), "strength": strength}

    def _tf1_best_commit(self, preferred_only: bool = True) -> Optional[Candidate]:
        """Priciest preferred-brand item valid under the ORIGINAL budget and spec."""

        ep = self.ep
        brand = ep.intent.get("brand")
        budget0 = ep.original_budget
        ranked = []
        for key in ep.known_keys(detailed_only=True):
            evaluation = self._tf1_eval(key, budget=budget0, spec=self._tf1_orig_spec())
            if evaluation is None:
                continue
            pid, sku = split_key(key)
            brand_rank = _tf1_brand_rank(brand, ep.product(pid).brand)
            if preferred_only and brand_rank >= 2:
                continue
            tier = 0 if evaluation["strength"] <= 1 else 1
            ranked.append(((brand_rank if preferred_only else 0, tier, -evaluation["price"], key), pid, sku))
        if not ranked:
            return None
        ranked.sort()
        _rank, pid, sku = ranked[0]
        return Candidate(pid=pid, sku=sku, reason="tf1 commit")

    def _tf1_ranked_finals(self) -> list:
        """Valid under the CURRENT budget/spec; strong evidence, post-event checked, cheapest."""

        ep = self.ep
        self._tf1_sync()
        since = ep.event.seq if ep.event is not None else None
        rows = []
        for key in ep.known_keys(detailed_only=True):
            if ep.event is not None and key == ep.event.target_key:
                continue
            if not ep.orderable(key):
                continue
            evaluation = self._tf1_eval(key, budget=ep.budget, spec=self._tf1_spec())
            if evaluation is None:
                continue
            tier = 0 if evaluation["strength"] <= 1 else 1
            unchecked = 1 if since is not None and not ep.state_checked_after(key, since) else 0
            rows.append(((tier, unchecked, evaluation["price"], key), key))
        rows.sort()
        out = []
        for rank, key in rows:
            pid, sku = split_key(key)
            out.append(Candidate(pid=pid, sku=sku, score=-rank[2], reason="tf1 final"))
        return out

    # -- Strategy hooks ---------------------------------------------------------
    def candidate_ok(self, key: str) -> bool:
        self._tf1_sync()
        return self._tf1_eval(key, budget=self.ep.budget, spec=self._tf1_spec()) is not None

    def final_ok(self, key: str) -> bool:
        # Sync first: the engine calls this right after a read turn that may carry a budget cut.
        self._tf1_sync()
        return self.ep.orderable(key) and self.candidate_ok(key)

    def make_plan(self) -> Optional[Plan]:
        ep = self.ep
        self._tf1_sync()
        fallback_ok = (self._tf1_exhausted or self._tf1_low()
                       or self._tf1_last_round >= self.max_research_rounds - 1)
        commit = self._tf1_best_commit(preferred_only=True)
        if commit is None:
            if not fallback_ok:
                return None
            commit = self._tf1_best_commit(preferred_only=False)
            if commit is None:
                return None
            ep.notes.append("tf1: no compliant preferred-brand item seen; committing to best valid item")
        finals = [c for c in self._tf1_ranked_finals() if c.pid != commit.pid]
        revision = bool(ep.intent.get("revision_announced"))
        if not finals and not revision and not fallback_ok and self._tf1_alt_waits < 1:
            self._tf1_alt_waits += 1  # one research round for alternates before committing
            return None
        return Plan(commit=commit, finals=finals, preadd=not revision)

    def commit_group(self, plan: Plan) -> list:
        """[add commit, inspect commit, add hedge, inspect hedge, inspect cheap finals...]."""

        ep = self.ep
        commit = plan.commit
        group = [
            action("add_to_cart", product_id=commit.pid, sku=commit.sku),
            action("inspect_stock", product_id=commit.pid, sku=commit.sku),
        ]
        finals = [f for f in plan.finals if f.key != commit.key]
        if plan.preadd and finals:
            hedge, rest = finals[0], finals[1:]
            group.append(action("add_to_cart", product_id=hedge.pid, sku=hedge.sku))
            group.append(action("inspect_stock", product_id=hedge.pid, sku=hedge.sku))
        else:
            rest = finals
        # Cheapest first: after a budget cut these finals need no extra state-check turn.
        for final in sorted(rest, key=lambda c: (ep.price(c.key) or 0.0, c.key)):
            if len(group) >= ep.max_calls:
                break
            group.append(action("inspect_stock", product_id=final.pid, sku=final.sku))
        return group[: ep.max_calls]

    def research_actions(self, round_no: int) -> list:
        self._tf1_sync()
        self._tf1_last_round = round_no
        if round_no == 0:
            acts = self._tf1_discovery("primary")
            if acts:
                return acts
        need_commit = self._tf1_best_commit(preferred_only=True) is None
        acts = self._tf1_inspect_batch(need_commit=need_commit)
        if acts:
            return acts
        stages = ("brand", "brand2", "alternates") if need_commit else ("alternates", "alternates2")
        for stage in stages:
            if stage not in self._tf1_stages:
                acts = self._tf1_discovery(stage)
                if acts:
                    return acts
        if need_commit:  # every brand lead is spent: inspect what is left for the finals
            acts = self._tf1_inspect_batch(need_commit=False)
            if acts:
                return acts
        self._tf1_exhausted = True
        return []

    def finals_after_event(self) -> list:
        return self._tf1_ranked_finals()

    def recovery_actions(self, round_no: int) -> list:
        self._tf1_sync()
        acts = self._tf1_inspect_batch(need_commit=False)
        if acts:
            return acts
        for stage in ("recover1", "recover2", "recover3"):
            if stage not in self._tf1_stages:
                acts = self._tf1_discovery(stage)
                if acts:
                    return acts
        return []

    def order_message(self, cand: Candidate) -> str:
        ep = self.ep
        product = ep.product(cand.pid)
        price = ep.price(cand.key)
        key, value = self._tf1_spec()
        currency = ep.currency or ""
        parts = []
        if ep.event is not None:
            parts.append("My first cart choice was repriced above your budget, so I switched items.")
        price_text = f" at {fmt_money(price)} {currency}" if price is not None else ""
        parts.append(f"I'm going with {product.title or cand.pid} (product {cand.pid}, SKU {cand.sku}){price_text}.")
        budget_text = f" your {fmt_money(ep.budget)} {currency} budget" if ep.budget and ep.budget < 1e11 else " your budget"
        parts.append(
            f"Yes, it has {_tf1_spec_phrase(key, value)}; I checked its listing, category and current "
            f"price and stock: it is in stock and within{budget_text}."
        )
        return " ".join(parts)[:600]

    # -- research building blocks ---------------------------------------------
    def _tf1_inspect_batch(self, *, need_commit: bool) -> list:
        """compare/view for promising uninspected products (one group of <= 22 products)."""

        ep = self.ep
        budget0 = ep.original_budget or ep.budget or 1e12
        budget_now = ep.budget or budget0
        orig_key, orig_value = self._tf1_orig_spec()
        cur_key, cur_value = self._tf1_spec()
        brand = ep.intent.get("brand")
        # alt_lo: the title states ANOTHER value. SKU options still win in the verifier, and in
        # indexed catalogs sibling SKUs of one listing share its title, so these stay eligible
        # (cheapest first, after every better lead).
        brand_hi, brand_lo, alt_hi, alt_mid, alt_lo = [], [], [], [], []
        for pid, product in ep.products.items():
            if product.detailed:
                continue
            prices = [
                ep.price(cand_key(pid, sku)) for sku in product.variants
                if ep.in_stock(cand_key(pid, sku)) is not False
            ]
            prices = [p for p in prices if p is not None]
            if not prices:
                continue
            low = min(prices)
            brand_rank = _tf1_brand_rank(brand, product.brand)
            if brand_rank < 2 and low <= budget0 + 1e-9:
                spec_rank = _tf1_title_spec_rank(product.title, orig_key, orig_value)
                (brand_hi if spec_rank < 2 else brand_lo).append((spec_rank, brand_rank, -low, pid))
            if low <= budget_now + 1e-9:
                spec_rank = _tf1_title_spec_rank(product.title, cur_key, cur_value)
                if spec_rank == 0:
                    alt_hi.append((low, pid))
                elif spec_rank == 1:
                    alt_mid.append((low, pid))
                else:
                    alt_lo.append((low, pid))
        for bucket in (brand_hi, brand_lo, alt_hi, alt_mid, alt_lo):
            bucket.sort()
        slots = COMPARE_LIMIT * MAX_COMPARES_PER_GROUP + max(0, self.ep.max_calls - MAX_COMPARES_PER_GROUP)
        if need_commit:
            if not brand_hi and not brand_lo:
                return []
            head = [row[-1] for row in brand_hi[:14]]
            order = (head + [p for _l, p in alt_hi] + [row[-1] for row in brand_hi[14:]]
                     + [row[-1] for row in brand_lo] + [p for _l, p in alt_mid]
                     + [p for _l, p in alt_lo])
        else:
            order = [p for _l, p in alt_hi] + [p for _l, p in alt_mid] + [p for _l, p in alt_lo]
        pids = list(dict.fromkeys(order))[:slots]
        return self._tf1_inspect_actions(pids)

    def _tf1_inspect_actions(self, pids: list) -> list:
        acts = []
        compared = pids[: COMPARE_LIMIT * MAX_COMPARES_PER_GROUP]
        for start in range(0, len(compared), COMPARE_LIMIT):
            acts.append(action("compare", product_ids=compared[start:start + COMPARE_LIMIT]))
        for pid in pids[len(compared):]:
            if len(acts) >= self.ep.max_calls:
                break
            acts.append(action("view", product_id=pid))
        return acts

    def _tf1_discovery(self, stage: str) -> list:
        """One group of searches/filters for ``stage``, sized to the engine's load limits."""

        ep = self.ep
        self._tf1_stages.add(stage)
        brand = (ep.intent.get("brand") or "").strip()
        cat = (ep.intent.get("cat_word") or "").strip()
        filter_cat = cat or None
        budget0 = ep.original_budget or ep.budget or 1e12
        now = ep.budget or budget0
        if stage in ("primary", "brand", "brand2"):
            key, value = self._tf1_orig_spec()
        else:
            key, value = self._tf1_spec()
        spec, spec_alt, spec_extra = _tf1_spec_terms(key, value)
        searches: list = []
        filters: list = []
        if stage == "primary":
            searches = [(f"{brand} {cat} {spec}", budget0), (f"{brand} {spec}", budget0),
                        (f"{brand} {cat}", budget0), (f"{cat} {spec}", budget0),
                        (f"{cat} {spec}", round(0.5 * budget0, 2))]
            # Most valuable first: only the first two filters fit one group (see below).
            filters = [(filter_cat, brand, budget0), (filter_cat, None, round(0.35 * budget0, 2)),
                       (filter_cat, None, budget0), (None, brand, budget0), (filter_cat, None, round(0.6 * budget0, 2))]
        elif stage == "brand":
            searches = [(f"{brand} {spec_alt}", budget0), (f"{brand} {cat} {spec_alt}", budget0),
                        (f"{brand} {spec_extra}", budget0), (f"{brand} {cat} {spec}", round(0.6 * budget0, 2)),
                        (f"{brand} {cat}", round(0.5 * budget0, 2))]
            filters = [(filter_cat, brand, round(0.75 * budget0, 2)), (filter_cat, brand, round(0.5 * budget0, 2)),
                       (filter_cat, brand, round(0.3 * budget0, 2)), (None, brand, round(0.6 * budget0, 2)),
                       (None, brand, round(0.3 * budget0, 2))]
        elif stage == "brand2":
            names = self._tf1_llm_models(brand, cat, key, value, budget0)
            searches = [(f"{brand} {name}", budget0) for name in names[:3]]
            searches += [(f"{brand} phone {spec}" if "phone" in cat else f"{brand} {spec} {cat}", budget0),
                         (f"{brand}", budget0), (f"{brand} {cat} {spec}", round(0.35 * budget0, 2))]
            filters = [(filter_cat, brand, round(0.9 * budget0, 2)), (filter_cat, brand, round(0.15 * budget0, 2)),
                       (None, brand, round(0.8 * budget0, 2))]
        elif stage == "alternates":
            searches = [(f"{spec} {cat}", now), (f"{cat} {spec_alt}", now), (f"{cat} {spec}", round(0.3 * now, 2)),
                        (f"{cat} {spec_extra}", now), (f"{cat} {spec}", round(0.7 * now, 2))]
            filters = [(filter_cat, None, round(0.8 * now, 2)), (filter_cat, None, round(0.5 * now, 2)),
                       (filter_cat, None, round(0.2 * now, 2))]
        elif stage == "alternates2":
            searches = [(f"{spec}", now), (f"{cat} {spec_alt}", round(0.5 * now, 2)),
                        (f"{spec_extra}", now), (f"{cat}", now)]
            filters = [(filter_cat, None, round(0.9 * now, 2)), (filter_cat, None, round(0.4 * now, 2))]
        elif stage == "recover1":
            searches = [(f"{cat} {spec}", now), (f"{spec} {cat}", now), (f"{brand} {cat} {spec}", now),
                        (f"{cat} {spec_alt}", now), (f"{cat} {spec}", round(0.6 * now, 2))]
            filters = [(filter_cat, None, now), (filter_cat, None, round(0.6 * now, 2)),
                       (filter_cat, None, round(0.3 * now, 2)), (filter_cat, brand, now), (None, brand, now)]
        elif stage == "recover2":
            searches = [(f"{cat} {spec_extra}", now), (f"{spec}", now), (f"{cat} {spec}", round(0.35 * now, 2)),
                        (f"{brand} {spec}", now), (f"{cat}", round(0.8 * now, 2))]
            filters = [(filter_cat, None, round(0.8 * now, 2)), (filter_cat, None, round(0.45 * now, 2)),
                       (filter_cat, None, round(0.15 * now, 2))]
        elif stage == "recover3":
            searches = [(f"{spec_alt}", now), (f"{cat} {spec_alt}", round(0.5 * now, 2)), (f"{cat}", now),
                        (f"{spec} {cat} cheap", now)]
            filters = [(None, brand, round(0.5 * now, 2)), (filter_cat, None, round(0.7 * now, 2))]
        # One stage = one group within the engine's load limits, so the engine never
        # splits it into extra turns (extra turns let scheduled budget cuts arrive).
        max_filters = min(MAX_FILTERS_PER_GROUP, 2)
        max_searches = min(MAX_SEARCHES_PER_GROUP, MAX_HEAVY_PER_GROUP - max_filters)
        acts: list = []
        n_search = 0
        for query, cap in searches:
            query = " ".join(query.split())
            if not query or n_search >= max_searches:
                continue
            sig = ("search", query.lower(), cap)
            if sig in self._tf1_issued:
                continue
            self._tf1_issued.add(sig)
            acts.append(action("search", query=query[:150], k=10, in_stock=True, max_price=cap))
            n_search += 1
        n_filter = 0
        for category, brand_name, cap in filters:
            if len(acts) >= ep.max_calls or n_filter >= max_filters:
                break
            brand_name = brand_name or None
            if category is None and brand_name is None:
                continue
            sig = ("filter", category, brand_name, cap)
            if sig in self._tf1_issued:
                continue
            self._tf1_issued.add(sig)
            acts.append(action("filter", category=category, brand=brand_name, max_price=cap, in_stock=True, k=10))
            n_filter += 1
        return acts[: ep.max_calls]

    def _tf1_llm_models(self, brand: str, cat: str, key, value, budget: float) -> list:
        """Optional: model names to search for (empty when the LLM is off or unsure)."""

        # llm_json can take ~42 s (2 attempts x 20 s + backoff); keep well clear of _tf1_low()'s
        # 80 s threshold, which would otherwise force an early non-preferred fallback commit.
        if not brand or self.ep.time_left() < 150:
            return []
        try:
            answer = llm_json(
                "You know consumer electronics catalogs. List up to 3 model names (no brand) of "
                f"{brand} {cat or 'products'} with {_tf1_spec_phrase(key, value)} that could cost under "
                f"{fmt_money(budget)} {self.ep.currency}. Return {{\"models\": [..]}}.",
                f"{brand} {cat}", max_tokens=150, timeout=20.0,
            )
        except Exception:  # noqa: BLE001
            answer = None
        models = answer.get("models") if isinstance(answer, dict) else None
        if not isinstance(models, list):
            return []
        return [str(m).strip()[:60] for m in models if str(m).strip()][:3]

# ========================================================================
# families/tf2_retrieval_recall.py
# ========================================================================

import re
from collections import Counter
from typing import Optional


# ---------------------------------------------------------------------------
# Public text parsing
# ---------------------------------------------------------------------------

_TF2_GOAL_RE = re.compile(
    r"in the (?P<category>.+?) category that match(?:es)?\s+"
    r"(?:[\"“](?P<qphrase>[^\"”]+)[\"”]|the phrase (?P<uphrase>.+?))\s*,\s*"
    r"(?:at or under|under|up to|below|at most|no more than|within)\s+(?:PHP|₱)?\s*"
    r"(?P<budget>[0-9][0-9,]*(?:\.[0-9]+)?)\s*(?P<currency>[A-Z]{3})?",
    re.I,
)
_TF2_CATEGORY_RES = (
    re.compile(r"\bin the (.+?) category\b", re.I),
    re.compile(r"\bfrom the (.+?) (?:category|section|department)\b", re.I),
    re.compile(r"\bcategory(?: is|:)\s+['\"“]?([A-Z][^,.;:'\"”]{1,60})", re.I),
)
_TF2_QUOTED_RES = (
    re.compile(r"[\"“]([^\"”]{1,120})[\"”]"),
    re.compile(r"‘([^’]{1,120})’"),
    re.compile(r"(?:^|\s)'([^']{1,80})'(?=[\s,.;:]|$)"),
)
_TF2_PHRASE_END = (
    r"['\"”’]?\s*(?:,|;|:|\.(?:\s|$)|$|\s(?:at or under|under|below|for|within|up to|at most|"
    r"no more than|priced|costing|and buy|and order|in the|from the|in stock)\b)"
)
_TF2_PHRASE_RES = (
    re.compile(r"\bthe phrase\s+['\"“‘]?([a-z0-9][^,;:!?\"”]{0,80}?)" + _TF2_PHRASE_END, re.I),
    re.compile(r"\bthe (?:words?|terms?|keywords?)\s+['\"“‘]?([a-z0-9][^,;:!?\"”]{0,80}?)"
               + _TF2_PHRASE_END, re.I),
    re.compile(r"\b(?:matching|matches|match|titled|called|named|containing|contains)\s+['\"“‘]?"
               r"([a-z0-9][^,;:!?\"”]{0,80}?)" + _TF2_PHRASE_END, re.I),
)
_TF2_MONEY_CUR_RE = re.compile(r"([0-9][0-9,]*(?:\.[0-9]+)?)\s*(PHP|[A-Z]{3})\b")
_TF2_MIN_RE = re.compile(r"surface at least (\d+) distinct matching product identities", re.I)
_TF2_CUT_LINE_RE = re.compile(r"budget|balance|afford|spend|can only|no more than|at most", re.I)
_TF2_CUT_RE = re.compile(
    r"(?:budget|balance|afford|spend|up to|at most|no more than|max(?:imum)?|cap|limit)"
    r"[^0-9\n]{0,30}?(?:PHP|₱)?\s*([0-9][0-9,]*(?:\.[0-9]+)?)",
    re.I,
)

# Title words that carry no sub-type signal (marketplace filler).
_TF2_STOP = frozenset(
    "the and for with of a an in on to by or at from new free sale hot best top original "
    "authentic genuine high quality premium pcs pc set pack piece pieces item items cod ready "
    "stock local seller shipping ship fast delivery ph philippines brand official store shop "
    "promo discount cheap buy get one sold per size color colour style type edition version "
    "g kg mg ml l oz lb cm mm inch x".split()
)
_TF2_GENERIC_BRANDS = frozenset(
    {"no brand", "nobrand", "oem", "generic", "none", "unbranded", "n a", "na", "other",
     "others", "local", "unknown", "no", "non brand"}
)
_TF2_MAX_QUERIES = 3
_TF2_SEARCHES_PER_GROUP = 4


def _tf2_norm(text: object) -> str:
    return " ".join(re.findall(r"[a-z0-9]+", str(text or "").casefold()))


def _tf2_theme(phrase: str) -> list:
    out: list = []
    for tok in re.findall(r"[a-z0-9]+", (phrase or "").lower()):
        if tok not in out:
            out.append(tok)
    return out


def _tf2_parse_goal(goal: str) -> dict:
    """category / phrase / theme / budget / currency from the goal line (template first)."""

    out: dict = {"category": None, "phrase": None, "theme": [], "budget": None, "currency": None}
    match = _TF2_GOAL_RE.search(goal)
    if match:
        out["category"] = match.group("category").strip()
        phrase = match.group("qphrase") if match.group("qphrase") is not None else match.group("uphrase")
        out["phrase"] = (phrase or "").strip().strip("'\"")
        out["budget"] = parse_money(match.group("budget"))
        if match.group("currency"):
            out["currency"] = match.group("currency").upper()
    if out["category"] is None:
        for pattern in _TF2_CATEGORY_RES:
            found = pattern.search(goal)
            if found:
                out["category"] = found.group(1).strip()
                break
    if out["category"]:
        out["category"] = out["category"].strip().strip("'\"“”‘’").strip() or None
    if not out["phrase"]:
        quoted = [m.group(1).strip() for pattern in _TF2_QUOTED_RES for m in pattern.finditer(goal)]
        quoted = [q for q in quoted if _tf2_theme(q) and q != out["category"]]
        if quoted:
            out["phrase"] = quoted[0]
    if not out["phrase"]:
        for pattern in _TF2_PHRASE_RES:
            found = pattern.search(goal)
            if found and _tf2_theme(found.group(1)):
                out["phrase"] = found.group(1).strip()
                break
    if out["budget"] is None:
        out["budget"] = parse_budget(goal)
    if out["currency"] is None:
        money = _TF2_MONEY_CUR_RE.search(goal)
        if money:
            out["currency"] = money.group(2).upper()
    out["theme"] = _tf2_theme(out["phrase"] or "")
    return out


def _tf2_model_token(facts: object) -> Optional[str]:
    """retrieval_recall._model_tokens on the visible facts.model value."""

    value = (facts or {}).get("model") if isinstance(facts, dict) else None
    if not value:
        return None
    token = "".join(re.findall(r"[a-z0-9]+", str(value).casefold()))
    if 5 <= len(token) <= 24 and any(c.isdigit() for c in token):
        return token
    return None


def _tf2_count_identities(items: dict) -> int:
    """Upper-bound port of retrieval_recall.relevance_clusters over visible data.

    items: key -> (brand, title_token_set, price, model_token or None).
    """

    keys = sorted(items)
    parent = {k: k for k in keys}

    def find(k: str) -> str:
        while parent[k] != k:
            parent[k] = parent[parent[k]]
            k = parent[k]
        return k

    def union(a: str, b: str) -> None:
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[max(ra, rb)] = min(ra, rb)

    by_pid: dict = {}
    for key in keys:
        by_pid.setdefault(key.split("::", 1)[0], []).append(key)
    for members in by_pid.values():
        for other in members[1:]:
            union(members[0], other)
    anchors: dict = {}
    twins: dict = {}
    for _pid, members in sorted(by_pid.items()):
        anchor = members[0]
        for key in members:
            token = items[key][3]
            if token:
                if token in anchors:
                    union(anchors[token], anchor)
                else:
                    anchors[token] = anchor
        brand, toks, price, _model = items[anchor]
        twins.setdefault((brand, toks), []).append((float(price or 0.0), anchor))
    for rows in twins.values():
        rows.sort()
        for (pa, ka), (pb, kb) in zip(rows, rows[1:]):
            if abs(pa - pb) <= 0.01:
                union(ka, kb)
    return len({find(k) for k in keys})


# ---------------------------------------------------------------------------
# Engine: wait for a late (turn- or count-triggered) event before choosing the final
# ---------------------------------------------------------------------------


class _TF2Engine(Engine):
    """Engine plus read probes while no event is visible after the commit turn.

    Pack events fire on the first add (the probe is idle there).  A solver_turn trigger
    stocks out the last cart row at a later turn start and an nth-add trigger needs more
    adds; ordering before the change is visible would be a blind recovery (reward 0).
    """

    _tf2_max_probes = 10

    def _choose_final(self, plan: Plan) -> Optional[Candidate]:
        strategy = self.strategy
        for probe_no in range(self._tf2_max_probes):
            ep = self.ep
            if ep.done or ep.first_add is None or strategy.tf2_event_seen():
                break
            if ep.turns_left() <= 4 or ep.time_left() < 45.0:
                break
            group = strategy.tf2_probe_group(probe_no)
            if not group:
                break
            self.env.call(group)
        return super()._choose_final(plan)


# ---------------------------------------------------------------------------
# Strategy
# ---------------------------------------------------------------------------


@register_strategy
class RetrievalRecallStrategy(Strategy):
    family = "retrieval_recall"
    max_research_rounds = 9
    max_recovery_rounds = 5
    engine_cls = _TF2Engine

    def __init__(self, ep) -> None:
        super().__init__(ep)
        self.tf2_goal: dict = {}
        self.tf2_theme: list = []
        self.tf2_category: Optional[str] = None
        self.tf2_hard_budget: Optional[float] = None
        self.tf2_min_ids: Optional[int] = None
        self.tf2_fallback = False
        self.tf2_queries: list = []  # distinct search strings, in issue order (<= 3)
        self.tf2_stage = 0
        self.tf2_research_done = False
        self.tf2_rounds = 0
        self.tf2_topups = 0
        self.tf2_unknown_rounds = 0
        self.tf2_llm_words: Optional[list] = None
        self.tf2_llm_rank: dict = {}
        self._tf2_filters_issued: set = set()
        self._tf2_essential_issued: set = set()
        self._tf2_compared: set = set()
        self._tf2_msg_index = 0
        self._tf2_filter_sig = -1
        self._tf2_proven: set = set()  # pids shown by a filter(category=C)
        self._tf2_refuted: set = set()  # keys proven outside C by a complete filter list
        self._tf2_inconclusive: dict = {}  # key -> number of full brand lists without it
        self._tf2_probe_added: set = set()

    # -- parsing -------------------------------------------------------------
    def parse(self) -> None:
        ep = self.ep
        goal = _tf2_parse_goal(ep.goal_text)
        if not goal["theme"] or not goal["category"]:
            extra = llm_json(
                "You extract fields from an online shopping request.",
                "Request: " + ep.goal_text[:600] + "\nReturn {\"category\": <catalog category "
                "named in the request>, \"phrase\": <the words the listing title must contain>, "
                "\"budget\": <number>}.",
                max_tokens=120, timeout=20.0,
            )
            if isinstance(extra, dict):
                if not goal["category"] and isinstance(extra.get("category"), str):
                    goal["category"] = extra["category"].strip() or None
                if not goal["theme"] and isinstance(extra.get("phrase"), str):
                    goal["phrase"] = extra["phrase"]
                    goal["theme"] = _tf2_theme(extra["phrase"])
                if goal["budget"] is None:
                    goal["budget"] = parse_money(extra.get("budget"))
        self.tf2_goal = goal
        self.tf2_theme = list(goal["theme"])
        self.tf2_category = goal["category"]
        if goal["currency"]:
            ep.currency = goal["currency"]
        ep.set_budget(goal["budget"])
        self.tf2_hard_budget = goal["budget"]
        found = _TF2_MIN_RE.search(ep.query)
        self.tf2_min_ids = int(found.group(1)) if found else None
        self.tf2_fallback = not self.tf2_theme or self.tf2_hard_budget is None
        ep.intent.update({
            "category": self.tf2_category, "theme": self.tf2_theme,
            "min_identities": self.tf2_min_ids, "fallback": self.tf2_fallback,
        })
        if self.tf2_fallback:
            ep.notes.append("tf2: goal not parsed, generic fallback")
            super().parse()

    # -- shopper lines -------------------------------------------------------------
    def _tf2_sync(self) -> None:
        """Budget cuts in phrasings the core regex misses ('my budget is now 200 PHP')."""

        ep = self.ep
        for _turn, text in ep.shopper_messages[self._tf2_msg_index:]:
            for line in text.split("\n"):
                if not _TF2_CUT_LINE_RE.search(line):
                    continue
                for match in _TF2_CUT_RE.finditer(line):
                    value = parse_money(match.group(1))
                    floor = 0.1 * (self.tf2_hard_budget or 0.0)
                    if value is None or ep.budget is None or not floor < value < ep.budget - 1e-9:
                        continue
                    ep.notes.append(f"tf2 budget cut {ep.budget} -> {value}")
                    ep.budget = value
        self._tf2_msg_index = len(ep.shopper_messages)

    # -- pool membership -----------------------------------------------------------
    def _tf2_title_ok(self, pid: str) -> bool:
        return bool(self.tf2_theme) and set(self.tf2_theme) <= title_tokens(self.ep.product(pid).title)

    def _tf2_price_ok(self, key: str) -> bool:
        price = self.ep.price(key)
        cap = self.tf2_hard_budget
        return price is not None and cap is not None and price <= cap + 1e-9

    def _tf2_same_category(self, value: object) -> bool:
        return value is not None and _tf2_norm(value) == _tf2_norm(self.tf2_category)

    def _tf2_refresh_filters(self) -> None:
        """Category evidence from every filter(category=C) result seen so far."""

        ep = self.ep
        if self._tf2_filter_sig == len(ep.searches):
            return
        self._tf2_filter_sig = len(ep.searches)
        proven: set = set()
        refuted: set = set()
        inconclusive: Counter = Counter()
        lists = [(args, keys) for (_t, name, args, keys) in ep.searches
                 if name == "filter" and self._tf2_same_category(args.get("category"))]
        for _args, keys in lists:
            for key in keys:
                proven.add(split_key(key)[0])
        candidates = [k for k in ep.known_keys() if self._tf2_title_ok(split_key(k)[0])]
        for args, keys in lists:
            shown = set(keys)
            try:
                k_arg = max(1, min(int(args.get("k") or 10), 10))
            except (TypeError, ValueError):
                k_arg = 10
            complete = len(keys) < k_arg
            brand = args.get("brand")
            cap = parse_money(args.get("max_price"))
            for key in candidates:
                pid, _sku = split_key(key)
                if key in shown or pid in proven:
                    continue
                product = ep.product(pid)
                if brand and not (product.brand and brand_matches(brand, product.brand)):
                    continue
                price = ep.price(key)
                if price is None or (cap is not None and price > cap + 1e-9):
                    continue
                if complete:
                    refuted.add(key)
                elif brand:
                    inconclusive[key] += 1
        self._tf2_proven, self._tf2_refuted = proven, refuted
        self._tf2_inconclusive = dict(inconclusive)

    def tf2_status(self, key: str) -> str:
        """'yes' (compare-verified pool) | 'proven' (filter-proven) | 'unknown' | 'no'."""

        ep = self.ep
        pid, _sku = split_key(key)
        if not self._tf2_title_ok(pid) or not self._tf2_price_ok(key):
            return "no"
        product = ep.product(pid)
        if product.detailed:
            ok = category_matches(self.tf2_category, product.category_path, title=product.title)
            return "yes" if ok else "no"
        self._tf2_refresh_filters()
        if pid in self._tf2_proven:
            return "proven"
        if key in self._tf2_refuted:
            return "no"
        return "unknown"

    def _tf2_keys(self, *statuses: str) -> list:
        return [k for k in self.ep.known_keys() if self.tf2_status(k) in statuses]

    def _tf2_rank(self) -> dict:
        """key -> (query index, position) of its first search/filter appearance."""

        ep = self.ep
        rank: dict = {}
        for position, (_t, name, args, keys) in enumerate(ep.searches):
            query = args.get("query") if name == "search" else None
            qi = self.tf2_queries.index(query) if query in self.tf2_queries else 9
            for i, key in enumerate(keys):
                rank.setdefault(key, (qi, position * 100 + i))
        return rank

    def candidate_ok(self, key: str) -> bool:
        if self.tf2_fallback:
            return super().candidate_ok(key)
        return self.tf2_status(key) in ("yes", "proven")

    def candidate_score(self, key: str) -> float:
        bonus = 1e6 if not self.tf2_fallback and self.tf2_status(key) == "yes" else 0.0
        return bonus - (self.ep.price(key) or 0.0)

    # -- identity estimate -----------------------------------------------------------
    def tf2_identity_estimate(self) -> int:
        ep = self.ep
        items: dict = {}
        for key in ep.known_keys():
            if self.tf2_status(key) == "no":
                continue
            pid, _sku = split_key(key)
            product = ep.product(pid)
            items[key] = (
                (product.brand or "").strip().lower(), title_tokens(product.title),
                ep.price(key), _tf2_model_token(product.facts) if product.detailed else None,
            )
        return _tf2_count_identities(items) if items else 0

    def _tf2_target(self) -> int:
        n = self.tf2_min_ids or 5
        if n >= 5:
            return 13
        if n == 4:
            return 10
        return 8

    # -- query construction -------------------------------------------------------------
    def _tf2_q1(self) -> str:
        return " ".join(self.tf2_theme)

    def _tf2_cotokens(self, exclude: set) -> list:
        """Title words co-occurring with the theme across distinct naive identities.

        Words of a flooding signature (one brand + title seen on >= 3 rows) are dropped: they
        would lift the same duplicates again.  Refuted and non-matching titles never vote.
        """

        ep = self.ep
        rows: Counter = Counter()
        brand_words: set = set()
        theme = set(self.tf2_theme)
        keys = [k for k in ep.known_keys() if self.tf2_status(k) != "no"]
        if not keys:
            # no title match visible yet (stemmed near-misses fill the top): borrow the
            # vocabulary of rows sharing any theme word
            keys = [k for k in ep.known_keys()
                    if theme & title_tokens(ep.product(split_key(k)[0]).title)]
        for key in keys:
            pid, _sku = split_key(key)
            product = ep.product(pid)
            brand_words |= set(re.findall(r"[a-z0-9]+", (product.brand or "").casefold()))
            rows[((product.brand or "").strip().lower(), title_tokens(product.title))] += 1
        banned = set(self.tf2_theme) | set(exclude) | brand_words | _TF2_STOP
        banned |= set(re.findall(r"[a-z0-9]+", (self.tf2_category or "").lower()))
        for (_brand, toks), n in rows.items():
            if n >= 3:
                banned |= set(toks)
        sigs = [sig for sig, n in rows.items() if n < 3]
        df: Counter = Counter()
        for (_brand, toks) in sigs:
            for tok in toks:
                if tok in banned or len(tok) < 3 or any(c.isdigit() for c in tok):
                    continue
                df[tok] += 1
        total = max(1, len(sigs))
        ranked = sorted(df.items(), key=lambda kv: (-(kv[1] if kv[1] < total else 0), -kv[1], kv[0]))
        return [tok for tok, _n in ranked]

    def _tf2_llm_extra_words(self) -> list:
        if self.tf2_llm_words is not None:
            return self.tf2_llm_words
        self.tf2_llm_words = []
        if self.ep.time_left() < 150.0:
            return []
        titles = []
        for key in self._tf2_keys("yes", "proven", "unknown")[:12]:
            titles.append(self.ep.product(split_key(key)[0]).title[:90])
        data = llm_json(
            "You help an online-shop search engine find more listings.",
            f'Category: {self.tf2_category}. Every wanted listing title contains the words '
            f'"{self._tf2_q1()}". Titles seen so far:\n- ' + "\n- ".join(titles) +
            "\nGive 4 single lowercase words that often appear in OTHER such listing titles "
            "(product sub-types, flavours, sizes, materials, uses), not words already shown. "
            'Return {"words": [...]}.',
            max_tokens=120, timeout=20.0,
        )
        words = data.get("words") if isinstance(data, dict) else data if isinstance(data, list) else None
        out: list = []
        for word in words or []:
            for tok in re.findall(r"[a-z0-9]+", str(word).lower()):
                if tok not in self.tf2_theme and tok not in _TF2_STOP and len(tok) >= 3 and tok not in out:
                    out.append(tok)
        self.tf2_llm_words = out[:4]
        return self.tf2_llm_words

    def _tf2_reformulation(self) -> Optional[str]:
        """The next query string: the theme plus up to 3 extra title words (theme repeated
        so title matches stay on top).  Q2 uses co-occurring title words; Q3 (built a round
        later, after the category checks) uses LLM words when available, else fresh ones."""

        if len(self.tf2_queries) >= _TF2_MAX_QUERIES:
            return None
        q1 = self._tf2_q1()
        used = {t for q in self.tf2_queries for t in q.split()}
        words: list = []
        if len(self.tf2_queries) >= 2:
            words = [w for w in self._tf2_llm_extra_words() if w not in used]
        if len(words) < 2:
            words += [w for w in self._tf2_cotokens(used) if w not in words]
        if not words:
            return None
        query = f"{q1} {' '.join(words[:3])} {q1}"
        return None if query in self.tf2_queries else query

    def _tf2_search(self, query: str, cap: Optional[float]) -> Optional[dict]:
        if query not in self.tf2_queries:
            if len(self.tf2_queries) >= _TF2_MAX_QUERIES:
                return None
            self.tf2_queries.append(query)
        cap = round(cap, 2) if cap is not None else None
        return action("search", query=query, k=10, max_price=cap)

    def _tf2_rungs(self, query: str) -> list:
        """(cap, [row prices]) of every search already issued with this exact string."""

        ep = self.ep
        out = []
        for (_t, name, args, keys) in ep.searches:
            if name != "search" or args.get("query") != query:
                continue
            cap = parse_money(args.get("max_price"))
            prices = [ep.price(k) for k in keys if ep.price(k) is not None]
            out.append((cap if cap is not None else float("inf"), sorted(prices), len(keys)))
        return out

    def _tf2_next_caps(self, query: str, limit: int, ceiling: Optional[float] = None) -> list:
        """Caps that should surface mostly unseen rows of this query's BM25 top 50."""

        top = ceiling if ceiling is not None else self.tf2_hard_budget
        if top is None or limit <= 0:
            return []
        rungs = self._tf2_rungs(query)
        if not rungs:
            return [top]
        used = [cap for cap, _p, _n in rungs]
        floor = max([cap for cap, _p, n in rungs if n < 10 and cap != float("inf")] + [0.0])
        if any(n < 10 and cap >= top - 1e-9 for cap, _p, n in rungs):
            return []  # everything under the ceiling is already visible
        scored = []
        for cap, prices, n in rungs:
            if n < 10 or not prices:
                continue
            for idx in (2, len(prices) // 2):
                if idx >= len(prices):
                    continue
                cand = round(prices[idx] - 0.01, 2)
                if cand > top or cand <= floor + 0.01 or cand < 0.01 * top:
                    continue
                if any(abs(cand - u) <= max(0.02, 0.01 * u) for u in used if u != float("inf")):
                    continue
                parent = min([u for u in used if u >= cand], default=None)
                parent_rows = next((p for c, p, _n in rungs if c == parent), prices)
                reappear = sum(1 for p in parent_rows if p <= cand + 1e-9)
                room = 10 - reappear
                if room >= 3:
                    scored.append((-room, -cand, cand))
        scored.sort()
        caps: list = []
        for _r, _c, cand in scored:
            if all(abs(cand - c) > max(0.02, 0.03 * c) for c in caps):
                caps.append(cand)
            if len(caps) >= limit:
                break
        return caps

    # -- category checks ------------------------------------------------------------
    def _tf2_brand_plans(self, budget_cap: Optional[float] = None) -> list:
        """Pending category checks: (priority, brand norm, brand, cap, essential).

        The first check of a brand uses the brand's highest candidate price; when that list
        comes back full (inconclusive), each listing is re-checked at its own price (fewer
        rivals sort ahead of it).  Generic brands ('No Brand', 'OEM') rarely resolve, so
        their re-checks are not essential (unproven compares need not wait for them).
        """

        ep = self.ep
        if not self.tf2_category:
            return []
        self._tf2_refresh_filters()
        rank = self._tf2_rank()
        by_brand: dict = {}
        for key in self._tf2_keys("unknown"):
            pid, _sku = split_key(key)
            if ep.product(pid).detailed:
                continue
            brand = (ep.product(pid).brand or "").strip()
            norm = _tf2_norm(brand)
            if not norm:
                continue
            price = ep.price(key)
            if price is None or (budget_cap is not None and price > budget_cap + 1e-9):
                continue
            by_brand.setdefault(norm, {"brand": brand, "keys": []})["keys"].append((price, key))
        plans = []
        for norm, info in by_brand.items():
            rows = sorted(info["keys"])
            generic = norm in _TF2_GENERIC_BRANDS
            best = min(rank.get(k, (9, 10**9)) for _p, k in rows)
            wide = round(max(p for p, _k in rows), 2)
            if (norm, wide) not in self._tf2_filters_issued:
                plans.append(((generic, 0, -len(rows), best), norm, info["brand"], wide, True))
                continue
            own_caps = []
            for price, key in rows:
                own = round(price, 2)
                if (self._tf2_inconclusive.get(key) and (norm, own) not in self._tf2_filters_issued
                        and own not in own_caps):
                    own_caps.append(own)
            for own in own_caps[:3]:
                plans.append(((generic, 1, -len(rows), best), norm, info["brand"], own, not generic))
        plans.sort(key=lambda t: t[0])
        return plans

    def _tf2_brand_filters(self, limit: int, budget_cap: Optional[float] = None) -> list:
        """filter(category=C, brand=b, max_price=p) for unproven candidates (precision-free)."""

        if limit <= 0:
            return []
        acts = []
        for _prio, norm, brand, cap, essential in self._tf2_brand_plans(budget_cap)[:limit]:
            self._tf2_filters_issued.add((norm, cap))
            if essential:
                self._tf2_essential_issued.add((norm, cap))
            acts.append(action("filter", category=self.tf2_category, brand=brand, max_price=cap, k=10))
        return acts

    def _tf2_checks_outstanding(self) -> bool:
        """True while an essential category check is queued or has not come back yet."""

        ep = self.ep
        done = {(_tf2_norm(args.get("brand")), parse_money(args.get("max_price")))
                for (_t, name, args, _k) in ep.searches if name == "filter" and args.get("brand")}
        if any((norm, cap) not in done for norm, cap in self._tf2_essential_issued):
            return True
        return any(plan[4] for plan in self._tf2_brand_plans())

    # -- compares ---------------------------------------------------------------------
    def _tf2_compare(self, pids: list) -> list:
        acts = []
        pids = [p for p in dict.fromkeys(pids) if p not in self._tf2_compared]
        for i in range(0, len(pids), COMPARE_LIMIT):
            chunk = pids[i:i + COMPARE_LIMIT]
            self._tf2_compared.update(chunk)
            acts.append(action("compare", product_ids=chunk))
        return acts

    def _tf2_signature(self, key: str) -> tuple:
        """Naive identity signature: brand + title-token set + price (twins share one)."""

        product = self.ep.product(split_key(key)[0])
        return ((product.brand or "").strip().lower(), title_tokens(product.title),
                round(self.ep.price(key) or 0.0, 1))

    def _tf2_proven_pids(self, limit: int, budget_cap: Optional[float] = None) -> list:
        """Filter-proven listings to compare (pool items: precision-neutral), one per
        naive identity first -- comparing ten duplicates of one listing adds nothing."""

        ep = self.ep
        rank = self._tf2_rank()
        covered = {self._tf2_signature(k) for k in self._tf2_keys("yes")}
        covered |= {self._tf2_signature(k) for k in ep.known_keys()
                    if split_key(k)[0] in self._tf2_compared}
        rows = []
        for key in self._tf2_keys("proven"):
            pid, _sku = split_key(key)
            if pid in self._tf2_compared or ep.product(pid).detailed:
                continue
            price = ep.price(key) or 0.0
            if budget_cap is not None and price > budget_cap + 1e-9:
                continue
            rows.append((rank.get(key, (9, 10**9)), price, pid, self._tf2_signature(key)))
        rows.sort(key=lambda r: (r[0], r[1], r[2]))
        first, rest = [], []
        for _r, _p, pid, sig in rows:
            if sig in covered:
                rest.append(pid)
            else:
                covered.add(sig)
                first.append(pid)
        have = len({split_key(k)[0] for k in self._tf2_keys("yes")}) + len(first)
        extra = rest[: max(0, 2 - have)]  # duplicates only while two verified items are missing
        return list(dict.fromkeys(first + extra))[:limit]

    def _tf2_token_evidence(self) -> tuple:
        """(in-category words, out-of-category words) learned from verified/refuted titles."""

        ep = self.ep
        pos: set = set()
        neg: set = set()
        theme = set(self.tf2_theme)
        self._tf2_refresh_filters()
        for key in ep.known_keys():
            pid, _sku = split_key(key)
            product = ep.product(pid)
            words = {t for t in title_tokens(product.title) - theme if t not in _TF2_STOP and len(t) >= 3}
            if product.detailed:
                ok = category_matches(self.tf2_category, product.category_path, title=product.title)
                (pos if ok else neg).update(words)
            elif pid in self._tf2_proven:
                pos.update(words)
            elif key in self._tf2_refuted:
                neg.update(words)
        return pos - neg, neg - pos

    def _tf2_unknown_pids(self, limit: int, budget_cap: Optional[float] = None) -> list:
        """Unproven listings to compare (precision risk): the most plausible first."""

        ep = self.ep
        rank = self._tf2_rank()
        pos, neg = self._tf2_token_evidence()
        theme = set(self.tf2_theme)
        rows = []
        for key in self._tf2_keys("unknown"):
            pid, _sku = split_key(key)
            if pid in self._tf2_compared or ep.product(pid).detailed:
                continue
            price = ep.price(key) or 0.0
            if budget_cap is not None and price > budget_cap + 1e-9:
                continue
            brand = _tf2_norm(ep.product(pid).brand)
            plaus = self.tf2_llm_rank.get(pid, 0.5)
            words = title_tokens(ep.product(pid).title) - theme
            evidence = len(words & pos) - 2 * len(words & neg)
            rows.append((-plaus, -evidence, not brand or brand in _TF2_GENERIC_BRANDS,
                         rank.get(key, (9, 10**9)), price, pid))
        rows.sort()
        pids = list(dict.fromkeys(r[-1] for r in rows))
        if len(pids) > limit and not self.tf2_llm_rank:
            self._tf2_llm_plausibility(pids[:8])
            if self.tf2_llm_rank:
                return self._tf2_unknown_pids(limit, budget_cap)
        return pids[:limit]

    def _tf2_llm_plausibility(self, pids: list) -> None:
        """Optional: ask the LLM which unproven titles belong in the category."""

        if self.ep.time_left() < 90.0:
            self.tf2_llm_rank = {pid: 0.5 for pid in pids}
            return
        listing = "\n".join(f"{i}. {self.ep.product(p).title[:100]}" for i, p in enumerate(pids))
        data = llm_json(
            "You classify online-shop listings into catalog categories.",
            f"Catalog category: {self.tf2_category}.\nListings:\n{listing}\n"
            "For each listing give the probability (0-1) that it is filed under that category "
            '(not an accessory for it or a different product type). Return {"p": [numbers in order]}.',
            max_tokens=120, timeout=20.0,
        )
        values = data.get("p") if isinstance(data, dict) else None
        rank = {pid: 0.5 for pid in pids}
        if isinstance(values, list):
            for pid, value in zip(pids, values):
                try:
                    rank[pid] = max(0.0, min(1.0, float(value)))
                except (TypeError, ValueError):
                    pass
        self.tf2_llm_rank = rank

    # -- research -------------------------------------------------------------------
    def _tf2_enough(self) -> bool:
        """Two verified pool items, at least one of them within the current budget."""

        ep = self.ep
        yes = [k for k in self._tf2_keys("yes") if ep.in_stock(k) is not False and k not in ep.excluded]
        return len(yes) >= 2 and any(ep.affordable(k) for k in yes)

    def _tf2_must_stop(self) -> bool:
        ep = self.ep
        return (self.tf2_rounds >= self.max_research_rounds or ep.time_left() < 40.0
                or ep.turns_left() <= 5)

    def research_actions(self, round_no: int) -> list:
        self.tf2_rounds = round_no + 1
        if self.tf2_fallback:
            return super().research_actions(round_no)
        self._tf2_sync()
        acts = self._tf2_stage_actions()
        if not acts:
            self.tf2_research_done = True
        return acts

    def _tf2_stage_actions(self) -> list:
        ep = self.ep
        B = self.tf2_hard_budget
        q1 = self._tf2_q1()
        while True:
            stage = self.tf2_stage
            self.tf2_stage += 1
            if stage == 0:
                acts = [self._tf2_search(q1, B), self._tf2_search(q1, B * 0.5),
                        self._tf2_search(q1, B * 0.25)]
                if self.tf2_category:
                    acts.append(action("filter", category=self.tf2_category, max_price=round(B, 2), k=10))
                return [a for a in acts if a]
            if stage == 1:
                # adaptive Q1 rungs + the first category checks (so Q2's words can skip
                # titles a filter has already refuted)
                acts = [self._tf2_search(q1, cap) for cap in self._tf2_next_caps(q1, 3)]
                acts = [a for a in acts if a]
                acts += self._tf2_brand_filters(10 - len(acts))
                if acts:
                    return acts
                continue
            if stage in (2, 3):
                acts = []
                query = self._tf2_reformulation()
                if query:
                    acts.append(self._tf2_search(query, B))
                if stage == 2 or ep.time_left() > 90.0:
                    acts += self._tf2_extra_rungs(_TF2_SEARCHES_PER_GROUP - len(acts), skip=query)
                acts = [a for a in acts if a]
                acts += self._tf2_brand_filters(max(0, 10 - len(acts) - 2))
                acts += self._tf2_compare(self._tf2_proven_pids(10))
                if stage == 3:
                    acts += self._tf2_unknown_compares()
                if acts:
                    return acts
                continue
            # stage >= 4: what is still missing for a safe commit + final, plus (at most twice)
            # recall top-up rungs while the identity estimate looks short.
            self.tf2_stage = 4
            acts = []
            enough = self._tf2_enough()
            if not enough:
                acts = self._tf2_compare(self._tf2_proven_pids(10))
                if not acts:
                    acts = self._tf2_unknown_compares(force=True)
            if self.tf2_topups < 2 and ep.time_left() > 100.0 and ep.turns_left() > 8:
                rungs = self._tf2_extra_rungs(_TF2_SEARCHES_PER_GROUP)
                if rungs:
                    self.tf2_topups += 1
                    acts += rungs
            if acts or not enough:
                acts += self._tf2_brand_filters(max(0, 9 - len(acts)))
            if not acts and not enough and ep.budget is not None and B is not None and ep.budget < B - 1e-9:
                acts = self._tf2_budget_searches(ep.budget)
            return acts

    def _tf2_extra_rungs(self, limit: int, skip: Optional[str] = None) -> list:
        """Adaptive max_price rungs over the existing strings while identities are short."""

        if limit <= 0 or self.tf2_identity_estimate() >= self._tf2_target():
            return []
        acts: list = []
        for query in list(self.tf2_queries):
            if len(acts) >= limit:
                break
            if query == skip:
                continue
            for cap in self._tf2_next_caps(query, 1 if len(self.tf2_queries) > 1 else 2):
                if len(acts) < limit:
                    act = self._tf2_search(query, cap)
                    if act:
                        acts.append(act)
        return acts

    def _tf2_unknown_compares(self, force: bool = False) -> list:
        """Compare unproven listings only when two verified pool items are still missing."""

        ep = self.ep
        yes = {split_key(k)[0] for k in self._tf2_keys("yes")}
        pending = {split_key(k)[0] for k in self._tf2_keys("proven")}  # compare outstanding
        have = len(yes | pending)
        if self.tf2_unknown_rounds >= 5:
            return []
        if self._tf2_checks_outstanding():
            return []  # a pending category check may prove or refute these listings for free
        cap = None
        if have >= 2:
            if not force or pending or self._tf2_enough():
                return []
            cap = ep.budget  # verified items exist, none fits the (cut) budget
        need = max(1, 2 - have)
        # One at a time while turns allow: each category_path seen sharpens the next pick.
        roomy = ep.turns_left() > 10 and ep.time_left() > 90.0
        pids = self._tf2_unknown_pids(1 if roomy else min(need, 2), budget_cap=cap)
        if not pids:
            return []
        self.tf2_unknown_rounds += 1
        ep.notes.append(f"tf2 unproven compare {pids}")
        return self._tf2_compare(pids)

    def _tf2_budget_searches(self, cap: float) -> list:
        acts = []
        for query in list(self.tf2_queries) or [self._tf2_q1()]:
            rung_caps = [c for c, _p, _n in self._tf2_rungs(query)]
            if all(abs(c - cap) > 0.01 for c in rung_caps):
                act = self._tf2_search(query, cap)
            else:
                caps = self._tf2_next_caps(query, 1, ceiling=cap)
                act = self._tf2_search(query, caps[0]) if caps else None
            if act:
                acts.append(act)
            if len(acts) >= _TF2_SEARCHES_PER_GROUP:
                break
        return acts

    # -- planning ---------------------------------------------------------------------
    def make_plan(self) -> Optional[Plan]:
        if self.tf2_fallback:
            return super().make_plan()
        self._tf2_sync()
        if not self.tf2_research_done and not self._tf2_must_stop():
            return None
        return self._tf2_select()

    def _tf2_select(self) -> Optional[Plan]:
        ep = self.ep
        rank = self._tf2_rank()
        usable = [k for k in self._tf2_keys("yes", "proven")
                  if ep.in_stock(k) is not False and k not in ep.excluded]
        if not usable:
            return None
        status = {k: self.tf2_status(k) for k in usable}

        def q1_tier(key: str) -> int:
            return 0 if rank.get(key, (9, 0))[0] == 0 else 1

        yes = [k for k in usable if status[k] == "yes"] or usable
        # Y first: the cheapest verified item within the current budget (survives cuts).
        finals_pool = sorted(
            usable,
            key=lambda k: (not ep.affordable(k), status[k] != "yes", q1_tier(k), ep.price(k) or 0.0, k),
        )
        y_key = next((k for k in finals_pool if ep.affordable(k)), None)
        # X: the most expensive verified item of another product (it gets stocked out).
        commit_pool = [k for k in yes if y_key is None or split_key(k)[0] != split_key(y_key)[0]]
        if not commit_pool:
            commit_pool = [k for k in yes if k != y_key]
        if not commit_pool:
            commit_pool = yes
        x_key = sorted(commit_pool, key=lambda k: (q1_tier(k), -(ep.price(k) or 0.0), k))[0]
        finals = [k for k in finals_pool if k != x_key]
        finals.sort(key=lambda k: (
            not ep.affordable(k), split_key(k)[0] == split_key(x_key)[0], status[k] != "yes",
            q1_tier(k), ep.price(k) or 0.0, k))
        commit = Candidate(*split_key(x_key), score=1.0, reason="commit")
        final_cands = [Candidate(*split_key(k), score=1.0) for k in finals]
        ep.notes.append(
            f"tf2 plan X={x_key} Y={finals[0] if finals else None} verified={len(yes)} "
            f"usable={len(usable)} identities~{self.tf2_identity_estimate()} "
            f"queries={len(self.tf2_queries)} budget={ep.budget}")
        return Plan(commit=commit, finals=final_cands, preadd=True)

    # -- after the event ---------------------------------------------------------------
    def finals_after_event(self) -> list:
        if self.tf2_fallback:
            return super().finals_after_event()
        self._tf2_sync()
        ep = self.ep
        planned = [f.key for f in self.plan.finals] if self.plan else []
        keys = [k for k in self._tf2_keys("yes", "proven") if self.final_ok(k)]
        order = {k: i for i, k in enumerate(planned)}
        keys.sort(key=lambda k: (
            k not in order, order.get(k, 0), self.tf2_status(k) != "yes", ep.price(k) or 0.0, k))
        return [Candidate(*split_key(k), score=1.0) for k in keys]

    def recovery_actions(self, round_no: int) -> list:
        if self.tf2_fallback:
            return super().recovery_actions(round_no)
        self._tf2_sync()
        ep = self.ep
        cap = ep.budget
        acts = self._tf2_compare(self._tf2_proven_pids(10, budget_cap=cap))
        unproven_ok = not self._tf2_checks_outstanding() or round_no >= 2
        acts += self._tf2_brand_filters(6)  # also completes the category evidence
        if round_no == 0 and cap is not None:
            acts += self._tf2_budget_searches(cap)
        if (round_no >= 1 or not acts) and unproven_ok:
            # Nothing proven fits: compare the most plausible unproven listing under the cap.
            if not any(self.final_ok(k) for k in self._tf2_keys("yes", "proven")):
                pids = self._tf2_unknown_pids(1 if ep.turns_left() > 6 else 2, budget_cap=cap)
                if pids:
                    ep.notes.append(f"tf2 recovery unproven compare {pids}")
                    acts += self._tf2_compare(pids)
        return acts

    def tf2_event_seen(self) -> bool:
        """The stockout is visible (TF2's validate_event_rule admits stockouts only).

        A re-read "price_change" is not an event here: core flags one whenever the first
        item re-reads above the CURRENT budget, which a delivered budget cut alone causes.
        """

        ep = self.ep
        event = ep.event
        if event is not None and not (event.source == "re-read" and event.kind != "stockout"):
            return True
        return any(ok and ep.in_stock(key) is False for (_t, _s, key, ok) in ep.adds)

    def tf2_probe_group(self, probe_no: int) -> list:
        """One read turn; from the second probe on, one sacrificial pool add (count triggers)."""

        ep = self.ep
        group: list = []
        if probe_no in (1, 2):
            sacrifice = self._tf2_probe_sacrifice()
            if sacrifice is not None:
                self._tf2_probe_added.add(sacrifice)
                pid, sku = split_key(sacrifice)
                group += [action("add_to_cart", product_id=pid, sku=sku),
                          action("inspect_stock", product_id=pid, sku=sku)]
        group.append(action("inspect_cart"))
        seen: set = set()
        for (_t, _s, key, ok) in ep.adds:
            if ok and key not in seen:
                seen.add(key)
                pid, sku = split_key(key)
                group.append(action("inspect_stock", product_id=pid, sku=sku))
        return group[: ep.max_calls]

    def _tf2_probe_sacrifice(self) -> Optional[str]:
        ep = self.ep
        in_cart = {key for (_t, _s, key, ok) in ep.adds if ok}
        finals = [c.key for c in self.finals_after_event() if c.key not in in_cart]
        keep = set(finals[:1])
        options = []
        for key in self._tf2_keys("yes", "proven"):
            if key in keep or key in in_cart or key in self._tf2_probe_added:
                continue
            if ep.in_stock(key) is not True:
                continue
            options.append((self.tf2_status(key) != "yes", -(ep.price(key) or 0.0), key))
        options.sort()
        return options[0][2] if options else None

    # -- ordering ------------------------------------------------------------------
    def order_message(self, cand: Candidate) -> str:
        ep = self.ep
        product = ep.product(cand.pid)
        price = ep.price(cand.key)
        price_text = f" at {fmt_money(price)} {ep.currency}" if price is not None else ""
        lead = "My first pick sold out, so " if ep.event is not None else ""
        phrase = self._tf2_q1() if not self.tf2_fallback else ""
        match = f"its title matches '{phrase}', " if phrase else ""
        return (
            f"{lead}I'm ordering {product.title or cand.pid} (SKU {cand.sku}){price_text}: "
            f"{match}it is in the {self.tf2_category or 'requested'} category, in stock and "
            "within your budget."
        )[:600]


__all__ = ["RetrievalRecallStrategy"]

# ========================================================================
# families/tf3_constraint_satisfaction.py
# ========================================================================

import re
from typing import Optional


# ---------------------------------------------------------------------------
# Public text parsing (goal template, sealed shopper answer, budget cuts)
# ---------------------------------------------------------------------------

_TF3_BUDGET_RE = re.compile(
    r"at or under\s+(?:PHP|₱)?\s*([0-9][0-9,]*(?:\.[0-9]+)?)\s*([A-Z]{3})?"
)
_TF3_GOAL_RE = re.compile(
    r"^\s*I need an?\s+(?P<item>.+?)(?:\s+with\s+(?P<spec>.+?))?,\s+at or under\s+", re.S
)
_TF3_UNDERSPEC_RE = re.compile(
    r"requirement on the spec that I will tell you if you ask|will tell you if you ask", re.I
)
_TF3_SPEC_PATTERNS = (
    ("ram", re.compile(r"(\d+(?:\.\d+)?)\s*(TB|GB) of RAM", re.I)),
    ("screen_size", re.compile(r"(\d+(?:\.\d+)?)\s*-\s*inch screen", re.I)),
    ("refresh_rate", re.compile(r"(\d+(?:\.\d+)?)\s*Hz refresh rate", re.I)),
    ("resolution", re.compile(r"\ban?\s+(4K|QHD|1080p Full HD|720p HD)\s+display\b")),
)
_TF3_RES_WORD = {"4k": "4k", "qhd": "qhd", "1080p full hd": "fhd", "720p hd": "hd"}
_TF3_CATEGORY_RE = re.compile(r"the required catalog category is ([^.\n]+)\.", re.I)
_TF3_BRAND_RE = re.compile(r"the required brand is ([^.\n]+)\.", re.I)
_TF3_CUT_RE = re.compile(
    r"(?:up to|at most|at or under|budget is(?: now)?)\s+(?:PHP|₱)?\s*([0-9][0-9,]*(?:\.[0-9]+)?)",
    re.I,
)
# A shopper line that re-states the budget in other words ("my budget dropped to 8000.00
# PHP"): only amounts written with the task currency, only in a budget-talk line that is
# not itself a question.
_TF3_BUDGET_TALK_RE = re.compile(
    r"\b(?:balance|budget|afford|spend|can only|go up to|limit|max(?:imum)?|cap)\b", re.I
)
# "still needs <spec phrase>" (the add_constraint template) re-states the firm spec.
_TF3_SPEC_RESTATE_RE = re.compile(r"\b(?:still\s+)?needs?\b|\bnon.negotiable\b|\bmust\b", re.I)
# Category words as the goal template renders them: category.lower() minus one trailing 's'.
_TF3_CATEGORY_WORDS = (
    "gaming monitor", "computer monitor", "graphics card", "video card", "mobile phone",
    "cell phone", "unlocked phone", "android phone", "smart watche", "smartwatche",
    "smart watch", "smartwatch", "smartphone", "smart phone", "gaming laptop", "laptop",
    "notebook", "tablet", "monitor", "desktop", "television", "tv", "headphone", "headset",
    "earbud", "phone", "camera", "speaker", "keyboard", "printer", "router",
)
# Lowercase words that belong to a category word, not to a brand ("a unlocked phone").
_TF3_CATEGORY_MODIFIERS = frozenset((
    "unlocked", "android", "gaming", "computer", "smart", "mobile", "cell", "wireless",
    "bluetooth", "portable", "curved", "ultrawide", "desktop", "laptop", "office", "5g",
))
_TF3_QUESTION = (
    "Before I choose: what is your firm spec requirement (screen size, RAM, resolution or "
    "refresh rate) and any other must-have requirements for the exact variant?"
)
_TF3_MAX_ASKS = 3
_TF3_ACCESSORY_RE = re.compile(
    r"\b(?:case|cases|cover|covers|protector|tempered|glass film|film|charger|cable|holder|"
    r"strap|pouch|skin|lens|stand|mount|adapter|replacement|sticker|bumper|sleeve)\b",
    re.I,
)
# Keys whose every verifier gate key is visible in view facts (size / refresh_rate):
# a product-level value the title states is then exact. For ram and resolution the
# verifier also reads keys the agent never sees ('installed memory', 'native
# resolution'), so a title-only value can hide a conflict that makes the SKU non-gold.
_TF3_TITLE_EXACT_KEYS = frozenset(("screen_size", "refresh_rate"))


def _tf3_conf(source: str, key: str) -> int:
    """3 = exact (SKU options, or the title for a fully visible key), 2 = title for
    ram/resolution, 1 = merged facts only (may come from a non-gate key), 0 = none."""

    if source == "options":
        return 3
    if source in ("title", "title+facts"):
        return 3 if key in _TF3_TITLE_EXACT_KEYS else 2
    return 1 if source == "facts" else 0


def _tf3_parse_spec(text: Optional[str]) -> Optional[tuple]:
    """(gated_key, canonical value) from the family's spec phrase, in verifier format."""

    if not text:
        return None
    for key, pattern in _TF3_SPEC_PATTERNS:
        match = pattern.search(text)
        if not match:
            continue
        if key == "resolution":
            return key, _TF3_RES_WORD[match.group(1).lower()]
        if key == "ram":
            scale = 1024 if match.group(2).upper() == "TB" else 1
            return key, f"{float(match.group(1)) * scale:g}gb"
        unit = {"screen_size": "in", "refresh_rate": "hz"}[key]
        return key, f"{float(match.group(1)):g}{unit}"
    return None


def _tf3_cat_word(category: Optional[str]) -> Optional[str]:
    """constraint_satisfaction._cat_word: category.lower() minus one trailing 's'."""

    if not category:
        return None
    low = " ".join(category.split()).lower()
    return low[:-1] if low.endswith("s") else low


def _tf3_split_item(item: str) -> tuple:
    """'<Brand> <category word>' -> (brand or None, category word, certain?).

    The brand is rendered verbatim and the category word in lowercase, so trailing
    lowercase modifier words of the would-be brand belong to the category word
    ('Zentrix gaming' + 'headset'). The split is certain only for a known category word,
    no moved words and a brand whose words all start upper-case or with a digit (a
    lowercase brand such as 'vivo' cannot be told from an unknown modifier).
    """

    item = " ".join((item or "").split())
    low = item.lower()
    known = False
    brand_part, cat = "", low
    for word in sorted(_TF3_CATEGORY_WORDS, key=len, reverse=True):
        if low == word or low.endswith(" " + word):
            brand_part, cat, known = item[: len(item) - len(word)].strip(), word, True
            break
    else:
        parts = item.rsplit(" ", 1)
        if len(parts) == 2:
            brand_part, cat = parts[0], parts[1].lower()
    words = brand_part.split()
    moved = False
    while words and words[-1].islower() and words[-1] in _TF3_CATEGORY_MODIFIERS:
        cat = f"{words.pop()} {cat}"
        moved = True
    while len(words) >= 2 and re.fullmatch(r"[a-z][a-z-]*", words[-1]) and any(
        re.search(r"[A-Z0-9]", w) for w in words[:-1]
    ):
        cat = f"{words.pop()} {cat}"
        moved = True
    brand_ok = all(w[:1].isupper() or w[:1].isdigit() for w in words)
    return (" ".join(words) or None), cat, known and not moved and brand_ok


def _tf3_spec_query(spec: Optional[tuple]) -> Optional[str]:
    """Search text for the wanted spec value ('6.7in' -> '6.7 inch')."""

    if not spec:
        return None
    key, value = spec
    if key == "screen_size":
        return f"{value[:-2]} inch"
    if key == "ram":
        return f"{value[:-2]}GB RAM"
    if key == "refresh_rate":
        return f"{value[:-2]}Hz"
    return {"4k": "4K", "qhd": "QHD", "fhd": "Full HD", "hd": "HD"}.get(value, value)


def _tf3_spec_query_alt(spec: Optional[tuple]) -> Optional[str]:
    if not spec:
        return None
    key, value = spec
    if key == "screen_size":
        return f"{value[:-2]}-inch display"
    if key == "ram":
        return f"{value[:-2]}GB"
    if key == "refresh_rate":
        return f"{value[:-2]}Hz display"
    return {"4k": "4K UHD 2160p", "qhd": "QHD 1440p", "fhd": "1080p", "hd": "720p"}.get(value, value)


# ---------------------------------------------------------------------------
# Engine: probe for a late (turn- or count-triggered) event before choosing the final
# ---------------------------------------------------------------------------


class _TF3Engine(Engine):
    """Engine with one TF3 addition: never order before the event has been observed.

    The pack's events fire on the first add, so this probe is idle there. A task whose
    event fires on a later add (nth_successful_cart_add) or at a solver turn (it lands on
    the LAST cart item at the start of that turn) gets probe turns -- a sacrificial add
    plus reads of the latest cart items and the top finals -- until the change is visible
    in a turn strictly before the order. Without a fired event the task cannot be paid,
    so probing continues while turns and time allow (the order reserve is kept).
    """

    _tf3_turn_reserve = 3
    _tf3_time_reserve = 45.0

    def _choose_final(self, plan: Plan) -> Optional[Candidate]:
        strategy = self.strategy
        probe_no = 0
        while True:
            ep = self.ep
            if ep.done or ep.first_add is None or ep.event is not None:
                break
            if ep.turns_left() <= self._tf3_turn_reserve or ep.time_left() < self._tf3_time_reserve:
                break
            group = strategy.tf3_probe_group(probe_no)
            if not group:
                break
            self.env.call(group)
            probe_no += 1
        return super()._choose_final(plan)


# ---------------------------------------------------------------------------
# Strategy
# ---------------------------------------------------------------------------


@register_strategy
class ConstraintSatisfactionStrategy(Strategy):
    family = "constraint_satisfaction"
    max_research_rounds = 6
    max_recovery_rounds = 4
    engine_cls = _TF3Engine

    def __init__(self, ep) -> None:
        super().__init__(ep)
        self.tf3_brand: Optional[str] = None
        self.tf3_category: Optional[str] = None
        self.tf3_cat_word: Optional[str] = None
        self.tf3_cat_known = False
        self.tf3_spec: Optional[tuple] = None
        self.tf3_spec_source = ""
        self._tf3_spec_rank = 0
        self.tf3_underspecified = False
        self.tf3_sealed = False
        self.tf3_exhausted = False
        self.tf3_spec_searched = False
        self.tf3_sacrifice: Optional[Candidate] = None
        self._tf3_msg_index = 0
        self._tf3_log_index = 0
        self._tf3_detail_keys: set = set()
        self._tf3_static: dict = {}
        self._tf3_static_sig: tuple = ()
        self._tf3_queries_done: set = set()
        self._tf3_compare_requested: set = set()
        self._tf3_asked_turns: list = []
        self._tf3_probe_added: set = set()

    # -- parsing -------------------------------------------------------------
    def parse(self) -> None:
        ep = self.ep
        goal = ep.goal_text
        match = _TF3_BUDGET_RE.search(goal)
        budget = parse_money(match.group(1)) if match else parse_budget(goal)
        if match and match.group(2):
            ep.currency = match.group(2).upper()
        ep.set_budget(budget)
        goal_match = _TF3_GOAL_RE.search(goal)
        item = goal_match.group("item") if goal_match else ""
        brand, cat_word, known = _tf3_split_item(item)
        if not goal_match:
            # Unknown goal template: take the category from a known word; the sealed
            # answer (asked for, since the parse is uncertain) gives the exact values.
            fallback = parse_category_word(goal)
            brand, cat_word, known = None, _tf3_cat_word(fallback), False
        self.tf3_brand, self.tf3_cat_word, self.tf3_cat_known = brand, cat_word, known
        if cat_word:
            self.tf3_category = cat_word if cat_word.endswith("s") else cat_word + "s"
        self.tf3_underspecified = bool(_TF3_UNDERSPEC_RE.search(goal))
        spec_text = goal_match.group("spec") if goal_match else None
        spec = _tf3_parse_spec(spec_text) or _tf3_parse_spec(goal)
        if spec:
            self.tf3_spec, self.tf3_spec_source, self._tf3_spec_rank = spec, "goal", 9
        elif not self.tf3_underspecified:
            loose = parse_gated_spec(spec_text or goal)
            if loose:
                self.tf3_spec, self.tf3_spec_source = loose, "goal-loose"
        ep.intent.update({
            "brand": self.tf3_brand, "category": self.tf3_category,
            "spec": self.tf3_spec, "underspecified": self.tf3_underspecified,
        })

    def tf3_needs_answer(self) -> bool:
        """The sealed answer is still worth a (repeated) question."""

        if self.tf3_sealed:
            return False
        return self.tf3_spec is None or self.tf3_spec_source == "goal-loose" or not self.tf3_cat_known

    def opening_message(self) -> Optional[str]:
        # Ask on turn 1 whenever the goal text leaves anything to a heuristic: the sealed
        # answer is exact. A fully certain specified goal skips the simulator call (each
        # one is an LLM round trip whose failure quarantines the session).
        if not self.tf3_needs_answer():
            return None
        self._tf3_asked_turns.append(self.ep.turn + 1)
        return _TF3_QUESTION

    def tf3_sync(self) -> None:
        """Fold new shopper lines (sealed answer, budget cut, spec reminder) into state."""

        ep = self.ep
        for _turn, text in ep.shopper_messages[self._tf3_msg_index:]:
            for line in [part for part in text.split("\n") if part.strip()]:
                self._tf3_read_line(line)
        self._tf3_msg_index = len(ep.shopper_messages)
        ep.intent.update({"brand": self.tf3_brand, "category": self.tf3_category, "spec": self.tf3_spec})
        # Detail rows: remember exactly which pid::sku pairs a view/compare returned.
        for entry in ep.log[self._tf3_log_index:]:
            for act, result in zip(entry.get("calls") or [], entry.get("results") or []):
                if (act or {}).get("name") not in ("view", "compare") or not isinstance(result, dict):
                    continue
                payload = result.get("observation")
                if not isinstance(payload, dict):
                    continue
                rows = payload.get("compared") if act.get("name") == "compare" else [payload]
                for row in rows or []:
                    if not isinstance(row, dict) or not row.get("product_id"):
                        continue
                    for variant in row.get("variants") or []:
                        if isinstance(variant, dict) and variant.get("sku"):
                            self._tf3_detail_keys.add(cand_key(row["product_id"], variant["sku"]))
        self._tf3_log_index = len(ep.log)

    def _tf3_read_line(self, line: str) -> None:
        ep = self.ep
        category = _TF3_CATEGORY_RE.search(line)
        if category:
            # The sealed answer: exact category, and the brand exactly when the task has one.
            self.tf3_sealed = True
            self.tf3_category = category.group(1).strip()
            self.tf3_cat_word = _tf3_cat_word(self.tf3_category)
            self.tf3_cat_known = True
            brand = _TF3_BRAND_RE.search(line)
            self.tf3_brand = brand.group(1).strip() if brand else None
        spec = _tf3_parse_spec(line)
        if spec:
            # goal phrase (9) > sealed answer (3) > "still needs ..." (2) > any other line (1)
            rank = 3 if category else (2 if _TF3_SPEC_RESTATE_RE.search(line) else 1)
            if self.tf3_spec is None or rank > self._tf3_spec_rank or (
                    self.tf3_spec_source == "goal-loose" and rank >= 2):
                self.tf3_spec, self.tf3_spec_source, self._tf3_spec_rank = spec, "shopper", rank
        if ep.budget is None:
            at_most = re.search(r"at most\s+([0-9][0-9,]*(?:\.[0-9]+)?)", line, re.I)
            if at_most:
                ep.set_budget(parse_money(at_most.group(1)))
        amounts = [parse_money(m.group(1)) for m in _TF3_CUT_RE.finditer(line)]
        if "?" not in line and _TF3_BUDGET_TALK_RE.search(line):
            cur = re.escape(ep.currency or "PHP")
            money = re.compile(
                rf"(?:\b{cur}|₱)\s*([0-9][0-9,]*(?:\.[0-9]+)?)|([0-9][0-9,]*(?:\.[0-9]+)?)\s*{cur}\b")
            for m in money.finditer(line):
                amounts.append(parse_money(m.group(1) or m.group(2)))
        for value in amounts:
            if value is not None and ep.budget is not None and 0 < value < ep.budget - 1e-9:
                ep.notes.append(f"tf3 budget {ep.budget} -> {value}")
                ep.budget = value

    # -- candidate evaluation ---------------------------------------------------
    def _tf3_static_eval(self, key: str) -> Optional[dict]:
        """Budget/stock-free checks of one detailed SKU (cached per requirement set)."""

        sig = (self.tf3_spec, self.tf3_brand, self.tf3_category, self.tf3_cat_word, self.ep.currency)
        if sig != self._tf3_static_sig:
            self._tf3_static, self._tf3_static_sig = {}, sig
        if key in self._tf3_static:
            return self._tf3_static[key]
        if key not in self._tf3_detail_keys or not self.tf3_spec:
            return None
        ep = self.ep
        pid, sku = split_key(key)
        view = ep.view_row(pid)
        variant = next((v for v in view["variants"] if str(v.get("sku")) == sku), None)
        if variant is None:
            return None
        options = variant.get("options")
        title = str(view.get("title") or "")
        spec_key, wanted = self.tf3_spec
        reasons = []
        if not self._tf3_category_ok(view.get("category_path") or [], title):
            reasons.append("category")
        if self.tf3_brand and not brand_matches(self.tf3_brand, view.get("brand")):
            reasons.append("brand")
        value, source = variant_attribute_with_source(view, options, spec_key)
        if value != wanted:
            reasons.append(f"spec:{value}")
        if not genuine_device_ok(self.tf3_category, view, options):
            reasons.append("device")
        currency = variant.get("currency")
        if ep.currency and currency and str(currency) != ep.currency:
            reasons.append("currency")
        out = {
            "key": key, "pid": pid, "sku": sku, "title": title, "ok": not reasons,
            "reasons": reasons, "conf": _tf3_conf(source, spec_key) if not reasons else 0,
        }
        self._tf3_static[key] = out
        return out

    def _tf3_category_ok(self, path: list, title: str) -> bool:
        if self.tf3_sealed or not self.tf3_cat_word:
            return category_matches(self.tf3_category, path, title=title)
        return category_matches(self.tf3_category, path, title=title) or category_matches(
            self.tf3_cat_word, path, title=title)

    def _tf3_rows(self, cap: Optional[float]) -> list:
        """Valid, in-stock, not-excluded SKUs priced at or under ``cap``."""

        ep = self.ep
        out = []
        for key in sorted(self._tf3_detail_keys):
            static = self._tf3_static_eval(key)
            if not static or not static["ok"]:
                continue
            price = ep.price(key)
            if key in ep.excluded or ep.in_stock(key) is not True or price is None:
                continue
            if cap is not None and price > cap + 1e-9:
                continue
            out.append({**static, "price": float(price)})
        return out

    def candidate_ok(self, key: str) -> bool:
        self.tf3_sync()
        static = self._tf3_static_eval(key)
        return bool(static and static["ok"])

    def candidate_score(self, key: str) -> float:
        static = self._tf3_static_eval(key) or {}
        return static.get("conf", 0) * 1e9 - (self.ep.price(key) or 0.0)

    # -- research ---------------------------------------------------------------
    def research_actions(self, round_no: int) -> list:
        self.tf3_sync()
        ep = self.ep
        acts: list = []
        asked = self._tf3_asked_turns
        if (self.tf3_needs_answer() and len(asked) < _TF3_MAX_ASKS
                and (not asked or asked[-1] <= ep.turn)):
            # The last question got no sealed answer (a due intervention wins the turn and
            # the simulator is not called): ask again on this turn.
            asked.append(ep.turn + 1)
            acts.append(action("message", content=_TF3_QUESTION))
        discovery = self._tf3_discovery(max_searches=4 if round_no else 3, max_compares=3)
        # Out of ideas only counts once the spec is known: spec-targeted queries are new then.
        if (not discovery and round_no and self.tf3_spec is not None) or (
                round_no >= self.max_research_rounds - 1):
            self.tf3_exhausted = True
        return acts + discovery

    def recovery_actions(self, round_no: int) -> list:
        self.tf3_sync()
        return self._tf3_discovery(max_searches=4, max_compares=3, post_event=True)

    def _tf3_discovery(self, *, max_searches: int, max_compares: int, post_event: bool = False) -> list:
        acts = []
        pids = self._tf3_compare_queue()[: max_compares * 5]
        for i in range(0, len(pids), 5):
            chunk = pids[i:i + 5]
            self._tf3_compare_requested.update(chunk)
            acts.append(action("compare", product_ids=chunk))
        searches = 0
        for act in self._tf3_query_plan(post_event):
            if searches >= max_searches:
                break
            sig = (act["name"], tuple(sorted((k, str(v)) for k, v in act["args"].items())))
            if sig in self._tf3_queries_done:
                continue
            self._tf3_queries_done.add(sig)
            acts.append(act)
            searches += 1
            if self.tf3_spec and act["name"] == "search":
                spec_text = _tf3_spec_query(self.tf3_spec) or ""
                if spec_text and spec_text.lower() in act["args"].get("query", "").lower():
                    self.tf3_spec_searched = True
        return acts

    def _tf3_query_plan(self, post_event: bool) -> list:
        ep = self.ep
        brand = self.tf3_brand or ""
        cat = self.tf3_cat_word or "smartphone"
        spec_q = _tf3_spec_query(self.tf3_spec)
        spec_alt = _tf3_spec_query_alt(self.tf3_spec)
        orig = ep.original_budget
        now = ep.budget
        cut = now is not None and orig is not None and now < orig - 1e-9
        phone = (self.tf3_category or "").casefold().rstrip("s") == "smartphone"

        def search(query: str, cap: Optional[float]) -> dict:
            text = " ".join(query.split())
            return action("search", query=text[:150], k=10, in_stock=True,
                          max_price=round(cap, 2) if cap else None)

        def filt(cap: Optional[float]) -> dict:
            return action("filter", category=self.tf3_category, brand=self.tf3_brand,
                          max_price=round(cap, 2) if cap else None, in_stock=True, k=10)

        plan: list = []
        if post_event or cut:
            if spec_q:
                plan += [search(f"{brand} {cat} {spec_q}", now), search(f"{brand} {spec_q}", now),
                         search(f"{cat} {spec_q}", now)]
            plan += [search(f"{brand} {cat}", now), filt(now)]
            if spec_alt:
                plan += [search(f"{brand} {cat} {spec_alt}", now)]
        if spec_q:
            plan += [search(f"{brand} {cat} {spec_q}", orig)]
            if brand:
                plan += [search(f"{brand} {spec_q}", orig)]
            plan += [search(f"{cat} {spec_q}", orig)]
        plan += [search(f"{brand} {cat}", orig), filt(orig)]
        if spec_q:
            cheap = orig * 0.65 if orig else None
            plan += [search(f"{brand} {cat} {spec_alt}", orig), search(f"{brand} {cat} {spec_q}", cheap)]
            if phone:
                plan += [search(f"{spec_q} {cat} android", orig)]
        if orig:
            plan += [search(f"{brand} {cat}", orig * 0.6), filt(orig * 0.6)]
        if phone:
            plan += [search(f"{brand} {cat} android 5G", orig), search(f"{brand} {cat} dual sim", orig)]
        return plan

    def _tf3_compare_queue(self) -> list:
        """Unseen products from search/filter results, most promising first."""

        ep = self.ep
        order: list = []
        seen: set = set()
        for (_turn, _name, _args, keys) in ep.searches:
            for key in keys:
                pid, _sku = split_key(key)
                if pid not in seen:
                    seen.add(pid)
                    order.append(pid)
        scored = []
        for rank, pid in enumerate(order):
            product = ep.product(pid)
            if product.detailed or pid in self._tf3_compare_requested:
                continue
            score = self._tf3_summary_score(pid)
            if score is None:
                continue
            scored.append((-score, rank, pid))
        scored.sort()
        return [pid for _s, _r, pid in scored]

    def _tf3_summary_score(self, pid: str) -> Optional[float]:
        """Priority of an unseen product from its search summary; None = not worth a compare."""

        ep = self.ep
        product = ep.product(pid)
        title = product.title or ""
        if self.tf3_brand and product.brand is not None and not brand_matches(self.tf3_brand, product.brand):
            return None
        keys = [cand_key(pid, sku) for sku in product.variants]
        prices = [ep.price(k) for k in keys if ep.price(k) is not None]
        if keys and all(ep.in_stock(k) is False for k in keys):
            return None
        if prices and ep.original_budget is not None and min(prices) > ep.original_budget + 1e-9:
            return None
        score = 0.0
        if self.tf3_spec:
            values = options_values(self.tf3_spec[0], title)
            if values == {self.tf3_spec[1]}:
                score += 4.0
            elif values:
                score -= 2.0
        if _TF3_ACCESSORY_RE.search(title):
            score -= 3.0
        low = title.lower()
        if (self.tf3_cat_word and self.tf3_cat_word in low) or "phone" in low:
            score += 1.0
        if prices and ep.budget is not None and min(prices) <= ep.budget + 1e-9:
            score += 0.5
        return score

    # -- planning ---------------------------------------------------------------
    def make_plan(self) -> Optional[Plan]:
        self.tf3_sync()
        ep = self.ep
        if self.tf3_spec is None:
            return None
        rows_orig = self._tf3_rows(ep.original_budget)
        rows_now = [r for r in rows_orig if ep.budget is not None and r["price"] <= ep.budget + 1e-9]
        n_orig = len({r["pid"] for r in rows_orig})
        n_now = len({r["pid"] for r in rows_now})
        lenient = self.tf3_exhausted or ep.time_left() < 90.0 or ep.turns_left() <= 12
        pending = [pid for pid in self._tf3_compare_queue() if (self._tf3_summary_score(pid) or 0) >= 4.0]
        ready = (
            n_orig >= 3 and n_now >= 2
            and (self.tf3_spec_searched or n_now >= 4)
            and not pending
        ) or (n_orig >= 3 and n_now >= 2 and lenient) or (lenient and n_orig >= 1)
        if not ready:
            return None
        return self._tf3_select(rows_orig, rows_now)

    def _tf3_select(self, rows_orig: list, rows_now: list) -> Optional[Plan]:
        """A = most expensive of the most reliable valid products (the first add must be
        gold); B = cheapest of the most reliable ones within the current budget."""

        if not rows_orig:
            return None

        def reliable_pool(rows: list) -> list:
            best = max(r["conf"] for r in rows)
            return [r for r in rows if r["conf"] >= best]

        b_row = None
        if rows_now:
            b_row = min(reliable_pool(rows_now), key=lambda r: (r["price"], r["pid"], r["sku"]))
        others = [r for r in rows_orig if b_row is None or r["pid"] != b_row["pid"]]
        if not others:  # a single valid product: commit to one SKU, keep a sibling if any
            others = [r for r in rows_orig if b_row is None or r["key"] != b_row["key"]]
        if not others:
            a_row, b_row = b_row, None
        else:
            a_row = max(reliable_pool(others), key=lambda r: (r["price"], r["pid"], r["sku"]))
        if a_row is None:
            return None
        finals_rows = [b_row] if b_row else []
        rest = [r for r in rows_orig if r["key"] not in {a_row["key"], *(x["key"] for x in finals_rows)}]
        rest.sort(key=lambda r: (
            not (self.ep.budget is not None and r["price"] <= self.ep.budget + 1e-9),
            r["pid"] == a_row["pid"], -r["conf"], r["price"], r["key"]))
        finals_rows += rest
        commit = Candidate(pid=a_row["pid"], sku=a_row["sku"], score=a_row["conf"], reason="commit")
        finals = [Candidate(pid=r["pid"], sku=r["sku"], score=r["conf"]) for r in finals_rows]
        self.tf3_sacrifice = self._tf3_pick_sacrifice(commit, finals)
        self.ep.notes.append(
            f"tf3 plan A={commit.key} B={finals[0].key if finals else None} "
            f"S={self.tf3_sacrifice.key if self.tf3_sacrifice else None} "
            f"valid={len(rows_orig)} budget={self.ep.budget}")
        return Plan(commit=commit, finals=finals, preadd=True)

    def _tf3_pick_sacrifice(self, commit: Candidate, finals: list) -> Optional[Candidate]:
        """Second add of a different product: absorbs a chained second-add stockout.

        Prefer a valid product we would order last (most expensive / over the budget);
        otherwise any other in-stock detailed product; else the preferred final itself.
        """

        ep = self.ep
        keep = {f.key for f in finals[:2]}
        pool = [f for f in finals if f.key not in keep and f.pid != commit.pid]
        if pool:
            best = max(pool, key=lambda f: (
                not (ep.budget is not None and (ep.price(f.key) or 0) <= ep.budget + 1e-9),
                ep.price(f.key) or 0.0, f.key))
            return best
        valid_keys = {f.key for f in finals}
        spare = []
        for key in sorted(self._tf3_detail_keys):
            pid, sku = split_key(key)
            if key in valid_keys or pid == commit.pid or any(f.pid == pid for f in finals[:2]):
                continue
            if ep.in_stock(key) is not True or key in ep.excluded or ep.price(key) is None:
                continue
            spare.append((ep.price(key) or 0.0, key))
        if spare:
            _price, key = min(spare)
            pid, sku = split_key(key)
            return Candidate(pid=pid, sku=sku, reason="sacrifice")
        return None

    def commit_group(self, plan: Plan) -> list:
        ep = self.ep
        commit = plan.commit
        group = [
            action("add_to_cart", product_id=commit.pid, sku=commit.sku),
            action("inspect_stock", product_id=commit.pid, sku=commit.sku),
        ]
        finals = [f for f in plan.finals if f.key != commit.key]
        second = self.tf3_sacrifice or (finals[0] if finals else None)
        if second is not None and second.pid == commit.pid and self.tf3_sacrifice is None:
            second = next((f for f in finals if f.pid != commit.pid), second)
        if second is not None:
            group.append(action("add_to_cart", product_id=second.pid, sku=second.sku))
            group.append(action("inspect_stock", product_id=second.pid, sku=second.sku))
        for final in finals[:4]:
            if second is not None and final.key == second.key:
                continue
            group.append(action("inspect_stock", product_id=final.pid, sku=final.sku))
        return group[: ep.max_calls]

    # -- after the event --------------------------------------------------------
    def finals_after_event(self) -> list:
        self.tf3_sync()
        ep = self.ep
        rows = [r for r in self._tf3_rows(ep.budget) if self.final_ok(r["key"])]
        rows.sort(key=lambda r: (-r["conf"], r["price"], r["key"]))
        return [Candidate(pid=r["pid"], sku=r["sku"], score=r["conf"]) for r in rows]

    def tf3_probe_group(self, probe_no: int) -> list:
        """One probe turn: [sacrificial add, inspect it, inspect the latest cart items,
        inspect the top finals].

        The add feeds a count trigger (it is never one of the top finals, so the event
        cannot land on the order target); a solver-turn event lands on the LAST cart item,
        which is read right away; the finals are read AFTER those items, so once the event
        shows up no extra read turn is needed before the order.
        """

        ep = self.ep
        group: list = []
        latest: list = []
        for (_t, _s, key, ok) in reversed(ep.adds):
            if ok and key not in latest:
                latest.append(key)
        sacrifice = self._tf3_probe_sacrifice()
        if sacrifice is not None:
            self._tf3_probe_added.add(sacrifice)
            pid, sku = split_key(sacrifice)
            group += [action("add_to_cart", product_id=pid, sku=sku),
                      action("inspect_stock", product_id=pid, sku=sku)]
        for key in latest[:4]:
            pid, sku = split_key(key)
            group.append(action("inspect_stock", product_id=pid, sku=sku))
        read = set(latest[:4]) | ({sacrifice} if sacrifice else set())
        for final in self.finals_after_event()[:3]:
            if final.key not in read:
                group.append(action("inspect_stock", product_id=final.pid, sku=final.sku))
        return group[: ep.max_calls]

    def _tf3_probe_sacrifice(self) -> Optional[str]:
        ep = self.ep
        finals = self.finals_after_event()
        keep = {f.key for f in finals[:2]}
        in_cart = {key for (_t, _s, key, ok) in ep.adds if ok}
        options = []
        for key in sorted(self._tf3_detail_keys):
            if key in keep or key in in_cart or key in self._tf3_probe_added:
                continue
            if ep.in_stock(key) is not True or ep.price(key) is None:
                continue
            options.append((key in {f.key for f in finals}, -(ep.price(key) or 0.0), key))
        if not options:
            return None
        options.sort()
        return options[0][2]

