import re
from typing import Optional


# ---------------------------------------------------------------------------
# Runtime constants (families/preference_reasoning.py, copied verbatim)
# ---------------------------------------------------------------------------

_TF4_GOOD = 0.65  # _GOOD_THRESHOLD: inclusive, on the score rounded to 3 decimals
_TF4_DEFAULT_CATEGORY = "Smartwatches"  # runtime scorer fallback for unknown categories
_TF4_BAD_TITLE_TOKENS = (
    "customer review", "customer rating", "search results", "results page",
    "refurb", "pre-owned", "restored", "renewed",
)
_TF4_PROFILES = {
    "Smartwatches": {
        "accessory_phrases": ("case for", "screen protector", "band for", "strap for", "charger for",
                              "mudra band", "replacement band", "watch band"),
        "device_signals": ("smartwatch", "smart watch", "watch phone", "apple watch", "galaxy watch",
                           "pixel watch", "garmin", "fitbit", "amazfit", "kospet"),
        "device_brands": frozenset({"garmin", "fitbit", "amazfit", "kospet"}),
        "axes": "GPS/navigation, ruggedness and water resistance, multi-day battery life",
        "queries": (
            "rugged gps smartwatch", "long battery waterproof smartwatch", "outdoor fitness gps watch",
            "gps smartwatch 5atm compass", "rugged outdoor smart watch waterproof",
            "hiking gps watch long battery", "tactical military smartwatch",
            "smartwatch gps compass barometer altitude", "outdoor smart watch 10atm",
            "smart watch gps 14 days battery", "waterproof sports smartwatch gps",
            "military rugged smart watch ip68", "trail running gps watch", "solar smartwatch outdoor",
            "swimming smart watch 5atm gps",
        ),
    },
    "Headphones": {
        "accessory_phrases": ("case for", "ear pads", "earpads", "replacement pad", "cable for",
                              "adapter", "stand for"),
        "device_signals": ("headphone", "headphones", "earbud", "earbuds", "earphone", "earphones",
                           "headset"),
        "device_brands": frozenset(),
        "axes": "sweat/water resistance, a secure sport fit, battery life, wireless freedom",
        "queries": (
            "waterproof sport earbuds", "wireless running headphones", "gym workout earbuds ipx",
            "ipx7 sport earbuds bluetooth", "sweatproof running earphones wireless",
            "ear hook sport headphones bluetooth", "waterproof bluetooth earbuds long battery",
            "ipx5 sports wireless earphones", "bone conduction sport headphones waterproof",
            "running earbuds ear hooks 40h playtime", "sport bluetooth headset sweatproof",
            "wireless sports earbuds ipx6 fitness", "open ear sport headphones bluetooth",
            "waterproof earphones swimming running", "gym earbuds wireless secure fit",
        ),
    },
    "Tablets": {
        "accessory_phrases": ("case for", "keyboard for", "screen protector", "stylus", "pen for",
                              "stand for", "charger for"),
        "device_signals": ("tablet", "ipad", "galaxy tab", "fire hd", "fire max"),
        "device_brands": frozenset(),
        "axes": "kid-ready durability, battery life, a kid-friendly 8-11 inch size, wifi",
        "queries": (
            "kids tablet case bundle", "kids tablet 10 inch", "wifi tablet long battery",
            "kids tablet shockproof case wifi", "children tablet 8 inch drop proof",
            "kids tablet bumper case 10 inch", "tablet wifi long battery life",
            "kids tablet android wifi", "tablet for kids with case", "rugged tablet 8 inch",
            "kids learning tablet 10 inch wifi", "toddler tablet drop proof",
            "10 inch tablet wifi 8000mah", "kids tablet parental control case",
            "children tablet kid proof case",
        ),
    },
}

# Extra words that only tighten our own confidence that a title is a device (the compiler's
# actual-device rule is not shipped; a wrong accept on either committed item pays 0, a wrong
# reject only costs a little score).
_TF4_STRICT_TITLE_RE = re.compile(
    r"\b(?:replacement|protector|pouch|covers?|silicone case|ear ?tips?|eartips|cushions?|"
    r"charging cable|charger|holder|sticker|skins|mount|hanger|decal)\b",
    re.I,
)
_TF4_STRICT_TYPE_RE = re.compile(
    r"accessor|ear ?pad|ear ?tip|cushion|cable|adapter|\bcase\b|\bstrap\b|\bband\b|protector",
    re.I,
)
_TF4_ACCESSORY_LEAF_RE = re.compile(r"accessor|replacement|parts\b|\bcases\b|protector|straps|bands\b", re.I)

# Goal / shopper parsing
_TF4_BUDGET_RE = re.compile(r"at or under\s+([0-9][0-9,]*(?:\.[0-9]+)?)\s*([A-Z]{3})\b")
_TF4_CAT_RE = re.compile(r"in-stock\s+([a-z][a-z \-]*?)(?=\s+(?:at or under|for)\b)", re.I)
_TF4_SEALED_CAT_RE = re.compile(r"the required catalog category is (.+?)\.(?:\s|$)")
# user_sim._sealed_answer always opens with this line (the CURRENT budget cap).
_TF4_SEALED_BUDGET_RE = re.compile(r"my budget is at most\s+([0-9][0-9,]*(?:\.[0-9]+)?)\s*([A-Za-z]{3})\b", re.I)
_TF4_CATEGORY_WORDS = (
    ("Headphones", re.compile(r"head ?(?:phone|set)s?\b|\bear ?(?:bud|phone)s?\b", re.I)),
    ("Smartwatches", re.compile(r"\bsmart ?watch", re.I)),  # also 'smartwatche' (_cat_word)
    ("Tablets", re.compile(r"\btablets?\b|\bipads?\b", re.I)),
)
# Shopper lines that restate an event's price move (user_sim._event_text), never a budget.
_TF4_EVENT_LINE_RE = re.compile(
    r"leaning toward|\bfrom\s+[0-9][0-9,.]*\s*(?:[a-z]{3}\s+)?to\s+[0-9]", re.I)
_TF4_BUDGET_CUE_RE = re.compile(
    r"budget|balance|afford|spend|limit|ceiling|\bcap\b|\bmax|up to|under\b|below|\bover\b|at most|"
    r"no more than|\bonly\b", re.I)
# Requirements questions before the first add. Only unanswered asks repeat (a due scripted
# intervention swallows the answer); research rounds and a turns-left guard bound the wait.
_TF4_MAX_ASKS = 6
_TF4_USE_CASE_RES = (
    re.compile(r"it's for (.+?) - "),
    re.compile(r"[A-Z]{3} for (.+?)\.\s"),
)
_TF4_LEAD_RES = (
    re.compile(r"pay a bit more for (.+?) than settle"),
    re.compile(r"cheapest isn't the goal here; (.+?) is what i actually care about"),
    re.compile(r"cheapest one - (.+?) matters more to me"),
)

# ---------------------------------------------------------------------------
# Exact scorer port (families/preference_reasoning.py _score_*), fed one view row
# ---------------------------------------------------------------------------

_TF4_WATER_RE = r"\b(ipx?[4-8]|ip5[0-9]|ip6[0-9]|sweat ?(?:proof|resistant)|water ?(?:proof|resistant))\b"
_TF4_SPORT_RE = r"\b(sports?|running|gym|workout|fitness|ear ?hook|secure fit)\b"
_TF4_WIRELESS_RE = r"\b(wireless|bluetooth|true wireless)\b"


def _tf4_contains(text: str, pattern: str) -> bool:
    return re.search(pattern, text, flags=re.I) is not None


def _tf4_facts_text(facts: Optional[dict]) -> str:
    return " ".join(f"{str(k).replace('_', ' ')} {v}" for k, v in (facts or {}).items()).casefold()


def _tf4_duration_axis(text: str) -> float:
    days = [float(m.group(1)) for m in re.finditer(r"(\d+(?:\.\d+)?)\s*days?", text, flags=re.I)]
    hours = [float(m.group(1)) for m in re.finditer(r"(\d+(?:\.\d+)?)\s*hours?", text, flags=re.I)]
    if days:
        best = max(days)
        if best >= 10:
            return 1.0
        if best >= 5:
            return 0.75
        if best >= 2:
            return 0.5
    if hours:
        best = max(hours)
        if best >= 120:
            return 1.0
        if best >= 72:
            return 0.75
        if best >= 36:
            return 0.5
    if "solar" in text or "battery life" in text:
        return 0.5
    return 0.0


def _tf4_short_duration_axis(text: str) -> float:
    hours = [
        float(m.group(1))
        for m in re.finditer(r"(?<![\w.])(\d+(?:\.\d+)?)\s*\+?\s*(?:hours?|hrs?|h)\b", text, flags=re.I)
    ]
    if re.search(r"\d+(?:\.\d+)?\s*days?", text, flags=re.I):
        return 1.0
    if hours:
        best = max(hours)
        if best >= 15:
            return 1.0
        if best >= 10:
            return 0.75
        if best >= 6:
            return 0.5
    if "battery life" in text:
        return 0.25
    return 0.0


def _tf4_score_headphones(row: dict) -> float:
    title = str(row.get("title") or "").casefold()
    facts_text = _tf4_facts_text(row.get("facts"))
    text = facts_text + " " + title
    category_text = " ".join(str(c) for c in row.get("category_path") or []).casefold()
    wireless_facts = facts_text + " " + category_text
    water = 1.0 if _tf4_contains(text, _TF4_WATER_RE) else 0.0
    sport = 1.0 if _tf4_contains(text, _TF4_SPORT_RE) else 0.0
    battery = _tf4_short_duration_axis(text)
    wireless = 1.0 if _tf4_contains(wireless_facts + " " + title, _TF4_WIRELESS_RE) else 0.0
    raw = (0.30 * water) + (0.28 * sport) + (0.22 * battery) + (0.20 * wireless)
    return round(max(0.0, min(1.0, raw)), 3)


def _tf4_score_smartwatch(row: dict) -> float:
    text = _tf4_facts_text(row.get("facts"))  # facts only: the title is ignored
    brand = str(row.get("brand") or "").casefold()
    navigation = 1.0 if _tf4_contains(
        text, r"\b(gps|gnss|maps?|compass|barometer|altitude|tactical|trail|hiking|outdoor)\b") else 0.0
    rugged = 0.0
    if _tf4_contains(
        text,
        r"\b(10\s*atm|5\s*atm|50m|100m|ip68|ip69|mil-std|waterproof|water resistant|sapphire|"
        r"fiber[- ]reinforced|titanium|rugged|tactical|tank)\b",
    ):
        rugged = 1.0
    elif _tf4_contains(text, r"\b(water|swim|steel|aluminum)\b"):
        rugged = 0.5
    battery = _tf4_duration_axis(text)
    outdoor_brand = 1.0 if brand in {"garmin", "amazfit", "fitbit", "kospet"} else 0.0
    penalty = 0.2 if _tf4_contains(text, r"\b(kid|kids|child|children|myfirst|watch phone)\b") else 0.0
    raw = (0.32 * navigation) + (0.26 * rugged) + (0.26 * battery) + (0.16 * outdoor_brand) - penalty
    return round(max(0.0, min(1.0, raw)), 3)


def _tf4_score_tablet(row: dict) -> float:
    title = str(row.get("title") or "").casefold()
    text = _tf4_facts_text(row.get("facts")) + " " + title
    kid = 1.0 if _tf4_contains(text, r"\b(kids?|child|children|drop ?proof|rugged case|bumper)\b") else 0.0
    battery = _tf4_short_duration_axis(text)
    size = 1.0 if _tf4_contains(text, r"\b(8|10|10\.\d|11)\s*(?:inch|in\b|\")") else 0.0
    wifi = 1.0 if _tf4_contains(text, r"\b(wi-?fi|wifi)\b") else 0.0
    raw = (0.40 * kid) + (0.25 * battery) + (0.20 * size) + (0.15 * wifi)
    return round(max(0.0, min(1.0, raw)), 3)


def _tf4_preference_score(row: dict, category: Optional[str]) -> float:
    """preference_score(...).score for one view/compare row (unknown category -> Smartwatches)."""

    scorer = {"Headphones": _tf4_score_headphones, "Tablets": _tf4_score_tablet}.get(
        str(category or ""), _tf4_score_smartwatch)
    return scorer(row)


def _tf4_title_estimate(row: dict, category: Optional[str]) -> float:
    """Score guess from a search row (title/brand only), used to order compares.

    For Headphones/Tablets this is a lower bound (facts only add matches). Smartwatches score
    facts only, so the title stands in for the facts as a proxy.
    """

    if str(category or "") in ("Headphones", "Tablets"):
        return _tf4_preference_score({"title": row.get("title"), "brand": row.get("brand")}, category)
    return _tf4_score_smartwatch({"facts": {"title": row.get("title") or ""}, "brand": row.get("brand")})


# ---------------------------------------------------------------------------
# Actual-device heuristic (compile-time rule approximated from the runtime profiles)
# ---------------------------------------------------------------------------


def _tf4_profile(category: Optional[str]) -> dict:
    return _TF4_PROFILES.get(str(category or ""), _TF4_PROFILES[_TF4_DEFAULT_CATEGORY])


def _tf4_actual_device(row: dict, category: Optional[str], strict: bool = False) -> bool:
    """Best guess of the compile-time actual-device rule (profile phrases/signals).

    strict=True adds our own confidence filters for the items we commit to or order.
    """

    profile = _tf4_profile(category)
    title = str(row.get("title") or "").casefold()
    brand = str(row.get("brand") or "").casefold().strip()
    if not title.strip():
        return False
    if any(token in title for token in _TF4_BAD_TITLE_TOKENS):
        return False
    if any(phrase in title for phrase in profile["accessory_phrases"]):
        return False
    positions = [title.find(signal) for signal in profile["device_signals"] if signal in title]
    if not positions and brand not in profile["device_brands"]:
        return False
    if not strict:
        return True
    if _TF4_STRICT_TITLE_RE.search(title):
        return False
    # "<thing> for <device>": the first device word only appears inside the "for ..." clause.
    for_match = re.search(r"(?:^|\s)for\s", title)
    if for_match and positions and min(positions) > for_match.start():
        return False
    if not positions and re.match(r"\s*for\s", title):
        return False
    facts = row.get("facts") or {}
    type_text = " ".join(str(facts.get(k) or "") for k in ("device_type", "description_device_type"))
    if _TF4_STRICT_TYPE_RE.search(type_text):
        return False
    path = [str(label) for label in row.get("category_path") or []]
    if path and _TF4_ACCESSORY_LEAF_RE.search(path[-1]):
        return False
    return True


# ---------------------------------------------------------------------------
# Goal parsing
# ---------------------------------------------------------------------------


def _tf4_category_from_word(text: str) -> Optional[str]:
    """The category whose device word appears FIRST ('a tablet my kid can watch' is a tablet);
    a bare 'watch' only counts when no explicit device word is present."""

    low = (text or "").casefold()
    hits = [(match.start(), category) for category, pattern in _TF4_CATEGORY_WORDS
            for match in [pattern.search(low)] if match]
    if hits:
        return min(hits)[1]
    if re.search(r"\bwatch", low):
        return "Smartwatches"
    return None


def _tf4_budget_mentions(text: str, currency: Optional[str]) -> list:
    """Currency-anchored amounts in shopper sentences that talk about the budget.

    Only amounts written next to the currency count (never '6.5-inch'), and a sentence
    that restates an event's price move ('... from 1290.00 to 2680.00 PHP') is skipped.
    """

    cur = re.escape(currency or "PHP")
    amount = re.compile(
        rf"(?:\b{cur}|₱)\s*([0-9][0-9,]*(?:\.[0-9]+)?)|([0-9][0-9,]*(?:\.[0-9]+)?)\s*(?:{cur}\b|₱)", re.I)
    out = []
    for line in str(text or "").split("\n"):
        for sentence in re.split(r"(?<=[.!?;])\s+", line):
            if _TF4_EVENT_LINE_RE.search(sentence) or not _TF4_BUDGET_CUE_RE.search(sentence):
                continue
            for match in amount.finditer(sentence):
                raw = (match.group(1) or match.group(2) or "").replace(",", "")
                try:
                    out.append(float(raw))
                except ValueError:
                    continue
    return out


def _tf4_parse_goal(goal: str) -> dict:
    out: dict = {"budget": None, "currency": None, "category": None, "cat_word": None,
                 "use_case": None, "lead": None}
    match = _TF4_BUDGET_RE.search(goal)
    if match:
        out["budget"] = float(match.group(1).replace(",", ""))
        out["currency"] = match.group(2)
    match = _TF4_CAT_RE.search(goal)
    word = (match.group(1) if match else "").strip()
    out["cat_word"] = word.casefold() or None
    out["category"] = _tf4_category_from_word(word) or _tf4_category_from_word(goal)
    for pattern in _TF4_USE_CASE_RES:
        match = pattern.search(goal)
        if match:
            out["use_case"] = match.group(1).strip()
            break
    for pattern in _TF4_LEAD_RES:
        match = pattern.search(goal)
        if match:
            out["lead"] = match.group(1).strip()
            break
    return out


# ---------------------------------------------------------------------------
# Strategy
# ---------------------------------------------------------------------------


@register_strategy
class PreferenceReasoningStrategy(Strategy):
    family = "preference_reasoning"
    max_research_rounds = 6
    max_recovery_rounds = 3
    compares_per_round = 3
    searches_per_round = 5

    def __init__(self, ep) -> None:
        super().__init__(ep)
        self.category: Optional[str] = None
        self.cat_word: Optional[str] = None
        self._queries: list = []
        self._query_cursor = 0
        self._last_round = -1
        self._rounds: list = []  # (searched, products_known_before)
        self._scores: dict = {}  # pid -> exact preference score
        self._static: dict = {}  # pid -> category + strict actual-device verdict
        self._currency_explicit = False  # the goal named the currency
        self._sync_mark = -1  # shopper messages already folded into category/budget
        self._asks = 0  # requirements questions sent before the first add
        self._shield: Optional[Candidate] = None

    # -- parsing -------------------------------------------------------------
    def parse(self) -> None:
        ep = self.ep
        goal = _tf4_parse_goal(ep.goal_text)
        budget = goal["budget"] if goal["budget"] is not None else parse_budget(ep.goal_text)
        ep.set_budget(budget)
        if goal["currency"]:
            ep.currency = goal["currency"]
            self._currency_explicit = True
        self.cat_word = goal["cat_word"]
        self.category = goal["category"] or parse_category_word(ep.goal_text) or "Headphones"
        ep.intent.update({"category": self.category, "use_case": goal["use_case"], "lead": goal["lead"]})
        self._queries = self._build_queries()

    def _build_queries(self) -> list:
        profile = _TF4_PROFILES.get(str(self.category or ""))
        if profile is not None:
            return list(profile["queries"])
        word = (self.cat_word or str(self.category or "device")).rstrip("s")
        return [word, f"waterproof {word}", f"{word} long battery", f"rugged {word}", f"{word} wireless"]

    def _refresh_intent(self) -> None:
        """The sealed shopper answer names the exact catalog category; trust it over the goal."""

        for _turn, text in self.ep.shopper_messages:
            match = _TF4_SEALED_CAT_RE.search(text)
            if not match:
                continue
            category = match.group(1).strip()
            if category and category != self.category:
                self.category = category
                self.ep.intent["category"] = category
                self._scores.clear()
                self._static.clear()
                remaining = self._build_queries()
                self._queries = self._queries[: self._query_cursor] + [
                    q for q in remaining if q not in self._queries[: self._query_cursor]
                ]

    def _sync(self) -> None:
        """Fold new shopper messages into the category and the budget (idempotent).

        * The sealed answer names the catalog category and the CURRENT budget cap; it
          supplies budget and currency when the goal text could not be parsed.
        * A delivered add_constraint tightens the budget the verifier enforces on the
          order. core parses the generator's template; this also reads other phrasings
          ('keep it under 1500.00 PHP'), using currency-anchored amounts only.
        """

        ep = self.ep
        if len(ep.shopper_messages) == self._sync_mark:
            return
        self._sync_mark = len(ep.shopper_messages)
        self._refresh_intent()
        for _turn, text in ep.shopper_messages:
            match = _TF4_SEALED_BUDGET_RE.search(text)
            if not match:
                continue
            if not self._currency_explicit:
                ep.currency = match.group(2).upper()
            if ep.budget is None:
                ep.set_budget(float(match.group(1).replace(",", "")))
        if ep.budget is None:
            return
        cuts = [value for _turn, text in ep.shopper_messages
                for value in _tf4_budget_mentions(text, ep.currency) if 0 < value < ep.budget - 1e-9]
        if cuts:
            ep.notes.append(f"tf4 budget {ep.budget} -> {min(cuts)} from shopper text")
            ep.budget = min(cuts)

    def _sealed_answered(self) -> bool:
        # TF4 tasks always carry hard.category, so every sealed answer names it; a scripted
        # line that merely quotes a budget is not an answer.
        return any(_TF4_SEALED_CAT_RE.search(text) for _turn, text in self.ep.shopper_messages)

    def _needs_answer(self) -> bool:
        """No sealed answer yet and nothing added: a hidden requires_priority_clarification
        flag still needs a shopper answer recorded before the first add. A question gets no
        answer on a turn where a scripted intervention is due, so it is asked again."""

        return not self.ep.adds and not self._sealed_answered()

    def _question(self) -> str:
        axes = _tf4_profile(self.category)["axes"] if self.category in _TF4_PROFILES else (
            "durability, battery life and the features you use most")
        lead = "Before I pick" if self._asks == 0 else "One more check before I add anything to the cart"
        return (
            f"{lead}, could you clarify your requirements and which of these matters most "
            f"to you for this use: {axes}?"
        )

    def opening_message(self) -> Optional[str]:
        text = self._question()
        self._asks += 1
        return text

    # -- candidate facts -----------------------------------------------------
    def _listing(self, pid: str) -> str:
        product = self.ep.products.get(pid)
        return (product.listing_id if product is not None and product.listing_id else None) or f"pid:{pid}"

    def _score(self, pid: str) -> float:
        if pid not in self._scores:
            self._scores[pid] = _tf4_preference_score(self.ep.view_row(pid), self.category)
        return self._scores[pid]

    def _static_ok(self, pid: str) -> bool:
        if pid not in self._static:
            row = self.ep.view_row(pid)
            self._static[pid] = bool(
                category_matches(self.category, row.get("category_path") or [], title=row.get("title"))
                and _tf4_actual_device(row, self.category, strict=True)
            )
        return self._static[pid]

    def candidate_ok(self, key: str) -> bool:
        pid, sku = split_key(key)
        product = self.ep.products.get(pid)
        if product is None or not product.detailed or sku not in product.variants:
            return False
        # One catalog, one currency: only a currency the goal named can rule a row out.
        currency = product.variants[sku].currency
        if self._currency_explicit and currency and currency != self.ep.currency:
            return False
        return self._static_ok(pid)

    def candidate_score(self, key: str) -> float:
        return self._score(split_key(key)[0])

    def _blocked_listings(self) -> set:
        ep = self.ep
        keys = []
        if ep.first_add is not None:
            keys.append(ep.first_add.key)
        if ep.event is not None:
            keys.append(ep.event.target_key)
        return {self._listing(split_key(k)[0]) for k in keys}

    def final_ok(self, key: str) -> bool:
        self._sync()
        if not (self.ep.orderable(key) and self.candidate_ok(key)):
            return False
        return self._listing(split_key(key)[0]) not in self._blocked_listings()

    def _first_ok(self, key: str) -> bool:
        """A genuine commitment: hard-valid on the ORIGINAL budget and scoring >= 0.65."""

        ep = self.ep
        if key in ep.excluded or not self.candidate_ok(key) or ep.in_stock(key) is not True:
            return False
        cap = ep.original_budget if ep.original_budget is not None else ep.budget
        price = ep.price(key)
        if price is None or cap is None or price > cap + 1e-9:
            return False
        return self._score(split_key(key)[0]) >= _TF4_GOOD

    def _pool(self, check) -> list:
        ep = self.ep
        since = ep.event.seq if ep.event is not None else 0
        out = []
        for key in ep.known_keys(detailed_only=True):
            if check(key):
                pid, sku = split_key(key)
                out.append(Candidate(pid=pid, sku=sku, score=self._score(pid)))
        out.sort(key=lambda c: (
            -c.score,
            not ep.in_cart(c.key),
            not (ep.event is not None and ep.state_checked_after(c.key, since)),
            ep.price(c.key) or 0.0,
            c.key,
        ))
        return out

    # -- research ------------------------------------------------------------
    def _title_key(self, product) -> tuple:
        return (" ".join(str(product.title or "").casefold().split()),
                str(product.brand or "").casefold().strip())

    def _compare_backlog(self) -> tuple:
        """(fresh, siblings): unseen, affordable, device-like products, most promising first.

        Siblings share a normalized title with an already seen product (usually one listing).
        """

        ep = self.ep
        cap = ep.budget if ep.budget is not None else float("inf")
        seen_titles = {self._title_key(p) for p in ep.products.values() if p.detailed}
        fresh, siblings, queued = [], [], set()
        for index, product in enumerate(list(ep.products.values())):
            if product.detailed or not product.title:
                continue
            affordable = any(
                ep.in_stock(cand_key(product.pid, sku)) is True
                and (ep.price(cand_key(product.pid, sku)) if ep.price(cand_key(product.pid, sku)) is not None
                     else float("inf")) <= cap + 1e-9
                for sku in product.variants
            )
            summary = {"title": product.title, "brand": product.brand}
            if not affordable or not _tf4_actual_device(summary, self.category, strict=False):
                continue
            item = (-_tf4_title_estimate(summary, self.category), index, product.pid)
            title_key = self._title_key(product)
            if title_key in seen_titles or title_key in queued:
                siblings.append(item)
            else:
                queued.add(title_key)
                fresh.append(item)
        fresh.sort()
        siblings.sort()
        return [item[2] for item in fresh], [item[2] for item in siblings]

    def _compare_actions(self) -> list:
        fresh, siblings = self._compare_backlog()
        pids = (fresh + siblings)[: 5 * self.compares_per_round]
        return [action("compare", product_ids=pids[i: i + 5]) for i in range(0, len(pids), 5)]

    def _search_actions(self) -> list:
        ep = self.ep
        batch = self._queries[self._query_cursor: self._query_cursor + self.searches_per_round]
        self._query_cursor += len(batch)
        cap = ep.budget
        return [action("search", query=q, k=10, in_stock=True, max_price=cap) for q in batch]

    def _next_round(self) -> list:
        self._sync()
        compares = self._compare_actions()
        searches = self._search_actions()
        self._rounds.append((bool(searches), len(self.ep.products)))
        return compares + searches

    def research_actions(self, round_no: int) -> list:
        self._last_round = max(self._last_round, round_no)
        actions = self._next_round()
        # Round 0 carries the opening question (engine prefix). Later rounds re-ask while no
        # sealed answer came back (a scripted intervention was due on the asking turn).
        if round_no >= 1 and self._needs_answer() and self._asks < _TF4_MAX_ASKS:
            actions = [action("message", content=self._question()[:600])] + actions
            self._asks += 1
        return actions

    def recovery_actions(self, round_no: int) -> list:
        return self._next_round()

    def _research_exhausted(self) -> bool:
        ep = self.ep
        if ep.time_left() < 60.0 or ep.turns_left() <= 6:
            return True
        if self._last_round < 0:
            return False
        if self._last_round >= self.max_research_rounds - 1:
            return True
        fresh, _siblings = self._compare_backlog()
        if fresh:
            return False
        if self._query_cursor >= len(self._queries):
            return True
        searched, known_before = self._rounds[-1] if self._rounds else (False, 0)
        return searched and len(ep.products) <= known_before  # last searches found nothing new

    def _hold_for_answer(self) -> bool:
        """Delay the commitment one research round so the requirements question is asked again."""

        ep = self.ep
        return (
            self._needs_answer() and self._asks < _TF4_MAX_ASKS
            and self._last_round < self.max_research_rounds - 1
            and ep.turns_left() > 8 and ep.time_left() > 90.0
        )

    # -- planning ------------------------------------------------------------
    def _pick_first(self, options: list, final: Candidate, finals: list) -> Candidate:
        """The commitment whose listing costs the least to give up.

        Any >= 0.65 hard-valid item outside FINAL's listing earns the same reward, but its
        listing is then closed to recovery. If FINAL is lost later (a budget cut delivered
        with the commit turn, a chained event), the best remaining final must not sit in
        that listing, whatever the new budget is: minimize the summed regret over every
        possible budget cap (each known final price, and the current budget).
        """

        ep = self.ep
        rows = sorted(
            ((ep.price(c.key), c.score, self._listing(c.pid)) for c in finals
             if c.key != final.key and ep.price(c.key) is not None),
            key=lambda row: -row[1],
        )
        caps = sorted({row[0] for row in rows} | ({ep.budget} if ep.budget is not None else set()))
        best_all = [next((s for p, s, _l in rows if p <= cap + 1e-9), 0.0) for cap in caps]

        def regret(listing: str) -> float:
            return round(sum(
                top - next((s for p, s, lst in rows if p <= cap + 1e-9 and lst != listing), 0.0)
                for cap, top in zip(caps, best_all)
            ), 6)

        def listing_best(listing: str) -> float:
            return max((s for _p, s, lst in rows if lst == listing), default=0.0)

        def within(cand: Candidate) -> bool:
            # The gate uses the ORIGINAL budget, but never commit above a budget the shopper
            # has since tightened unless nothing else qualifies.
            return ep.budget is None or (ep.price(cand.key) or 0.0) <= ep.budget + 1e-9

        by_listing: dict = {}
        for cand in options:
            by_listing.setdefault(self._listing(cand.pid), []).append(cand)
        chosen = min(by_listing, key=lambda lst: (
            not any(within(c) for c in by_listing[lst]), regret(lst), listing_best(lst), lst))
        return min(by_listing[chosen], key=lambda c: (not within(c), ep.price(c.key) or 0.0, c.key))

    def _pick_shield(self, first: Candidate, final: Candidate, finals: list) -> Optional[Candidate]:
        """A second add between FIRST and FINAL that absorbs any second-add market event.

        A chained event (event_rules: second_successful_cart_add) or an nth=2 trigger hits the
        next add of another product. Adding a worthless item there keeps FINAL clean:
        preferably a sibling in FIRST's listing (closed to recovery anyway, and a valid
        commitment should FIRST's add ever fail), else an item we would never order. It must
        have been compared/viewed (an nth=2 event target must be observed before the event).
        """

        ep = self.ep
        first_listing, final_listing = self._listing(first.pid), self._listing(final.pid)
        usable = {c.key: c.score for c in finals}
        best, best_rank = None, None
        for key in ep.known_keys(detailed_only=True):
            pid, sku = split_key(key)
            listing = self._listing(pid)
            if pid in (first.pid, final.pid) or key in ep.excluded or listing == final_listing:
                continue
            same = listing == first_listing
            rank = (not same, 0.0 if same else usable.get(key, 0.0), not self._first_ok(key),
                    ep.price(key) or 0.0, key)
            if best_rank is None or rank < best_rank:
                best, best_rank = Candidate(pid=pid, sku=sku), rank
        return best

    def make_plan(self) -> Optional[Plan]:
        self._sync()
        finals = self._pool(self.final_ok)
        firsts = self._pool(self._first_ok)
        pair = None
        for final in finals:
            listing = self._listing(final.pid)
            options = [f for f in firsts if self._listing(f.pid) != listing]
            if options:
                pair = (self._pick_first(options, final, finals), final)
                break
        exhausted = self._research_exhausted()
        if pair is not None:
            first, final = pair
            if final.score < 1.0 and not exhausted:
                return None  # a better final may still turn up
            if self._hold_for_answer():
                return None
            first_listing = self._listing(first.pid)
            backups = [c for c in finals if c.key != final.key and self._listing(c.pid) != first_listing]
            self._shield = self._pick_shield(first, final, finals)
            self.ep.notes.append(
                f"tf4 plan first={first.key} ({first.score}) final={final.key} ({final.score}) "
                f"shield={self._shield.key if self._shield else None}")
            return Plan(commit=first, finals=[final] + backups, preadd=True)
        if not exhausted:
            return None
        # Nothing pays > 0 (no >= 0.65 commitment in a second listing): still finish cleanly.
        pool = finals or self._pool(lambda k: self.ep.orderable(k) and self.candidate_ok(k))
        if not pool:
            return None
        first = pool[0]
        others = [c for c in pool if self._listing(c.pid) != self._listing(first.pid)]
        self._shield = self._pick_shield(first, others[0], finals) if others else None
        self.ep.notes.append(f"tf4 degenerate plan first={first.key} ({first.score})")
        return Plan(commit=first, finals=others, preadd=bool(others))

    def commit_group(self, plan: Plan) -> list:
        """[add FIRST, inspect FIRST, add SHIELD, inspect SHIELD, add FINAL, inspect FINAL + backups].

        inspect FIRST right after its add notices a quiet (hard-band) event before any other
        add; the shield takes any second-add event; FINAL enters the cart last, so the order
        turn needs no add. 9 calls at most (10 s group limit)."""

        commit = plan.commit
        finals = [f for f in plan.finals if f.key != commit.key]
        group = [
            action("add_to_cart", product_id=commit.pid, sku=commit.sku),
            action("inspect_stock", product_id=commit.pid, sku=commit.sku),
        ]
        shield = self._shield
        if shield is not None and finals:
            group += [
                action("add_to_cart", product_id=shield.pid, sku=shield.sku),
                action("inspect_stock", product_id=shield.pid, sku=shield.sku),
            ]
        if plan.preadd and finals:
            group.append(action("add_to_cart", product_id=finals[0].pid, sku=finals[0].sku))
        for final in finals[:4]:
            group.append(action("inspect_stock", product_id=final.pid, sku=final.sku))
        return group[: self.ep.max_calls]

    def finals_after_event(self) -> list:
        self._sync()
        return self._pool(self.final_ok)

    # -- ordering ------------------------------------------------------------
    def order_message(self, cand: Candidate) -> str:
        ep = self.ep
        product = ep.product(cand.pid)
        price = ep.price(cand.key)
        price_text = f" at {fmt_money(price)} {ep.currency}" if price is not None else ""
        axes = _tf4_profile(self.category)["axes"]
        lead = (
            "My first pick changed (repriced or out of stock) while shopping, so from a different listing "
            if ep.event is not None else ""
        )
        return (
            f"{lead}I'm going with {product.title or cand.pid} (SKU {cand.sku}){price_text}. "
            f"I compared the product facts against your priorities ({axes}) and re-checked its "
            "current price and stock: it is in stock and within your budget."
        )[:600]

# ========================================================================
# families/tf5_ranking.py
# ========================================================================

import re
from typing import Optional


# ---------------------------------------------------------------------------
# Goal parsing
# ---------------------------------------------------------------------------

# 'Compare only these candidate variants: k1, k2, k3. Choose ...' The segment ends at the
# first '.' followed by whitespace (keys never contain whitespace).
_TF5_LIST_RE = re.compile(r"candidate[^:.\n]{0,40}:\s*(.+?)\.(?=\s|$)", re.I | re.S)
_TF5_KEY_RE = re.compile(r"(?<![\w:.\-])([\w][\w.\-]*?)::([^\s,;]+)")
_TF5_BUDGET_RE = re.compile(
    r"at or (?:under|below)\s+(?:(?:PHP|₱|[A-Z]{3})\s*)?([0-9][0-9,]*(?:\.[0-9]+)?)\s*([A-Z]{3})?"
)
_TF5_CURRENCY_RE = re.compile(r"\b(PHP|USD|EUR|GBP|JPY|SGD|MYR|IDR|THB|VND|INR|AUD|CAD|HKD|KRW|CNY)\b")
_TF5_CATWORD_RE = re.compile(r"\bWant an?\s+in-stock\s+(.+?)\s+at or (?:under|below)\b", re.I)
_TF5_FACT_LABEL = {"refresh_rate": "refresh_rate", "screen_size": "size"}
_TF5_UNIT = {"refresh_rate": "hz", "screen_size": "in"}


def _tf5_clean_key(raw: str) -> Optional[str]:
    text = raw.strip().strip("()[]{}'\"`").rstrip(".,;:)]}")
    if text.lower().startswith("and "):
        text = text[4:].strip()
    pid, sep, sku = text.partition("::")
    pid, sku = pid.strip(), sku.strip()
    if not sep or not pid or not sku or re.search(r"\s", pid + sku):
        return None
    return f"{pid}::{sku}"


def _tf5_parse_goal(goal: str) -> dict:
    """Ordered candidate keys, original budget, currency and category word from the goal."""

    out: dict = {"keys": [], "budget": None, "currency": None, "cat_word": None}
    match = _TF5_BUDGET_RE.search(goal)
    if match:
        out["budget"] = float(match.group(1).replace(",", ""))
        out["currency"] = match.group(2)
    else:
        out["budget"] = parse_budget(goal)
    if not out["currency"]:
        cur = _TF5_CURRENCY_RE.search(goal)
        out["currency"] = cur.group(1) if cur else None
    match = _TF5_CATWORD_RE.search(goal)
    if match:
        out["cat_word"] = match.group(1).strip()
    match = _TF5_LIST_RE.search(goal)
    keys = _tf5_keys_in(match.group(1)) if match else []
    if not keys:  # other phrasings: every pid::sku token in the goal, in order
        keys = _tf5_keys_in(goal)
    out["keys"] = keys
    return out


def _tf5_keys_in(text: str) -> list:
    keys = []
    for pid, sku in _TF5_KEY_RE.findall(text or ""):
        key = _tf5_clean_key(f"{pid}::{sku}")
        if key:
            keys.append(key)
    return list(dict.fromkeys(keys))


# ---------------------------------------------------------------------------
# Tradeoff values (ranking.tradeoff_values on view data)
# ---------------------------------------------------------------------------


def _tf5_concept_values(key: str, text) -> set:
    return hz_values(text) if key == "refresh_rate" else inch_values(text)


def _tf5_fallback_value(key: str, view: dict, options) -> Optional[str]:
    """HEURISTIC for a listed key the exact port cannot resolve (facts-surface limits).

    facts['size'] also merges non-resolver keys (size, screen size inch, case size, ...)
    and facts['refresh_rate'] shows only the first 2 raw strings. The runtime always
    unions the title values, so a lone title value is its answer. Otherwise take the facts
    segment value seen most often, preferring later segments (the generic 'size' key
    renders first).
    """

    opt_values = _tf5_concept_values(key, options or "")
    if len(opt_values) == 1:
        return next(iter(opt_values))
    title_values = _tf5_concept_values(key, str(view.get("title") or ""))
    if len(title_values) == 1:
        return next(iter(title_values))
    text = str((view.get("facts") or {}).get(_TF5_FACT_LABEL[key]) or "").replace(" [truncated]", "")
    counts: dict = {}
    last: dict = {}
    for index, segment in enumerate(text.split("; ")):
        for value in _tf5_concept_values(key, segment):
            counts[value] = counts.get(value, 0) + 1
            last[value] = index
    if title_values:
        counts = {v: c for v, c in counts.items() if v in title_values} or {v: 1 for v in title_values}
    if not counts:
        return None
    return max(counts, key=lambda v: (counts[v], last.get(v, -1), v))


def _tf5_axis(view: dict, options, key: str) -> Optional[float]:
    """One tradeoff axis of one variant: exact port first, then the fallback heuristic."""

    value = resolve_variant_attribute_visible(view, options, key) or resolve_attribute_visible(view, key)
    if not value:
        value = _tf5_fallback_value(key, view, options)
    unit = _TF5_UNIT[key]
    if not value or not value.endswith(unit):
        return None
    try:
        number = float(value[: -len(unit)])
    except ValueError:
        return None
    return number if number > 0 else None


def _tf5_sort_key(item: tuple) -> tuple:
    key, vec = item
    return (-vec[0], -vec[1], vec[2], key)


def _tf5_short(title: str, limit: int = 90) -> str:
    text = " ".join(str(title or "").replace("?", "").split())
    return text if len(text) <= limit else text[: limit - 3].rstrip() + "..."


def _tf5_payload_is_evidence(payload: dict, target: str) -> bool:
    """Per-observation test of base.event_observed_or_signaled for a stockout target."""

    if not isinstance(payload, dict):
        return False
    event = payload.get("market_event") or {}
    tgt = event.get("target") or {}
    if f"{tgt.get('product_id') or ''}::{tgt.get('sku') or ''}" == target:
        return True
    tpid, tsku = split_key(target)
    rows = []
    if payload.get("product_id") and payload.get("sku"):
        rows.append(payload)
    rows.extend(payload.get("results") or [])
    rows.extend(payload.get("variants") or [])  # view rows; compare rows never count
    for row in rows:
        if not isinstance(row, dict):
            continue
        key = f"{row.get('product_id') or tpid}::{row.get('sku') or tsku}"
        if key == target and row.get("in_stock") is False:
            return True
    return False


# ---------------------------------------------------------------------------
# Engine: research -> commit pre-top -> (probe for the event) -> re-rank -> order
# ---------------------------------------------------------------------------


class _TF5Engine(Engine):
    """Three-turn TF5 protocol (see the module docstring)."""

    # Probe turns carry no message and no visible event, so they trigger no simulator call.
    _tf5_max_probes = 12

    def run(self) -> None:
        ep, strategy = self.ep, self.strategy
        strategy.parse()
        plan = self._research()
        if plan is None or ep.done:
            ep.notes.append("tf5: no rankable candidate, nothing to commit to")
            return
        strategy.plan = plan
        if not self._tf5_commit(plan):
            return
        if not self._tf5_await_event():
            ep.notes.append("tf5: no stockout visible after the commitment")
        final = self._tf5_choose_final()
        if final is None:
            ep.notes.append("tf5: no valid final candidate")
            return
        self._tf5_order(final)

    def _tf5_commit(self, plan: Plan) -> bool:
        ep, strategy = self.ep, self.strategy
        for _attempt in range(3):
            if ep.done or ep.turns_left() <= 2:
                return False
            self.env.call(strategy.commit_group(plan))
            if ep.first_add is not None:
                if ep.first_add.key != plan.commit.key:
                    ep.notes.append(f"tf5: first add {ep.first_add.key} != planned {plan.commit.key}")
                return True
            # A failed add is not a commitment; an unpurchasable key is outside the
            # verifier's pool too, so the next-ranked key is the real pre-event top.
            strategy.tf5_failed_adds.add(plan.commit.key)
            ep.notes.append(f"tf5: add of {plan.commit.key} failed; re-planning")
            replan = strategy.make_plan()
            if replan is None:
                return False
            plan = strategy.plan = replan
        return False

    def _tf5_await_event(self) -> bool:
        """The stockout must be seen in a turn before the order (probe late triggers)."""

        ep, strategy = self.ep, self.strategy
        for _probe in range(self._tf5_max_probes):
            if ep.done or strategy.tf5_evidence() is not None:
                break
            if ep.first_add is None or ep.turns_left() <= 3 or ep.time_left() < 45.0:
                break
            first = ep.first_add
            group = [
                action("add_to_cart", product_id=first.pid, sku=first.sku),
                action("inspect_stock", product_id=first.pid, sku=first.sku),
            ]
            group += strategy.tf5_reread(min(6, ep.max_calls - len(group)), first.key)
            self.env.call(group)
        return strategy.tf5_evidence() is not None

    def _tf5_choose_final(self) -> Optional[Candidate]:
        ep, strategy = self.ep, self.strategy
        for round_no in range(3):
            if ep.done:
                return None
            finals = strategy.finals_after_event()
            evidence = strategy.tf5_evidence()
            since = evidence[1] if evidence is not None else 0
            if not finals:
                if round_no >= 2 or self._low():
                    return None
                self._read_turns(strategy.tf5_reread(ep.max_calls, None))
                continue
            top = finals[0]
            if evidence is None or ep.state_checked_after(top.key, since) or self._low():
                return top
            reads = [
                action("inspect_stock", product_id=c.pid, sku=c.sku)
                for c in finals[:4]
                if not ep.state_checked_after(c.key, since)
            ]
            self._read_turns(reads)
        finals = strategy.finals_after_event()
        return finals[0] if finals else None

    def _tf5_order(self, final: Candidate) -> None:
        ep, strategy = self.ep, self.strategy
        for _attempt in range(2):
            if ep.done or ep.turns_left() < 1:
                return
            group = [
                action("message", content=strategy.order_message(final)[:600]),
                action("inspect_stock", product_id=final.pid, sku=final.sku),
            ]
            if not ep.in_cart(final.key):
                group.append(action("add_to_cart", product_id=final.pid, sku=final.sku))
            group += [
                action("inspect_cart"),
                {"name": "place_test_order", "args": {"product_id": final.pid, "sku": final.sku}},
            ]
            self.env.call(group)
            if ep.done:
                return
            ep.notes.append("tf5: order not placed; retrying")


# ---------------------------------------------------------------------------
# Strategy
# ---------------------------------------------------------------------------


@register_strategy
class RankingStrategy(Strategy):
    family = "ranking"
    max_research_rounds = 4
    max_recovery_rounds = 2
    engine_cls = _TF5Engine

    def __init__(self, ep) -> None:
        super().__init__(ep)
        self.tf5_keys: list = []  # listed candidate keys, goal order (the only answers)
        self.tf5_pids: list = []
        self.tf5_budget: Optional[float] = None  # ORIGINAL goal budget (verifier pool)
        self.tf5_category: Optional[str] = None
        self.tf5_cat_word: Optional[str] = None
        self.tf5_view_tries: dict = {}
        self.tf5_failed_adds: set = set()
        self.tf5_rounds = 0

    # -- parsing -------------------------------------------------------------
    def parse(self) -> None:
        ep = self.ep
        goal = _tf5_parse_goal(ep.goal_text)
        if goal["currency"]:
            ep.currency = goal["currency"]
        ep.set_budget(goal["budget"])
        self.tf5_budget = goal["budget"]
        self.tf5_keys = list(goal["keys"])
        self.tf5_pids = list(dict.fromkeys(split_key(k)[0] for k in self.tf5_keys))
        self.tf5_cat_word = goal["cat_word"]
        self.tf5_category = parse_category_word(ep.goal_text)
        ep.intent.update({
            "category": self.tf5_category,
            "cat_word": self.tf5_cat_word,
            "candidate_keys": list(self.tf5_keys),
            "priority": ["refresh_rate", "screen_size", "price"],
        })
        if not self.tf5_keys:
            ep.notes.append("tf5: no candidate list in the goal; ranking discovered candidates")

    # -- candidate state -------------------------------------------------------
    def tf5_pool(self) -> list:
        ep = self.ep
        if self.tf5_keys:
            return list(self.tf5_keys)
        keys = []
        for key in ep.known_keys(detailed_only=True):
            product = ep.product(split_key(key)[0])
            if self.tf5_category and not category_matches(
                self.tf5_category, product.category_path, title=product.title
            ):
                continue
            keys.append(key)
        return keys

    def tf5_present(self, key: str) -> bool:
        pid, sku = split_key(key)
        product = self.ep.products.get(pid)
        return bool(product is not None and product.detailed and sku in product.variants)

    def tf5_live(self, key: str) -> bool:
        """In stock by the latest observation and not covered by an observed event."""

        ep = self.ep
        return key not in ep.excluded and key not in self.tf5_failed_adds and ep.in_stock(key) is True

    def tf5_vector(self, key: str) -> Optional[tuple]:
        """(refresh_hz, screen_in, live price), or None when unresolvable."""

        ep = self.ep
        if not self.tf5_present(key):
            return None
        pid, sku = split_key(key)
        view = ep.view_row(pid)
        options = (find_variant(view, sku) or {}).get("options")
        refresh = _tf5_axis(view, options, "refresh_rate")
        size = _tf5_axis(view, options, "screen_size")
        price = ep.price(key)
        if refresh is None or size is None or price is None:
            return None
        return (refresh, size, float(price))

    def tf5_ranked(self) -> list:
        """[(key, vector)] best first: (-refresh, -size, price, key) over the live pool.

        The pool mirrors ranking.true_state_pool: in stock (latest read), not hit by the
        event, price <= the ORIGINAL budget. Unresolvable listed keys (vector None) are
        placed by the goal's list order when it agrees with the computed ranking, else last.
        """

        ep = self.ep
        budget = self.tf5_budget
        resolved, unresolved = [], []
        for key in self.tf5_pool():
            if not self.tf5_present(key) or not self.tf5_live(key):
                continue
            price = ep.price(key)
            if price is None or (budget is not None and price > budget + 1e-9):
                continue
            vec = self.tf5_vector(key)
            if vec is None:
                unresolved.append(key)
            else:
                resolved.append((key, vec))
        resolved.sort(key=_tf5_sort_key)
        if unresolved and self.tf5_keys:
            return self._tf5_merge_unresolved(resolved, unresolved)
        return resolved

    def _tf5_merge_unresolved(self, resolved: list, unresolved: list) -> list:
        position = {k: i for i, k in enumerate(self.tf5_keys)}
        vectors = dict(resolved)
        order = [k for k, _v in resolved]
        consistent = all(
            position[a] < position[b] or vectors[a] == vectors[b] for a, b in zip(order, order[1:])
        )
        tail = [(k, None) for k in sorted(unresolved, key=lambda k: position.get(k, 10**6))]
        if not consistent:
            return resolved + tail
        merged, resolved_iter, wanted = [], iter(resolved), set(order) | set(unresolved)
        for key in self.tf5_keys:
            if key not in wanted:
                continue
            merged.append((key, None) if key in unresolved else next(resolved_iter))
        return merged

    @staticmethod
    def tf5_tie_class(ranked: list) -> list:
        if not ranked:
            return []
        top_key, top_vec = ranked[0]
        if top_vec is None:
            return [top_key]
        return sorted(k for k, v in ranked if v == top_vec)

    def tf5_evidence(self) -> Optional[tuple]:
        """(turn, seq) of the first observation proving the first add's stockout, else None."""

        ep = self.ep
        if ep.first_add is None:
            return None
        target = ep.first_add.key
        seq, after_add = 0, False
        for row in ep.log:
            if "results" not in row:
                continue
            for act, result in zip(row.get("calls") or [], row.get("results") or []):
                seq += 1
                payload = result.get("observation") if isinstance(result, dict) else None
                if not isinstance(payload, dict):
                    continue
                if not after_add:
                    after_add = act.get("name") == "add_to_cart" and isinstance(payload.get("added"), dict)
                    if not after_add:
                        continue
                if act.get("name") != "compare" and _tf5_payload_is_evidence(payload, target):
                    return (row.get("turn"), seq)
        return None

    def _tf5_read_products(self, pids: list, room: Optional[int]) -> list:
        if not pids:
            return []
        limit = self.ep.max_calls if room is None else room
        if limit <= 0:
            return []
        if len(pids) <= limit:
            return [action("view", product_id=p) for p in pids]
        chunks = [pids[i : i + COMPARE_LIMIT] for i in range(0, len(pids), COMPARE_LIMIT)]
        if room is not None:
            chunks = chunks[: min(room, MAX_COMPARES_PER_GROUP)]
        return [action("compare", product_ids=chunk) for chunk in chunks]

    def tf5_reread(self, room: int, commit_key: Optional[str]) -> list:
        """Re-read candidate products after the add: tie-class twins first, then by rank."""

        ranked = self.tf5_ranked()
        klass = self.tf5_tie_class(ranked)
        pids: list = []
        for key in [*klass, *(k for k, _v in ranked), *self.tf5_pool()]:
            pid = split_key(key)[0]
            if pid not in pids:
                pids.append(pid)
        if commit_key is not None:
            commit_pid = split_key(commit_key)[0]
            siblings = [k for k in self.tf5_pool() if split_key(k)[0] == commit_pid and k != commit_key]
            if commit_pid in pids and not siblings:  # inspect_stock already re-reads it
                pids.remove(commit_pid)
                pids.append(commit_pid)
        return self._tf5_read_products(pids, room)

    # -- Strategy hooks ----------------------------------------------------------
    def research_actions(self, round_no: int) -> list:
        ep = self.ep
        self.tf5_rounds = round_no + 1
        if self.tf5_keys:
            pids = [p for p in self.tf5_pids if not ep.detailed(p) and self.tf5_view_tries.get(p, 0) < 2]
            for pid in pids:
                self.tf5_view_tries[pid] = self.tf5_view_tries.get(pid, 0) + 1
            return self._tf5_read_products(pids, None)
        if round_no == 0:
            return [
                action("search", query=ep.goal_text[:150], k=10, in_stock=True, max_price=self.tf5_budget),
                action("filter", category=self.tf5_category, max_price=self.tf5_budget, in_stock=True, k=10),
            ]
        return self.compare_unseen(limit=COMPARE_LIMIT, groups=MAX_COMPARES_PER_GROUP)

    def make_plan(self) -> Optional[Plan]:
        ep = self.ep
        if self.tf5_keys:
            if any(not ep.detailed(p) and self.tf5_view_tries.get(p, 0) < 2 for p in self.tf5_pids):
                return None  # every listed product is read before the first add
        elif self.tf5_rounds < 2:
            return None
        ranked = self.tf5_ranked()
        if not ranked:
            return None
        klass = set(self.tf5_tie_class(ranked))
        commit = Candidate(*split_key(ranked[0][0]), score=1.0, reason="pre-event lexicographic top")
        finals = [Candidate(*split_key(k), score=0.0) for k, _v in ranked if k not in klass]
        return Plan(commit=commit, finals=finals, preadd=False)

    def commit_group(self, plan: Plan) -> list:
        ep = self.ep
        commit = plan.commit
        group = [
            action("add_to_cart", product_id=commit.pid, sku=commit.sku),
            action("inspect_stock", product_id=commit.pid, sku=commit.sku),
        ]
        return group + self.tf5_reread(ep.max_calls - len(group), commit.key)

    def finals_after_event(self) -> list:
        first = self.ep.first_add.key if self.ep.first_add is not None else None
        return [Candidate(*split_key(k), score=0.0) for k, _v in self.tf5_ranked() if k != first]

    def final_ok(self, key: str) -> bool:
        first = self.ep.first_add.key if self.ep.first_add is not None else None
        return key != first and any(k == key for k, _v in self.tf5_ranked())

    def candidate_ok(self, key: str) -> bool:
        if self.tf5_keys and key not in self.tf5_keys:
            return False
        return self.tf5_vector(key) is not None

    def candidate_score(self, key: str) -> float:
        vec = self.tf5_vector(key)
        if vec is None:
            return -1e18
        return vec[0] * 1e12 + vec[1] * 1e8 - vec[2]

    def recovery_actions(self, round_no: int) -> list:
        return self.tf5_reread(self.ep.max_calls, None)

    def justification(self, cand: Candidate) -> Optional[dict]:
        return None  # a false claim zeroes the family gate; none is required

    def order_message(self, cand: Candidate) -> str:
        ep = self.ep
        title = _tf5_short(ep.product(cand.pid).title or cand.pid)
        vec = self.tf5_vector(cand.key)
        price = ep.price(cand.key)
        facts = []
        if vec is not None:
            facts += [f"{vec[0]:g}Hz", f"{vec[1]:g}-inch"]
        if price is not None:
            facts.append(f"{fmt_money(price)} {ep.currency}")
        detail = f": {', '.join(facts)}" if facts else ""
        parts = []
        first = ep.first_add
        if first is not None and first.key != cand.key and self.tf5_evidence() is not None:
            first_title = _tf5_short(ep.product(first.pid).title or first.pid)
            parts.append(
                f"Update: {first_title} (SKU {first.sku}), the top pick I added to the cart, went out "
                "of stock right after I added it, so I re-ranked the remaining candidates by your "
                "priority: highest refresh rate, then largest screen, then lowest price."
            )
        parts.append(
            f"I'm ordering {title} (SKU {cand.sku}{detail}). I re-checked its current price and "
            "stock: it is the best-ranked option still available and within your budget."
        )
        return " ".join(parts).replace("?", "")[:600]

# ========================================================================
# families/tf6_recovery.py
# ========================================================================

import re
from typing import Optional


# ---------------------------------------------------------------------------
# Goal text and query helpers
# ---------------------------------------------------------------------------

# Longest shade first so 'midnight blue' wins over 'blue' (the runtime's span rule).
_TF6_COLORS = tuple(sorted(set(_COLOR_PHRASES) | {"sage green"}, key=lambda c: (-len(c), c)))
_TF6_COLOR_RES = tuple(
    (
        re.compile(r"(?<![a-z0-9])" + r"\W+".join(re.escape(w) for w in c.split()) + r"(?![a-z0-9])"),
        "green" if c == "sage green" else c,
    )
    for c in _TF6_COLORS
)
# Colors worth a same-model sibling query after the event, most common first.
_TF6_DISCOVERY_COLORS = (
    "black", "white", "blue", "green", "silver", "gold", "gray", "grey", "purple", "pink",
    "red", "graphite", "midnight blue", "titanium black", "light blue", "sky blue", "violet",
    "starlight", "beige", "peach", "khaki", "sandstone", "transparent",
)
_TF6_BUDGET_RE = re.compile(
    r"\b(?:at\s+or\s+(?:below|under)|no\s+more\s+than|up\s+to|under|below|within|"
    r"max(?:imum)?(?:\s+of)?)\s+(?:PHP|₱|\$)?\s*([0-9][0-9,]*(?:\.[0-9]+)?)",
    re.I,
)
_TF6_PREF_RES = (
    re.compile(r"\bstrongly\s+prefers?\s+(?:the|a|an)\s+(.+?)\s*(?:\.(?=\s|$)|;|\s+if\s)", re.I | re.S),
    re.compile(r"\bprefer(?:s|red|ably)?\s+(?:the|a|an)\s+(.+?)\s*(?:\.(?=\s|$)|;|,|\s+if\s)", re.I | re.S),
    re.compile(r"\beye\s+on\s+the\s+(.+?)\s*(?:\s+specifically\b|\.(?=\s|$)|;|,)", re.I | re.S),
    re.compile(
        r"\b(?:ideally|specifically|really\s+want|would\s+love|hoping\s+for)\s+(?:the|a|an)\s+"
        r"(.+?)\s*(?:\.(?=\s|$)|;|,|\s+if\s)",
        re.I | re.S,
    ),
)
# Last resorts, accepted only when the phrase names a known color ('want the black Z9PRO',
# '... if possible the pink 635.').
_TF6_LOOSE_PREF_RES = (
    re.compile(
        r"\b(?:want|wants|looking\s+for|after|get|buy|order)\s+(?:the|a|an)\s+(.+?)\s*"
        r"(?:\.(?=\s|$)|;|,|\s+if\s|\s+at\s+or\s|\s+under\s|\s+for\s)",
        re.I | re.S,
    ),
    re.compile(r"\bthe\s+(.+?)\s*(?:[.;,!?](?=\s|$)|\s+if\s|\s+please\b|$)", re.I | re.S),
)
_TF6_COLOR_LABELS = frozenset(label for _pattern, label in _TF6_COLOR_RES)
# Trailing only: 'Headphones 700' is itself a runtime named model.
_TF6_DEVICE_WORDS_RE = re.compile(r"(?i)\s+(?:(?:smart\s*)?phones?|mobiles?|headphones?|headsets?)$")
_TF6_SUFFIX_RE = re.compile(
    r"(?i)(?<=[a-z0-9])(PRO|MAX|ULTRA|PLUS|LITE|MINI|NEO|PRIME)"
    r"(?=(?:PRO|MAX|ULTRA|PLUS|LITE|MINI|NEO|PRIME)*$)"
)


def _tf6_split_pref(phrase: str) -> tuple:
    """'black Z9PRO' -> ('black', 'Z9PRO'); also 'Z9PRO in midnight blue', 'white 8520 phone'."""

    text = " ".join(str(phrase or "").replace('"', " ").split()).strip(" .,'")
    low = text.casefold()
    color, model = None, None
    for name in _TF6_COLORS:
        if low.startswith(name + " "):
            color, model = ("green" if name == "sage green" else name), text[len(name):]
            break
    else:
        for pattern, label in _TF6_COLOR_RES:
            match = pattern.search(low)
            if match:
                rest = text[: match.start()] + " " + text[match.end():]
                rest = re.sub(r"(?i)\b(?:in|colou?r(?:way)?|finish|the|one|version)\b|[(),/]", " ", rest)
                if rest.strip(" -"):
                    color, model = label, rest
                    break
    if color is None:
        first, _, rest = text.partition(" ")
        color, model = first.casefold(), rest
    model = " ".join(str(model or "").split()).strip(" -")
    for _round in range(2):  # a device word is never part of a normalized model label
        model = _TF6_DEVICE_WORDS_RE.sub("", model).strip(" -")
    return color, model


def _tf6_parse_goal(goal: str) -> dict:
    """Budget, currency, category/device word, preferred color and model from the goal."""

    goal = str(goal or "")
    out: dict = {"budget": None, "currency": None, "category": "Smartphones",
                 "device": "smartphone", "color": None, "model": None}
    match = _TF6_BUDGET_RE.search(goal)
    if match:
        out["budget"] = parse_money(match.group(1))
        currency = re.match(r"\s*([A-Z]{3})\b", goal[match.end(1):])
        if currency:
            out["currency"] = currency.group(1)
    if out["budget"] is None:
        out["budget"] = parse_budget(goal)
    low = goal.casefold()
    if re.search(r"\bhead\s*phones?\b|\bheadsets?\b", low) and not re.search(r"\bsmart\s*phones?\b", low):
        out["category"], out["device"] = "Headphones", "headphones"
    for pattern in _TF6_PREF_RES:
        match = pattern.search(goal)
        if match:
            out["color"], out["model"] = _tf6_split_pref(match.group(1))
            break
    else:
        for pattern in _TF6_LOOSE_PREF_RES:
            for match in pattern.finditer(goal):
                color, model = _tf6_split_pref(match.group(1))
                if color in _TF6_COLOR_LABELS and model and re.search(r"\d", model):
                    out["color"], out["model"] = color, model
                    return out
    return out


def _tf6_model_forms(model: str) -> list:
    """The goal's normalized code plus its re-spaced suffix form ('15PROMAX' -> '15 PRO MAX')."""

    model = " ".join(str(model or "").split())
    if not model:
        return []
    forms = [model]
    spaced = " ".join(_TF6_SUFFIX_RE.sub(r" \1", model).split())
    if spaced.casefold() != model.casefold():
        forms.append(spaced)
    return forms


def _tf6_split_union(model: str) -> Optional[str]:
    """One bag-of-words query holding every 2-part split of a mixed code ('SMA155F' ->
    '... SM A155F SMA 155F ...'): catalog titles write 'SM-A155F' as two tokens."""

    code = re.sub(r"[^A-Za-z0-9]", "", str(model or ""))
    if not 4 <= len(code) <= 14 or not re.search(r"[A-Za-z]", code) or not re.search(r"\d", code):
        return None
    parts = [code]
    for i in range(2, len(code) - 1):
        parts += [code[:i], code[i:]]
    return " ".join(dict.fromkeys(parts))


def _tf6_sku_family(sku: str) -> str:
    """Lazada skus of one listing share the prefix before the last '-' (item id)."""

    sku = str(sku or "")
    return sku.rsplit("-", 1)[0] if "-" in sku else sku


def _tf6_title_mentions(title: str, model: str) -> bool:
    code = re.sub(r"[^a-z0-9]", "", str(model or "").casefold())
    if len(code) < 2:
        return False
    low = str(title or "").casefold()
    if code.isdigit():
        return re.search(r"(?<![a-z0-9])" + code + r"(?![0-9])", low) is not None
    return code in re.sub(r"[^a-z0-9]", "", low)


def _tf6_has_color(text: str, color: str) -> bool:
    color = str(color or "").casefold()
    low = str(text or "").casefold()
    for pattern, label in _TF6_COLOR_RES:
        if label == color and pattern.search(low):
            return True
    return False


def _tf6_strip_colors(title: str, max_tokens: int = 10) -> str:
    low = str(title or "").casefold()
    for pattern, _label in _TF6_COLOR_RES:
        low = pattern.sub(" ", low)
    low = re.sub(r"\b(?:colou?r|family|edition|variant)\b", " ", low)
    tokens = re.findall(r"[a-z0-9][a-z0-9.+]*", low)
    return " ".join(tokens[:max_tokens])


def _tf6_title_can_be_row(title: str, category: str) -> bool:
    """Title-only half of the runtime's row admission: a hit failing it is never acceptable."""

    title = str(title or "")
    if not title.strip():
        return True  # unknown yet
    if category == "Headphones":
        return recovery_valid_headphone_title(title)
    return recovery_valid_smartphone_title(title) and (
        smartphone_evidence({"title": title, "facts": {}}, "")["status"] != "conflict"
    )


def _tf6_same_model(model: Optional[str], preferred: str) -> bool:
    if not model or not preferred:
        return False
    return model.casefold() == preferred.casefold() or (
        model_code(model) is not None and model_code(model) == model_code(preferred)
    )


# ---------------------------------------------------------------------------
# Engine: research -> commit -> discover/verify replacement -> order
# ---------------------------------------------------------------------------


class _Tf6Engine(Engine):
    """Default engine phases with TF6-specific research and recovery loops."""

    def run(self) -> None:
        ep, st = self.ep, self.strategy
        st.parse()
        plan = self._research()
        if ep.done:
            return
        if plan is None:
            plan = st.tf6_fallback_plan()
            if plan is None:
                ep.notes.append("tf6: nothing to commit to")
                return
            ep.notes.append("tf6: no level-0 listing verified; best-effort commit")
        st.plan = plan
        self._commit(plan)
        if ep.done:
            return
        final = self._choose_final(plan)
        if final is None:
            ep.notes.append("tf6: no valid replacement")
            return
        self._order(final)

    def _research(self) -> Optional[Plan]:
        ep, st = self.ep, self.strategy
        for round_no in range(st.max_research_rounds):
            if ep.done or self._low() or st.tf6_ready(round_no):
                break
            actions = st.research_actions(round_no)
            if not actions:
                break
            self._read_turns(actions)
        return st.make_plan()

    def _tf6_await_event(self) -> None:
        """Pack events fire on the first add; other triggers get read-only probe turns."""

        ep, st = self.ep, self.strategy
        for _probe in range(3):
            if ep.done or ep.first_add is None or st.tf6_detect_event():
                return
            if ep.turns_left() <= 4 or ep.time_left() < 40.0:
                return
            group = [action("inspect_cart")]
            seen: set = set()
            for (_t, _s, key, ok) in ep.adds:
                if ok and key not in seen:
                    seen.add(key)
                    pid, sku = split_key(key)
                    group.append(action("inspect_stock", product_id=pid, sku=sku))
            self.env.call(group[: ep.max_calls])
        st.tf6_detect_event()

    def _choose_final(self, plan: Plan) -> Optional[Candidate]:
        ep, st = self.ep, self.strategy
        self._tf6_await_event()
        for round_no in range(st.max_recovery_rounds):
            if ep.done:
                return None
            if self._low():
                break
            actions = st.recovery_actions(round_no)
            if not actions:
                break
            self._read_turns(actions)
        for _attempt in range(3):
            if ep.done:
                return None
            finals = st.finals_after_event()
            if not finals:
                break
            cand = finals[0]
            needs = st.tf6_evidence_needs(cand)
            if not needs or self._low():
                return cand
            self._read_turns(needs)
            if st.final_ok(cand.key) and not st.tf6_evidence_needs(cand):
                return cand
        finals = st.finals_after_event()
        return finals[0] if finals else None


# ---------------------------------------------------------------------------
# Strategy
# ---------------------------------------------------------------------------


@register_strategy
class RecoveryStrategy(Strategy):
    family = "recovery"
    max_research_rounds = 6
    max_recovery_rounds = 5
    engine_cls = _Tf6Engine

    def __init__(self, ep) -> None:
        super().__init__(ep)
        self.tf6_goal: dict = {}
        self.tf6_model = ""
        self.tf6_color = ""
        self.tf6_category = "Smartphones"
        self.tf6_device = "smartphone"
        self.tf6_budget0: Optional[float] = None
        self._tf6_static: dict = {}  # key -> {profile, model, color, title, family}
        self._tf6_base: dict = {}  # key -> pre-commit (base) price
        self._tf6_queries: set = set()  # (query casefold, post_event)
        self._tf6_requested: set = set()  # pids sent to compare/view by this strategy
        self._tf6_search_rounds = 0  # post-event rounds that ran discovery searches
        self._tf6_llm_used = False

    # -- parsing ---------------------------------------------------------------
    def parse(self) -> None:
        ep = self.ep
        goal = _tf6_parse_goal(ep.goal_text)
        if (not goal.get("model") or not goal.get("color") or goal.get("budget") is None):
            goal = self._tf6_llm_goal(goal)
        self.tf6_goal = goal
        ep.set_budget(goal.get("budget"))
        if goal.get("currency"):
            ep.currency = goal["currency"]
        self.tf6_budget0 = ep.original_budget
        self.tf6_category = goal.get("category") or "Smartphones"
        self.tf6_device = goal.get("device") or "smartphone"
        self.tf6_color = str(goal.get("color") or "").casefold()
        self.tf6_model = str(goal.get("model") or "")
        ep.intent.update({"category": self.tf6_category, "preferred_color": self.tf6_color,
                          "preferred_model": self.tf6_model})
        ep.notes.append(f"tf6 goal: {goal}")

    def _tf6_llm_goal(self, goal: dict) -> dict:
        reply = llm_json(
            "Extract the shopper's request from a shopping goal.",
            "Goal: " + self.ep.goal_text[:800] + '\nReturn {"budget": number, "currency": "PHP", '
            '"color": "preferred color, lowercase", "model": "preferred model exactly as written"}.',
            max_tokens=150, timeout=20.0,
        )
        if not isinstance(reply, dict):
            return goal
        out = dict(goal)
        if out.get("budget") is None and parse_money(reply.get("budget")) is not None:
            out["budget"] = parse_money(reply.get("budget"))
        for field in ("color", "model", "currency"):
            if not out.get(field) and isinstance(reply.get(field), str) and reply[field].strip():
                out[field] = reply[field].strip()
        return out

    # -- per-key labels ----------------------------------------------------------
    def _tf6_row(self, key: str) -> Optional[dict]:
        """Static recovery labels of one detailed variant (runtime ports, cached)."""

        cached = self._tf6_static.get(key)
        if cached is not None:
            return cached
        ep = self.ep
        pid, sku = split_key(key)
        product = ep.product(pid)
        if not product.detailed or sku not in product.variants:
            return None
        view = ep.view_row(pid)
        variant = find_variant(view, sku) or {}
        options = variant.get("options")
        profile = recovery_profile(view, options)
        row = {
            "profile": profile,
            "model": recovery_model_label(view, options) if profile else None,
            "color": recovery_color_label(view, options) if profile else None,
            "title": str(view.get("title") or ""),
            "family": _tf6_sku_family(sku),
        }
        self._tf6_static[key] = row
        return row

    def tf6_base_price(self, key: str) -> Optional[float]:
        if key in self._tf6_base:
            return self._tf6_base[key]
        return self.ep.price(key)

    def tf6_level(self, key: str) -> Optional[int]:
        """The verifier's relaxation level of an acceptable key, None when not a row."""

        row = self._tf6_row(key)
        if not row or row["profile"] != self.tf6_category:
            return None
        base = self.tf6_base_price(key)
        if base is None or (self.tf6_budget0 is not None and base > self.tf6_budget0 + 1e-9):
            return None
        return relaxation_level(row["model"], row["color"], self.tf6_model, self.tf6_color)

    def _tf6_snapshot_base(self) -> None:
        ep = self.ep
        for key in ep.known_keys():
            if key not in self._tf6_base and ep.price(key) is not None:
                self._tf6_base[key] = ep.price(key)

    def _tf6_same_model_keys(self) -> list:
        out = []
        for key in self.ep.known_keys(detailed_only=True):
            row = self._tf6_row(key)
            if row and row["profile"] == self.tf6_category and _tf6_same_model(row["model"], self.tf6_model):
                out.append(key)
        return out

    def _tf6_model_families(self) -> set:
        fams = {self._tf6_row(k)["family"] for k in self._tf6_same_model_keys()}
        if self.ep.first_add is not None:
            fams.add(_tf6_sku_family(self.ep.first_add.sku))
        return {f for f in fams if f}

    def _tf6_model_titles(self) -> set:
        return {_tf6_strip_colors(self._tf6_row(k)["title"]) for k in self._tf6_same_model_keys()}

    def tf6_orderable(self, key: str) -> bool:
        ep = self.ep
        price = ep.price(key)
        return (key not in ep.excluded and ep.in_stock(key) is True and price is not None
                and (ep.budget is None or price <= ep.budget + 1e-9))

    # -- candidates ------------------------------------------------------------------
    def tf6_commit_candidates(self) -> list:
        """Level-0 keys (chosen by the ORIGINAL budget: that is what the commitment check uses)."""

        ep = self.ep
        sibling_count: dict = {}
        for key in self._tf6_same_model_keys():
            fam = self._tf6_row(key)["family"]
            sibling_count[fam] = sibling_count.get(fam, 0) + 1
        rows = []
        for key in ep.known_keys(detailed_only=True):
            if key in ep.excluded or ep.in_stock(key) is not True or self.tf6_level(key) != 0:
                continue
            fam = self._tf6_row(key)["family"]
            rows.append((-sibling_count.get(fam, 0), self.tf6_base_price(key) or 0.0, key))
        rows.sort()
        return [Candidate(pid=split_key(k)[0], sku=split_key(k)[1], score=3.0) for _n, _p, k in rows]

    def tf6_finals(self, exclude: Optional[set] = None) -> list:
        """Orderable acceptable keys, least relaxed first, then cheapest."""

        ep = self.ep
        exclude = set(exclude or ())
        if ep.event is not None:
            exclude.add(ep.event.target_key)
            exclude.update(ep.event.targets)
        rows = []
        for key in ep.known_keys(detailed_only=True):
            if key in exclude:
                continue
            level = self.tf6_level(key)
            if level is None or not self.tf6_orderable(key):
                continue
            rows.append((level, ep.price(key) or 0.0, key))
        rows.sort()
        return [Candidate(pid=split_key(k)[0], sku=split_key(k)[1], score=float(3 - lvl))
                for lvl, _p, k in rows]

    def _tf6_unseen(self, min_score: int = 0) -> list:
        """Search hits never compared/viewed, most promising first: [(pid, score)]."""

        ep = self.ep
        fams = self._tf6_model_families()
        titles = self._tf6_model_titles()
        best: dict = {}
        for idx, (_turn, _name, _args, keys) in enumerate(ep.searches):
            # A query matching fewer than k documents is specific (a rare model code also
            # matches spec values and options in the production index): an ordering hint only,
            # "strong" (>= 3) still needs model evidence (sku family, title, same title).
            specific = 1 if 0 < len(keys) < 10 else 0
            for pos, key in enumerate(keys):
                pid, sku = split_key(key)
                if pid in self._tf6_requested or ep.product(pid).detailed:
                    continue
                if key in ep.excluded or ep.in_stock(key) is False:
                    continue
                price = ep.price(key)
                if price is not None and self.tf6_budget0 is not None and price > self.tf6_budget0 + 1e-9:
                    continue
                title = ep.product(pid).title
                if not _tf6_title_can_be_row(title, self.tf6_category):
                    continue
                score = specific
                if _tf6_sku_family(sku) in fams:
                    score += 4
                if _tf6_title_mentions(title, self.tf6_model):
                    score += 3
                if titles and _tf6_strip_colors(title) in titles:
                    score += 2
                if self.tf6_color and _tf6_has_color(title, self.tf6_color):
                    score += 1
                old = best.get(pid)
                if old is None or (score, -pos, -idx) > (old[0], -old[1], -old[2]):
                    best[pid] = (score, pos, idx)
        items = [(pid, val) for pid, val in best.items() if val[0] >= min_score]
        items.sort(key=lambda it: (-it[1][0], it[1][1], it[1][2], it[0]))
        return [(pid, val[0]) for pid, val in items]

    # -- actions -----------------------------------------------------------------------
    def _tf6_search(self, query: str, *, post: bool) -> Optional[dict]:
        query = " ".join(str(query or "").split())[:150]
        if not query:
            return None
        mark = (query.casefold(), post)
        if mark in self._tf6_queries:
            return None
        self._tf6_queries.add(mark)
        cap = self.ep.budget if post else self.tf6_budget0
        return action("search", query=query, k=10, in_stock=True, max_price=cap)

    def _tf6_compares(self, pids: list, max_groups: int = 3) -> list:
        out = []
        pids = [p for p in dict.fromkeys(pids) if p not in self._tf6_requested]
        for i in range(0, min(len(pids), max_groups * COMPARE_LIMIT), COMPARE_LIMIT):
            chunk = pids[i : i + COMPARE_LIMIT]
            self._tf6_requested.update(chunk)
            out.append(action("compare", product_ids=chunk))
        return out

    def _tf6_goal_queries(self) -> list:
        model, color, device = self.tf6_model, self.tf6_color, self.tf6_device
        if not model:
            return [f"{color} {device}".strip()]
        forms = _tf6_model_forms(model)
        main = forms[-1]
        queries = [model]
        if main != model:
            queries.append(main)
        queries += [f"{color} {main} {device}", self._tf6_enriched(main)[0]]
        union = _tf6_split_union(model) if len(forms) == 1 else None
        if union and union.casefold() != model.casefold():
            queries.append(union)
        queries += [f"{main} {device}", f"{color} {model}"]
        return [" ".join(q.split()) for q in dict.fromkeys(queries) if q.strip()]

    def _tf6_enriched(self, main: str) -> list:
        """Model queries padded with words device listings carry and accessory listings lack
        (cases and protectors named after the model otherwise fill every top-10)."""

        if self.tf6_category == "Headphones":
            return [f"{main} over ear headphones", f"{main} wireless bluetooth over ear headphones",
                    f"{main} on ear headphones"]
        return [f"{main} 5G smartphone 256GB", f"{main} smartphone android dual sim 4G",
                f"{main} smartphone 8GB 128GB"]

    def _tf6_query_for(self, key: Optional[str]) -> Optional[str]:
        """The search query that ranked ``key`` highest (re-run in stock after the event)."""

        best = None
        for (_turn, name, args, keys) in self.ep.searches:
            if name == "search" and key in keys:
                pos = keys.index(key)
                if best is None or pos < best[0]:
                    best = (pos, str(args.get("query") or ""))
        return best[1] if best else None

    def _tf6_seed_queries(self, round_no: int) -> list:
        """Pre-event queries seeded by what the first rounds showed."""

        ep = self.ep
        color = self.tf6_color
        queries: list = list(self._tf6_enriched((_tf6_model_forms(self.tf6_model) or [""])[-1])[1:])
        titles = []
        for pid, score in self._tf6_unseen(min_score=3)[:3]:
            titles.append(ep.product(pid).title)
        for key in self._tf6_same_model_keys():
            titles.append(self._tf6_row(key)["title"])
        for title in titles:
            base = _tf6_strip_colors(title)
            if base:
                queries += [f"{color} {base}", base]
        if round_no >= 2 and not self._tf6_llm_used:
            self._tf6_llm_used = True
            queries += self._tf6_llm_queries()
        for form in _tf6_model_forms(self.tf6_model):
            queries += [f"{form} {color}", f"{self.tf6_device} {form}"]
        return [q for q in dict.fromkeys(" ".join(q.split()) for q in queries) if q]

    def _tf6_llm_queries(self) -> list:
        reply = llm_json(
            "You write short full-text search queries for an online electronics catalog.",
            f"A shopper wants the {self.tf6_color} {self.tf6_model} ({self.tf6_device}). The model "
            "code is normalized (upper case, spaces and hyphens removed). Suggest up to 3 short "
            'queries as sellers would title it (brand, series, model). Return {"queries": [...]}.',
            max_tokens=200, timeout=20.0,
        )
        queries = reply.get("queries") if isinstance(reply, dict) else None
        return [q for q in queries or [] if isinstance(q, str) and q.strip()][:3]

    def _tf6_empty_queries(self) -> set:
        """Queries that already returned nothing (an in-stock re-run cannot return more)."""

        return {str(args.get("query") or "").casefold() for (_t, name, args, keys) in self.ep.searches
                if name == "search" and not keys}

    def _tf6_take_searches(self, queries: list, limit: int, *, post: bool) -> list:
        """Search actions for the first ``limit`` fresh queries (only those are marked done)."""

        empty = self._tf6_empty_queries() if post else set()
        out: list = []
        for query in queries:
            if len(out) >= limit:
                break
            if " ".join(str(query or "").split()).casefold() in empty:
                continue
            act = self._tf6_search(query, post=post)
            if act:
                out.append(act)
        return out

    def _tf6_sibling_queries(self, commit_key: Optional[str] = None) -> list:
        """Post-event re-runs that expose the committed listing's hidden siblings."""

        ep = self.ep
        if commit_key is None and ep.first_add is not None:
            commit_key = ep.first_add.key
        main = (_tf6_model_forms(self.tf6_model) or [""])[-1]
        title = _tf6_strip_colors(ep.product(split_key(commit_key)[0]).title) if commit_key else ""
        # 1) the query that ranked the commit best: its listing's next sibling surfaces;
        # 2) the commit's own title plus the preferred color: a same-color sibling (a second
        #    full match, e.g. another storage variant) outranks the other colors.
        queries = [self._tf6_query_for(commit_key), f"{self.tf6_color} {title}" if title else ""]
        if main:
            queries.append(f"{main} {self.tf6_device}")
        queries += [title, self.tf6_model]
        return [q for q in dict.fromkeys(" ".join(str(q or "").split()) for q in queries) if q]

    def _tf6_discovery_queries(self, level: Optional[int]) -> list:
        """Post-event queries: hidden siblings, then other colors of the model; when nothing
        reaches level 2 yet, same-color queries (any other model is level 2) come first."""

        main = (_tf6_model_forms(self.tf6_model) or [""])[-1]
        device, color = self.tf6_device, self.tf6_color
        seen_colors = {str(self._tf6_row(k)["color"] or "") for k in self._tf6_same_model_keys()}
        colors = [f"{other} {main}" for other in _TF6_DISCOVERY_COLORS
                  if main and other != color and other not in seen_colors][:10]
        fish = [f"{color} {device}".strip(), f"{color} {device} {main}".strip(), device]
        order = self._tf6_sibling_queries()
        order += (fish + colors) if level is None or level >= 3 else colors
        return [q for q in dict.fromkeys(" ".join(q.split()) for q in order) if q]

    # -- engine hooks --------------------------------------------------------------------
    def tf6_ready(self, round_no: int) -> bool:
        """Stop pre-event research: a level-0 key is verified and nothing better is pending."""

        if round_no == 0 or not self.tf6_commit_candidates():
            return False
        commit = self.tf6_commit_candidates()[0]
        finals = self.tf6_finals(exclude={commit.key})
        if finals and (self.tf6_level(finals[0].key) or 0) <= 1:
            return True
        return round_no >= 3 or not self._tf6_unseen(min_score=3)

    def research_actions(self, round_no: int) -> list:
        """Round 0 searches the model; later rounds compare the most promising unseen hits and,
        while no level-0 key is verified, add enriched/seeded searches."""

        if round_no == 0:
            return self._tf6_take_searches(self._tf6_goal_queries(), 5, post=False)
        has_l0 = bool(self.tf6_commit_candidates())
        unseen = self._tf6_unseen(min_score=3 if has_l0 else 0)
        actions = self._tf6_compares([pid for pid, _s in unseen])
        if not has_l0:
            strong = sum(1 for _pid, score in unseen[:15] if score >= 3)
            limit = 2 if round_no == 1 and strong >= 3 else 4
            actions += self._tf6_take_searches(self._tf6_seed_queries(round_no), limit, post=False)
        return actions

    def make_plan(self) -> Optional[Plan]:
        commits = self.tf6_commit_candidates()
        if not commits:
            return None
        commit = commits[0]
        finals = self.tf6_finals(exclude={commit.key})
        return Plan(commit=commit, finals=finals, preadd=bool(finals))

    def tf6_fallback_plan(self) -> Optional[Plan]:
        """No level-0 key verified: commit the least-relaxed thing anyway so the session ends
        with an order (the commitment gate fails, so this cannot be paid)."""

        ep = self.ep
        rows = []
        for key in ep.known_keys(detailed_only=True):
            if key in ep.excluded or ep.in_stock(key) is not True:
                continue
            level = self.tf6_level(key)
            rows.append((9 if level is None else level, ep.price(key) or 0.0, key))
        if not rows:
            return None
        rows.sort()
        pid, sku = split_key(rows[0][2])
        commit = Candidate(pid=pid, sku=sku)
        finals = self.tf6_finals(exclude={commit.key})
        return Plan(commit=commit, finals=finals, preadd=bool(finals))

    def commit_group(self, plan: Plan) -> list:
        ep = self.ep
        self._tf6_snapshot_base()
        commit = plan.commit
        group = [
            action("add_to_cart", product_id=commit.pid, sku=commit.sku),
            action("inspect_stock", product_id=commit.pid, sku=commit.sku),
        ]
        finals = [f for f in plan.finals if f.key != commit.key]
        # A second add of ANOTHER product absorbs what a chained rule (first add of a different
        # product after the event), an nth-add trigger or a turn trigger (last cart row) would
        # otherwise do to the replacement. Harmless without such rules: only the order counts.
        second = self._tf6_pick_sacrifice(commit, finals)
        if second is None and plan.preadd and finals:
            second = finals[0]
        if second is not None:
            group += [action("add_to_cart", product_id=second.pid, sku=second.sku),
                      action("inspect_stock", product_id=second.pid, sku=second.sku)]
        for final in finals[:3]:
            if second is None or final.key != second.key:
                group.append(action("inspect_stock", product_id=final.pid, sku=final.sku))
        best = self.tf6_level(finals[0].key) if finals else None
        if best != 0:
            # The stockout drops the committed key from in_stock searches (the filters run before
            # per-listing prioritisation), so the listing's next sibling surfaces -- a second
            # full match (another storage variant) included, which a level-1 order would lose.
            room = min(2 if best == 1 else 3, ep.max_calls - len(group))
            group += self._tf6_take_searches(self._tf6_sibling_queries(commit.key), room, post=True)
        ep.notes.append(f"tf6 commit {commit.key} finals={[f.key for f in finals[:3]]} best_level={best}")
        return group[: ep.max_calls]

    def _tf6_pick_sacrifice(self, commit: Candidate, finals: list) -> Optional[Candidate]:
        """Cheapest in-stock key of another product that is no useful replacement: never one of
        the best finals, never a hit that may be a same-model sibling."""

        ep = self.ep
        keep = {f.key for f in finals[:3]}
        fams = self._tf6_model_families() | {_tf6_sku_family(commit.sku)}
        strong = {pid for pid, _s in self._tf6_unseen(min_score=3)}
        best = None
        for key in ep.known_keys():
            pid, sku = split_key(key)
            if pid == commit.pid or key in keep or key in ep.excluded or pid in strong:
                continue
            if _tf6_sku_family(sku) in fams or ep.in_stock(key) is not True or ep.price(key) is None:
                continue
            level = self.tf6_level(key)
            rank = (level is not None, -(level or 0), ep.price(key) or 0.0, key)
            if best is None or rank < best[0]:
                best = (rank, key)
        if best is None:
            return None
        pid, sku = split_key(best[1])
        return Candidate(pid=pid, sku=sku)

    def tf6_detect_event(self) -> bool:
        """True once the event is known; records a stockout/over-budget of any added key
        (turn- or count-triggered rules hit the last cart item, not the first add)."""

        ep = self.ep
        if ep.event is not None:
            return True
        for (_t, _s, key, ok) in ep.adds:
            if not ok:
                continue
            live = ep.live.get(key, {})
            if live.get("source") == "cart":
                continue  # the add response itself may be a pre-event snapshot
            gone = ep.in_stock(key) is False
            over = ep.budget is not None and (ep.price(key) or 0.0) > ep.budget + 1e-9
            if gone or over:
                ep.event = MarketEvent(
                    kind="stockout" if gone else "price_change", target_key=key, turn=ep.turn,
                    seq=int(live.get("seq") or ep.seq), new_price=ep.price(key), source="re-read",
                    noticed_turn=ep.turn,
                )
                ep.excluded.add(key)
                ep.notes.append(f"tf6: event detected on {key} by re-read")
                return True
        return False

    def finals_after_event(self) -> list:
        return self.tf6_finals()

    def final_ok(self, key: str) -> bool:
        ep = self.ep
        if ep.event is not None and key in {ep.event.target_key, *ep.event.targets}:
            return False
        return self.tf6_orderable(key) and self.tf6_level(key) is not None

    def candidate_ok(self, key: str) -> bool:
        return self.tf6_level(key) is not None

    def candidate_score(self, key: str) -> float:
        level = self.tf6_level(key)
        return -1.0 if level is None else float(3 - level)

    def tf6_evidence_needs(self, cand: Candidate) -> list:
        """Reads the verifier still needs for the replacement: a view/compare at any time and
        a view/compare/inspect_stock after the event."""

        ep = self.ep
        if not ep.detailed(cand.pid):
            return [action("view", product_id=cand.pid)]
        if ep.event is not None and not ep.state_checked_after(cand.key, ep.event.seq):
            return [action("inspect_stock", product_id=cand.pid, sku=cand.sku)]
        return []

    def recovery_actions(self, round_no: int) -> list:
        """One post-event round, or [] once the best replacement cannot be improved."""

        ep = self.ep
        finals = self.finals_after_event()
        best = finals[0] if finals else None
        level = self.tf6_level(best.key) if best else None
        strong = self._tf6_unseen(min_score=3)
        if level == 0 or (level == 1 and (not strong or round_no >= 2)):
            return []
        # Speculative search rounds: few when a same-color model is in hand, more when not.
        if not strong and self._tf6_search_rounds >= (2 if level == 2 else 4):
            return []
        actions: list = list(self.tf6_evidence_needs(best)) if best is not None else []
        if strong or level in (1, 2):
            pool = strong  # only a same-model hit can beat a level-2 replacement
        else:
            pool = self._tf6_unseen(min_score=1) or self._tf6_unseen(min_score=0)
        compares = self._tf6_compares([pid for pid, _s in pool])
        searches: list = []
        if not strong and level != 1:
            room = min(5, ep.max_calls - len(actions) - len(compares))
            searches = self._tf6_take_searches(self._tf6_discovery_queries(level), room, post=True)
            self._tf6_search_rounds += bool(searches)
        if not compares and not searches:
            return []  # nothing new to learn; the engine's final loop does any evidence read
        return actions + compares + searches

    # -- ordering ----------------------------------------------------------------------------
    def justification(self, cand: Candidate) -> Optional[dict]:
        return None

    def order_message(self, cand: Candidate) -> str:
        ep = self.ep
        row = self._tf6_row(cand.key) or {}
        level = self.tf6_level(cand.key)
        title = ep.product(cand.pid).title or cand.pid
        preferred = f"{self.tf6_color} {self.tf6_model}".strip() or "your first choice"
        other = str(row.get("color") or "another color")
        if level == 0:
            why = f"This is the {preferred} you asked for"
        elif level == 1:
            why = f"The {preferred} became unavailable after I added it, so I kept the same model in {other}"
        elif level == 2:
            why = (f"The {preferred} became unavailable and no other color of that model was in stock "
                   f"within budget, so I kept your color on the closest other model")
        else:
            why = (f"The {preferred} became unavailable and nothing closer was in stock within budget, "
                   "so this is the least-relaxed option I verified")
        price = ep.price(cand.key)
        price_text = f" at {fmt_money(price)} {ep.currency}" if price is not None else ""
        budget_text = f" of {fmt_money(ep.budget)} {ep.currency}" if ep.budget is not None else ""
        return (f"{why}. I'm ordering {title} (SKU {cand.sku}){price_text}; I re-checked that it is "
                f"in stock and within your budget{budget_text}.")[:600]

# ========================================================================
# families/tf7_justification.py
# ========================================================================

import re
from typing import Optional


# ---------------------------------------------------------------------------
# Goal parsing (the three generator templates, then a generic fallback)
# ---------------------------------------------------------------------------

_TF7_PHRASE = (
    r"(?P<phrase>4K|QHD \(1440p\)|1080p Full HD|720p HD|\d+(?:\.\d+)?Hz|\d+(?:\.\d+)?-inch)"
)
_TF7_TAIL = (
    r"(?P<cat>[A-Za-z][A-Za-z0-9 &'/-]*?) at or under (?P<budget>\d+(?:\.\d+)?) (?P<cur>[A-Z]{3})"
)
_TF7_TEMPLATES = (
    (0, re.compile(
        rf"^Find me an? (?P<brand>.+?) {_TF7_PHRASE} {_TF7_TAIL}, in stock, and tell me why it's a good pick\."
    )),
    (1, re.compile(
        rf"^I want an? (?P<brand>.+?) {_TF7_PHRASE} {_TF7_TAIL}, and it has to be in stock\. "
        r"Walk me through why the one you pick is right\."
    )),
    (2, re.compile(
        rf"^Can you get me an in-stock (?P<brand>.+?) {_TF7_PHRASE} {_TF7_TAIL}\? "
        r"Give me a reason I can trust for whichever you choose\."
    )),
)
# Any gate phrase a paraphrased goal could use (case-insensitive; 'qHD' is rejected later).
_TF7_ANY_PHRASE = (
    r"(?P<phrase>(?:4K|UHD)(?:\s+(?:UHD|Ultra\s+HD))?(?:\s*\(2160p\))?|Ultra\s+HD|2160p|"
    r"QHD(?:\s*\(1440p\))?|WQHD|1440p|2K(?:\s+QHD)?|"
    r"1080p(?:\s+Full\s+HD)?|Full\s+HD(?:\s*\(1080p\))?|FHD|"
    r"720p(?:\s+HD)?|HD(?:\s*\(720p\))?|"
    r"\d{3,5}\s*[x×]\s*\d{3,5}|"
    r"\d+(?:\.\d+)?\s*-?\s*Hz|"
    r"\d+(?:\.\d+)?\s*-?\s*(?:inch(?:es)?|in\b|\"|”|''))"
)
_TF7_PRICE_WORDS = (
    r"(?:at\s+or\s+under|at\s+or\s+below|under|below|for\s+(?:no\s+more\s+than|at\s+most|up\s+to)|"
    r"up\s+to|within|no\s+more\s+than|at\s+most|max(?:imum)?(?:\s+of)?|costing|priced|for|that|"
    r"which|in\s+stock|with|,|\?)"
)
_TF7_GENERIC_RE = re.compile(
    rf"(?:\b(?:an?|any|some|the|in-stock|in\s+stock)|,)\s+(?P<brand>[^,.?!]+?)\s+{_TF7_ANY_PHRASE}\s+"
    rf"(?P<cat>[A-Za-z][A-Za-z0-9 &'/-]*?)\s*{_TF7_PRICE_WORDS}",
    re.I,
)
_TF7_BUDGET_RE = re.compile(
    r"(?:at\s+or\s+under|at\s+or\s+below|under|below|no\s+more\s+than|up\s+to|at\s+most|"
    r"max(?:imum)?(?:\s+of)?|within|budget(?:\s+of|\s+is)?|spend)\s*(?:PHP|₱)?\s*"
    r"([0-9][0-9,]*(?:\.[0-9]+)?)\s*([A-Z]{3})?",
    re.I,
)
_TF7_LEADING_NOISE = re.compile(
    r"^(?:(?:an?|any|some|the|in-stock|in\s+stock|new|brand-new|best|good|great|nice|decent|cheap|"
    r"cheaper|affordable|reliable|quality|solid|budget|genuine|original|single|one)\s+)+",
    re.I,
)
_TF7_SMARTPHONE_RULE = "For a smartphone, the title or raw phone/device type"
_TF7_BUDGET_CUT_RE = re.compile(
    r"(?:only\s+go\s+up\s+to|go\s+up\s+to|up\s+to|at\s+most|at\s+or\s+under|no\s+more\s+than|"
    r"budget\s+(?:is\s+)?(?:now\s+)?|max(?:imum)?\s+(?:of\s+)?|cap\s+(?:is\s+|of\s+)?)"
    r"\s*(?:PHP|₱)?\s*([0-9][0-9,]*(?:\.[0-9]+)?)",
    re.I,
)

# ---------------------------------------------------------------------------
# Claim rules (ports of oro_env_runtime.families.justification)
# ---------------------------------------------------------------------------

_TF7_FACT_LABEL = {"resolution": "display", "refresh_rate": "refresh_rate", "screen_size": "size"}
_TF7_VALUE_SETS = {"resolution": resolution_values, "screen_size": inch_values, "refresh_rate": hz_values}
_TF7_TRUTHY = {"true", "yes", "y", "in stock", "available", "available now"}
_TF7_FALSY = {"false", "no", "n", "out of stock", "unavailable"}
_TF7_FIELD_ALIASES = {
    "availability": "in_stock", "current_price": "price", "hz": "refresh_rate",
    "microphones": "microphone", "privacy": "privacy_cover", "privacy_shutter": "privacy_cover",
    "refresh": "refresh_rate", "refresh_rate_hz": "refresh_rate", "screen": "screen_size",
    "screensize": "screen_size", "size": "screen_size", "stock": "in_stock",
    "streaming_support": "streaming",
}
_TF7_SOFT_PATTERNS = {
    "hdr": r"\b(hdr|high dynamic range)\b",
    "microphone": r"\b(?:mic|microphone)\b",
    "streaming": r"\b(streaming|conference|conferencing|zoom|teams)\b|\bvideo[- ]?call(?:ing|s)?\b",
    "autofocus": r"\bauto[- ]?focus\b",
    "privacy_cover": r"\bprivacy (?:cover|shutter)\b",
}
_TF7_NEG_BEFORE = re.compile(
    r"\b(?:no|without|lack(?:s|ing)?|missing|exclude[ds]?|unsupported|not|"
    r"cannot|can['’]t|doesn['’]t|optional)\b(?:[\s-]+[\w'’]+){0,5}[\s-]*$",
    re.I,
)
_TF7_NEG_AFTER = re.compile(
    r"\s*(?:(?:support|feature|function|mode|capability)\s*)?[:=]?\s*"
    r"(?:(?:is|are|was|were)\s+)?"
    r"(?:not|no|false|none|unsupported|absent|unavailable|missing|excluded|disabled|optional|0)\b|"
    r"^\s*[- ]free\b|^\s+sold\s+separately\b",
    re.I,
)
_TF7_GATE_WORDS = {
    "resolution": {"hd": "720p HD", "fhd": "1080p Full HD", "qhd": "QHD (1440p)", "4k": "4K"},
}
_TF7_RES_QUERIES = {
    "hd": ["720p HD", "HD 1280x720", "1366x768 HD", "720p"],
    "fhd": ["1080p Full HD", "Full HD", "FHD 1920x1080", "1080p"],
    "qhd": ["QHD 1440p", "2K QHD", "2560x1440", "1440p"],
    "4k": ["4K UHD", "UHD 2160p", "3840x2160", "4K"],
}

# ---------------------------------------------------------------------------
# Title heuristics for choosing what to compare (search rows have no facts)
# ---------------------------------------------------------------------------

_TF7_BAD_TITLE = ("customer rating", "customer review", "compare ", "refurb", "pre-owned",
                  "restored", "renewed")
_TF7_ACCESSORY_RE = re.compile(
    r"\b(?:case|cases|cover|covers|protector|tempered|screen\s+film|charger|cable|holder|"
    r"strap|pouch|skin|stand|mount|arm|bracket|adapter|replacement|sticker|bumper|sleeve|"
    r"stylus|keyboard\s+case|wall\s+mount)\b",
    re.I,
)
_TF7_PHONE_CONFLICT_RE = re.compile(
    r"\b(?:tablets?|feature\s*phones?|basic\s*phones?|(?:mystery|blind|lucky)\s*box(?:es)?|"
    r"accessor(?:y|ies)|screen\s*protectors?|phone\s*cases?|case\s*(?:cover\s*)?for|"
    r"replacement\s*(?:screen|battery)|smart\s*watch(?:es)?|earbuds?|headphones?)\b",
    re.I,
)
_TF7_HIGH_HZ_RE = re.compile(r"(\d{2,3}(?:\.\d+)?)\s*-?\s*hz", re.I)
# Common listing-title words per category: extra searches reach listings that BM25 ranks
# below a crowd of near-identical titles (each search/filter returns at most 10 rows).
_TF7_VOCAB = {
    "monitor": ("office", "IPS", "LED", "curved", "gaming", "HDR", "frameless", "display", "FHD",
                "QHD", "4K", "75Hz", "165Hz", "USB-C", "speakers", "ultrawide", "portable",
                "business", "eye care", "computer", "screen"),
    "tablet": ("Android", "WiFi", "kids", "pad", "tab", "64GB", "128GB", "octa core", "LTE",
               "keyboard", "pro", "lite", "display", "4G", "10 inch", "8 inch"),
    "phone": ("5G", "4G", "Android", "dual SIM", "unlocked", "128GB", "64GB", "256GB", "pro",
              "lite", "plus", "note", "mobile", "cell phone", "smartphone"),
    "": ("new", "pro", "lite", "plus", "max", "mini", "series", "display", "portable", "2024"),
}


def _tf7_norm(text) -> str:
    return " ".join(re.findall(r"[a-z0-9]+", str(text or "").casefold()))


def _tf7_clean_query(text: str) -> str:
    return " ".join(str(text or "").split())[:150]


def _tf7_category_from_word(cat_word: str) -> str:
    words = [w for w in cat_word.split() if w]
    title = " ".join(w[:1].upper() + w[1:] for w in words)
    return title if title.lower().endswith("s") else title + "s"


def _tf7_gate_from_phrase(phrase: str) -> Optional[tuple]:
    """(attr, canonical value) of a gate phrase, in the scorer's canonical form."""

    text = " ".join(str(phrase or "").split())
    if not text:
        return None
    if re.search(r"hz\b", text, re.I):
        value = norm_attr_claim_value("refresh_rate", text)
        return ("refresh_rate", value) if value else None
    if re.search(r"\d\s*-?\s*(?:inch|in\b|\"|”|'')", text, re.I):
        value = norm_attr_claim_value("screen_size", text.replace("''", '"'))
        return ("screen_size", value) if value else None
    if re.search(r"\bqHD\b", text):  # quarter HD, never a gate value
        return None
    value = normalize_resolution(text)
    if value is None and re.fullmatch(r"(?i)wqhd", text):
        value = "qhd"
    return ("resolution", value) if value else None


def _tf7_phrase_for(attr: str, value: str) -> str:
    if attr == "resolution":
        return _TF7_GATE_WORDS["resolution"].get(value, value.upper())
    if attr == "refresh_rate":
        return f"{value[:-2]}Hz"
    if attr == "screen_size":
        return f"{value[:-2]}-inch"
    return value


def _tf7_parse_goal(goal: str) -> Optional[dict]:
    """Brand / gate / category / budget / currency from the goal text, or None."""

    goal = " ".join(str(goal or "").split("\n\nTask rules:", 1)[0].split())
    smartphone = _TF7_SMARTPHONE_RULE in goal
    for template_id, pattern in _TF7_TEMPLATES:
        match = pattern.match(goal)
        if not match:
            continue
        gate = _tf7_gate_from_phrase(match.group("phrase"))
        if gate is None:
            continue
        cat_word = match.group("cat").strip()
        return {
            "template_id": template_id,
            "brand": match.group("brand").strip(),
            "attr": gate[0],
            "gate": gate[1],
            "phrase": match.group("phrase"),
            "cat_word": cat_word,
            "category": _tf7_category_from_word(cat_word),
            "budget": float(match.group("budget")),
            "currency": match.group("cur"),
            "smartphone": smartphone,
        }
    # Generic fallback: '<article> <Brand> <gate phrase> <category word> <price words>'.
    out: dict = {"template_id": None, "smartphone": smartphone}
    for match in _TF7_GENERIC_RE.finditer(goal):
        gate = _tf7_gate_from_phrase(match.group("phrase"))
        if gate is None:
            continue
        brand = _TF7_LEADING_NOISE.sub("", match.group("brand").strip()).strip()
        cat_word = match.group("cat").strip().lower()
        if not brand or len(brand.split()) > 5 or not cat_word:
            continue
        out.update({"brand": brand, "attr": gate[0], "gate": gate[1], "phrase": match.group("phrase"),
                    "cat_word": cat_word, "category": _tf7_category_from_word(cat_word)})
        break
    if "attr" not in out:
        spec = parse_gated_spec(goal)
        if spec and spec[0] in _TF7_FACT_LABEL:
            out.update({"attr": spec[0], "gate": spec[1], "phrase": _tf7_phrase_for(*spec)})
    if "category" not in out:
        word = parse_category_word(goal)
        if word:
            out.update({"category": word, "cat_word": word.lower().rstrip("s")})
    budget_match = _TF7_BUDGET_RE.search(goal)
    if budget_match:
        out["budget"] = parse_money(budget_match.group(1))
        if budget_match.group(2) and budget_match.group(2).isupper():
            out["currency"] = budget_match.group(2)
    else:
        out["budget"] = parse_budget(goal)
    if not out.get("currency"):
        currency = re.search(r"\b[0-9][0-9,]*(?:\.[0-9]+)?\s*([A-Z]{3})\b", goal)
        if currency:
            out["currency"] = currency.group(1)
    if out.get("attr") and out.get("budget"):
        return out
    return out if out.get("attr") or out.get("budget") else None


def _tf7_llm_goal(goal: str) -> Optional[dict]:
    """Optional LLM fallback for an unknown goal phrasing (never needed for the templates)."""

    reply = llm_json(
        "Extract the shopping request fields.",
        "Goal: " + goal[:1200] + "\nReturn JSON {\"brand\": str|null, \"gate_attr\": one of "
        "resolution|refresh_rate|screen_size, \"gate_value\": canonical like 4k|qhd|fhd|hd|144hz|27in, "
        "\"category\": plural category like Monitors, \"budget\": number, \"currency\": 3 letters}.",
        max_tokens=200,
    )
    if not isinstance(reply, dict):
        return None
    attr = str(reply.get("gate_attr") or "").strip().lower()
    value = reply.get("gate_value")
    if attr not in _TF7_FACT_LABEL or not value:
        return None
    canonical = norm_attr_claim_value(attr, str(value))
    if canonical is None:
        return None
    out = {"attr": attr, "gate": canonical, "phrase": _tf7_phrase_for(attr, canonical)}
    if reply.get("brand"):
        out["brand"] = str(reply["brand"]).strip()
    if reply.get("category"):
        out["category"] = str(reply["category"]).strip()
        out["cat_word"] = out["category"].lower()[:-1] if out["category"].lower().endswith("s") \
            else out["category"].lower()
    budget = parse_money(reply.get("budget"))
    if budget:
        out["budget"] = budget
    if reply.get("currency") and re.fullmatch(r"[A-Za-z]{3}", str(reply["currency"])):
        out["currency"] = str(reply["currency"]).upper()
    return out


# ---------------------------------------------------------------------------
# Claim helpers
# ---------------------------------------------------------------------------


def _tf7_claim_field(field) -> str:
    name = _tf7_norm(field).replace(" ", "_")
    return _TF7_FIELD_ALIASES.get(name, name)


def _tf7_bool_value(value) -> Optional[bool]:
    norm = _tf7_norm(value)
    if norm in _TF7_TRUTHY:
        return True
    if norm in _TF7_FALSY:
        return False
    return None


def _tf7_price_claim_ok(value: str, price: float, currency: str) -> bool:
    amount, cur = r"(\d+(?:\.\d+)?)", r"(?:\s+([A-Za-z]{3}))?"
    strict = re.fullmatch(rf"\s*(?:under|below)\s+{amount}{cur}\s*", value, re.I)
    inclusive = re.fullmatch(rf"\s*(?:at\s+most|<=|≤)\s*{amount}{cur}\s*", value, re.I)
    exact = re.fullmatch(rf"\s*{amount}{cur}\s*", value, re.I)
    match = strict or inclusive or exact
    if match is None or (match.group(2) and match.group(2).casefold() != str(currency).casefold()):
        return False
    price_cents, claimed = round(price * 100), round(float(match.group(1)) * 100)
    if strict is not None:
        return price_cents < claimed
    if inclusive is not None:
        return price_cents <= claimed
    return price_cents == claimed


def _tf7_price_text(price: float) -> str:
    """The exact price as the scorer compares it (integer cents, no separators)."""

    cents = int(round(float(price) * 100))
    return f"{cents // 100}.{cents % 100:02d}"


def _tf7_soft_supported(row: dict, field: str) -> bool:
    """Port of justification._support_soft_field_source over visible facts + title."""

    pattern = _TF7_SOFT_PATTERNS[field]
    supported = False
    texts = [str(v) for v in (row.get("facts") or {}).values()] + [str(row.get("title") or "")]
    for text in texts:
        for match in re.finditer(pattern, text, re.I):
            before = re.split(r"[.;!?\n]", text[: match.start()])[-1]
            after = re.split(r"[.;!?\n]", text[match.end():])[0]
            if _TF7_NEG_BEFORE.search(before) or _TF7_NEG_AFTER.match(after):
                return False
            supported = True
    return supported


def _tf7_title_values(attr: str, row: dict) -> set:
    title = resolution_title(row) if attr == "resolution" else str(row.get("title") or "")
    return set(_TF7_VALUE_SETS[attr](title))


def _tf7_vocab(cat_word: str, attr: Optional[str], gate: Optional[str]) -> list:
    """Title words for extra searches; words naming another gate value are skipped."""

    low = str(cat_word or "").lower()
    key = next((k for k in ("monitor", "tablet", "phone") if k and k in low), "")
    words = []
    for word in _TF7_VOCAB[key]:
        values = set(_TF7_VALUE_SETS[attr](word)) if attr in _TF7_VALUE_SETS else set()
        if values and values != {gate}:
            continue
        words.append(word)
    return words


def _tf7_gaming_title_ok(title: str) -> bool:
    tokens = set()
    for tok in re.findall(r"[a-z0-9]+", str(title or "").casefold()):
        tokens.add(tok)
        if len(tok) > 3 and tok.endswith("s"):
            tokens.add(tok[:-1])
    high = any(float(m.group(1)) >= 120 for m in _TF7_HIGH_HZ_RE.finditer(str(title or "")))
    return {"gaming", "monitor"} <= tokens or ("monitor" in tokens and high)


# ---------------------------------------------------------------------------
# Engine: one retry when the order call itself was refused
# ---------------------------------------------------------------------------


class _TF7Engine(Engine):
    """The shared protocol plus a single retry of a refused place_test_order.

    The order turn is [message, (add), inspect_cart, place_test_order]. If the environment
    answers the order with an error (e.g. the item was not in the cart after all), the
    episode would end without an order (reward 0); re-add, re-read the cart and order again.
    """

    def _order(self, final: Candidate) -> None:
        super()._order(final)
        ep = self.ep
        if ep.done or ep.turns_left() <= 1 or not ep.log:
            return
        last = ep.log[-1]
        if not any((c or {}).get("name") == "place_test_order" for c in last.get("calls") or []):
            return
        ep.notes.append("tf7 order refused; retrying once")
        group = []
        if not ep.in_cart(final.key):
            group.append(action("add_to_cart", product_id=final.pid, sku=final.sku))
        args: dict = {"product_id": final.pid, "sku": final.sku}
        justification = self.strategy.justification(final)
        if justification is not None:
            args["justification"] = justification
        group += [action("inspect_cart"), {"name": "place_test_order", "args": args}]
        self.env.call(group)


# ---------------------------------------------------------------------------
# Strategy
# ---------------------------------------------------------------------------


@register_strategy
class JustificationStrategy(Strategy):
    family = "justification"
    max_research_rounds = 8
    max_recovery_rounds = 4
    engine_cls = _TF7Engine

    def __init__(self, ep) -> None:
        super().__init__(ep)
        self.tf7: dict = {}
        self._tf7_round = 0
        self._tf7_exhausted = False
        self._tf7_queries_done: set = set()
        self._tf7_compare_requested: set = set()
        self._tf7_detail_keys: set = set()
        self._tf7_eval_cache: dict = {}
        self._tf7_failed_adds: set = set()
        self._tf7_log_index = 0
        self._tf7_msg_index = 0

    # -- parsing ---------------------------------------------------------------
    def parse(self) -> None:
        ep = self.ep
        goal = ep.goal_text
        parsed = _tf7_parse_goal(goal) or {}
        if not (parsed.get("attr") and parsed.get("budget") and parsed.get("brand") and parsed.get("category")):
            extra = _tf7_llm_goal(goal) or {}
            for name, value in extra.items():
                parsed.setdefault(name, value)
        if not parsed.get("attr"):
            # The runtime's own default for a task without attributes.
            parsed.update({"attr": "resolution", "gate": "4k", "phrase": "4K"})
        if not parsed.get("cat_word") and parsed.get("category"):
            low = str(parsed["category"]).lower()
            parsed["cat_word"] = low[:-1] if low.endswith("s") else low
        category = str(parsed.get("category") or "")
        if category and category.casefold().rstrip("s") in ("smartphone", "mobile phone", "cell phone"):
            parsed["smartphone"] = True
        parsed.setdefault("smartphone", False)
        self.tf7 = parsed
        if parsed.get("currency"):
            ep.currency = str(parsed["currency"])
        ep.set_budget(parsed.get("budget") or parse_budget(goal))
        ep.intent.update({
            "brand": parsed.get("brand"), "category": parsed.get("category"),
            "spec": (parsed.get("attr"), parsed.get("gate")), "template": parsed.get("template_id"),
        })
        ep.notes.append(
            f"tf7 goal brand={parsed.get('brand')!r} gate={parsed.get('attr')}={parsed.get('gate')} "
            f"category={parsed.get('category')!r} budget={ep.budget} {ep.currency}"
        )

    def opening_message(self) -> Optional[str]:
        return None  # nothing is hidden; a message would only wake the simulator

    # -- state sync --------------------------------------------------------------
    def _tf7_sync(self) -> None:
        """Fold new observations and shopper lines into the strategy state."""

        ep = self.ep
        for entry in ep.log[self._tf7_log_index:]:
            for act, result in zip(entry.get("calls") or [], entry.get("results") or []):
                name = (act or {}).get("name")
                payload = result.get("observation") if isinstance(result, dict) else None
                if name == "add_to_cart" and (not isinstance(payload, dict) or "error" in payload
                                              or not isinstance(payload.get("added"), dict)):
                    args = (act or {}).get("args") or {}
                    self._tf7_failed_adds.add(cand_key(args.get("product_id"), args.get("sku")))
                if name not in ("view", "compare") or not isinstance(payload, dict):
                    continue
                rows = payload.get("compared") if name == "compare" else [payload]
                for row in rows or []:
                    if not isinstance(row, dict) or not row.get("product_id") or "error" in row:
                        continue
                    for variant in row.get("variants") or []:
                        if isinstance(variant, dict) and variant.get("sku"):
                            self._tf7_detail_keys.add(cand_key(row["product_id"], variant["sku"]))
        self._tf7_log_index = len(ep.log)
        for _turn, text in ep.shopper_messages[self._tf7_msg_index:]:
            for line in [part for part in text.split("\n") if part.strip()] or [text]:
                if not re.search(r"balance|budget|only|now|afford|cap|limit", line, re.I):
                    continue
                for match in _TF7_BUDGET_CUT_RE.finditer(line):
                    value = parse_money(match.group(1))
                    if value is not None and ep.budget is not None and 0 < value < ep.budget - 1e-9:
                        ep.notes.append(f"tf7 budget {ep.budget} -> {value}")
                        ep.budget = value
        self._tf7_msg_index = len(ep.shopper_messages)
        self._tf7_infer_brand()
        self._tf7_quiet_event_fallback()

    def _tf7_infer_brand(self) -> None:
        """No brand parsed: adopt a listing brand (from search rows) that the goal names.

        Only brands whose every token occurs in the goal, and that the goal writes
        capitalized, qualify; the shortest such brand wins ('Zentrix' over 'Zentrix Display').
        """

        g = self.tf7
        ep = self.ep
        if g.get("brand") or g.get("_brand_checked_at") == len(ep.searches) or not ep.searches:
            return
        g["_brand_checked_at"] = len(ep.searches)
        goal = ep.goal_text
        goal_tokens = set(re.findall(r"[a-z0-9]+", goal.casefold()))
        capitalized = {w.casefold() for w in re.findall(r"\b[A-Z][A-Za-z0-9&'-]*", goal)}
        generic = set(re.findall(r"[a-z0-9]+", f"{g.get('cat_word') or ''} {g.get('phrase') or ''}".casefold()))
        found = []
        for product in ep.products.values():
            brand = str(product.brand or "").strip()
            tokens = set(re.findall(r"[a-z0-9]+", brand.casefold()))
            if not tokens or not tokens <= goal_tokens or tokens <= generic:
                continue
            if not any(tok in capitalized for tok in tokens - generic):
                continue
            found.append(brand)
        if found:
            brand = min(found, key=lambda b: (len(_tf7_norm(b).split()), len(b), b))
            g["brand"] = brand
            self._tf7_eval_cache.clear()
            ep.intent["brand"] = brand
            ep.notes.append(f"tf7 brand inferred from listings: {brand!r}")

    def _tf7_quiet_event_fallback(self) -> None:
        """A re-read of the first add that shows another price (or no stock) is the event.

        The core spots a quiet event by price > budget; this also covers a mis-parsed budget.
        Only reads the verifier accepts as notice count (inspect_stock, view, search/filter
        rows); a cart or compare row must not mark the event as noticed, or the order could
        land without real notice evidence (sacrificial exploit). Without this, the engine
        runs its own inspect_stock re-read turn first.
        """

        ep = self.ep
        if ep.event is not None or ep.first_add is None:
            return
        key = ep.first_add.key
        first_seq = min((seq for (_t, seq, k, ok) in ep.adds if ok), default=None)
        live = ep.live.get(key, {})
        if first_seq is None or live.get("seq", 0) <= first_seq:
            return
        if live.get("source") not in ("inspect_stock", "view", "search"):
            return
        at_add, now = live.get("price_at_add", live.get("first_add_price")), live.get("price")
        changed = live.get("in_stock") is False or (
            at_add is not None and now is not None and abs(float(now) - float(at_add)) > 0.005)
        if not changed:
            return
        ep.event = MarketEvent(
            kind="stockout" if live.get("in_stock") is False else "price_change", target_key=key,
            turn=ep.first_add_turn or ep.turn, seq=first_seq, new_price=now, source="tf7-reread",
            noticed_turn=ep.turn,
        )
        ep.excluded.add(key)
        ep.notes.append(f"tf7 event spotted on re-read of {key}")

    # -- candidate evaluation -----------------------------------------------------
    def _tf7_category_ok(self, row: dict) -> bool:
        g = self.tf7
        forms = [c for c in (g.get("category"), g.get("cat_word")) if c]
        if not forms:
            return is_actual_item(row, None)
        return any(is_actual_item(row, form) for form in forms)

    def _tf7_eval(self, key: str) -> Optional[dict]:
        """Every visible gold check of one SKU that does not depend on price or stock."""

        if key in self._tf7_eval_cache:
            return self._tf7_eval_cache[key]
        if key not in self._tf7_detail_keys:
            return None
        ep = self.ep
        g = self.tf7
        pid, sku = split_key(key)
        row = ep.view_row(pid)
        variant = next((v for v in row["variants"] if str(v.get("sku")) == sku), None)
        if variant is None:
            return None
        options = variant.get("options")
        attr, gate = g.get("attr"), g.get("gate")
        reasons = []
        currency = variant.get("currency")
        if g.get("currency") and currency and str(currency) != str(g["currency"]):
            reasons.append("currency")
        if g.get("brand") and not brand_matches(g["brand"], row.get("brand")):
            reasons.append("brand")
        if not self._tf7_category_ok(row):
            reasons.append("category_or_condition")
        fact = fact_attr_value(row, attr)
        canonical = resolve_attribute_visible(row, attr)
        per_sku = resolve_variant_attribute_visible(row, options, attr)
        if fact != gate:
            reasons.append(f"fact:{fact}")
        if canonical != gate:
            reasons.append(f"canonical:{canonical}")
        if per_sku != gate:
            reasons.append(f"options:{per_sku}")
        if g.get("smartphone") and not smartphone_supported(row, options):
            reasons.append("smartphone_evidence")
        if not re.search(r"[a-z0-9]", str(row.get("brand") or ""), re.I) and not any(
                _tf7_soft_supported(row, f) for f in _TF7_SOFT_PATTERNS):
            reasons.append("no_soft_claim")
        out = {
            "key": key, "pid": pid, "sku": sku, "ok": not reasons, "reasons": reasons,
            "rank": self._tf7_rank(row) if not reasons else (9, 9, 9),
            "title": str(row.get("title") or ""),
        }
        self._tf7_eval_cache[key] = out
        return out

    def _tf7_rank(self, row: dict) -> tuple:
        """Hidden-key reliability, lower is better.

        (title states exactly the gate value, fact group has a single part, fact is numeric).
        The canonical value also reads raw keys view never shows (resolution: 'screen/native
        resolution'; display/refresh groups keep 2 values), so corroboration lowers the risk.
        """

        attr, gate = self.tf7.get("attr"), self.tf7.get("gate")
        facts = row.get("facts") or {}
        fact_text = str(facts.get(_TF7_FACT_LABEL[attr]) or "")
        numeric = re.search(
            r"\d{3,5}\s*[x×]\s*\d{3,5}|\b\d{3,4}p\b|\d+(?:\.\d+)?\s*(?:-?\s*inch|in\b|\"|”|-?\s*hz)",
            fact_text, re.I)
        return (
            0 if _tf7_title_values(attr, row) == {gate} else 1,
            1 if "; " in fact_text else 0,
            0 if numeric else 1,
        )

    def _tf7_rows(self, cap: Optional[float]) -> list:
        """Eligible, in-stock, not excluded SKUs priced at or under ``cap``."""

        ep = self.ep
        out = []
        for key in sorted(self._tf7_detail_keys):
            ev = self._tf7_eval(key)
            if not ev or not ev["ok"]:
                continue
            if key in ep.excluded or key in self._tf7_failed_adds or ep.in_stock(key) is not True:
                continue
            price = ep.price(key)
            if price is None or (cap is not None and float(price) > cap + 1e-9):
                continue
            out.append({**ev, "price": float(price)})
        return out

    def candidate_ok(self, key: str) -> bool:
        self._tf7_sync()
        ev = self._tf7_eval(key)
        return bool(ev and ev["ok"])

    def candidate_score(self, key: str) -> float:
        ev = self._tf7_eval(key) or {}
        rank = ev.get("rank") or (9, 9, 9)
        return -(rank[0] * 4 + rank[1] * 2 + rank[2]) * 1e9 - (self.ep.price(key) or 0.0)

    def final_ok(self, key: str) -> bool:
        ep = self.ep
        if key in self._tf7_failed_adds:
            return False
        if ep.event is not None and ep.first_add is not None and key == ep.first_add.key:
            return False
        return ep.orderable(key) and self.candidate_ok(key)

    # -- research --------------------------------------------------------------------
    def research_actions(self, round_no: int) -> list:
        self._tf7_sync()
        self._tf7_round = round_no
        ep = self.ep
        orig = ep.original_budget
        # The commitment may cost up to the original budget, but after a budget cut the
        # final must fit the new cap: search under the cut until a final is known.
        cut = ep.budget is not None and orig is not None and ep.budget < orig - 1e-9
        search_cap = ep.budget if cut and not self._tf7_rows(ep.budget) else orig
        if round_no == 0:
            acts = self._tf7_discovery(max_searches=5, max_compares=0, cap=search_cap,
                                       queue_cap=orig, max_filters=3)
        else:
            thin = len(self._tf7_compare_queue(orig)) <= 5 * 3
            acts = self._tf7_discovery(max_searches=4 if thin or cut else 1, max_compares=3,
                                       cap=search_cap, queue_cap=orig, max_filters=2 if thin else 0)
        if not acts or round_no >= self.max_research_rounds - 1:
            self._tf7_exhausted = True
        return acts

    def recovery_actions(self, round_no: int) -> list:
        self._tf7_sync()
        return self._tf7_discovery(max_searches=4, max_compares=3, cap=self.ep.budget, max_filters=2)

    def _tf7_discovery(self, *, max_searches: int, max_compares: int, cap: Optional[float],
                       queue_cap: Optional[float] = None, max_filters: int = 0,
                       max_calls: int = 10) -> list:
        """compare() the best unseen hits, then new searches/filters (one call group).

        ``cap`` is the max_price of new searches; ``queue_cap`` (default ``cap``) bounds which
        unseen hits are worth a compare. Within the validator's per-group limits: <= 3
        compares of 5 ids, <= 5 searches, <= 10 calls.
        """

        acts: list = []
        pids = self._tf7_compare_queue(cap if queue_cap is None else queue_cap)
        pids = pids[: min(3, max(0, max_compares)) * 5]
        for i in range(0, len(pids), 5):
            chunk = pids[i:i + 5]
            self._tf7_compare_requested.update(chunk)
            acts.append(action("compare", product_ids=chunk))
        searches = n_filters = 0
        max_searches = min(max_searches, 5)
        for act in self._tf7_query_plan(cap):
            if len(acts) >= max_calls or (searches >= max_searches and n_filters >= max_filters):
                break
            is_search = act["name"] == "search"
            if (is_search and searches >= max_searches) or (not is_search and n_filters >= max_filters):
                continue
            sig = (act["name"], tuple(sorted((k, str(v)) for k, v in act["args"].items())))
            if sig in self._tf7_queries_done:
                continue
            self._tf7_queries_done.add(sig)
            acts.append(act)
            if is_search:
                searches += 1
            else:
                n_filters += 1
        return acts[:max_calls]

    def _tf7_query_plan(self, cap: Optional[float]):
        """Searches/filters in priority order (lazily; already-run ones are skipped).

        BM25 search and filter both return at most 10 rows, so breadth comes from diversity:
        gate phrasings, titles of verified items (siblings and near-duplicates are often gold
        too), common title words of the category, and price bands under the cap (a filter
        is sorted by product_id, so a lower cap reaches a different slice).
        """

        g = self.tf7
        brand = str(g.get("brand") or "")
        cat = str(g.get("cat_word") or "")
        attr, gate = g.get("attr"), g.get("gate")
        phrase = str(g.get("phrase") or _tf7_phrase_for(attr, gate))
        if attr == "resolution":
            alts = list(_TF7_RES_QUERIES.get(gate, [phrase]))
        elif attr == "screen_size":
            n = gate[:-2]
            alts = [f"{n} inch", f"{n}in", f'{n}"', f"{n} inches"]
        else:
            n = gate[:-2]
            alts = [f"{n}Hz", f"{n} Hz", f"{n}hz refresh", f"{n}Hz high refresh"]
        rounded = round(cap, 2) if cap else None

        def search(text: str, price_cap: Optional[float] = rounded) -> dict:
            return action("search", query=_tf7_clean_query(text), k=10, in_stock=True,
                          max_price=price_cap)

        def filt(category: Optional[str], price_cap: Optional[float] = rounded) -> dict:
            return action("filter", category=category, brand=brand or None,
                          max_price=price_cap, in_stock=True, k=10)

        category = str(g.get("category") or "")
        low_cat = category.casefold()
        if low_cat in ("gaming monitors", "gaming monitor"):
            filter_cats = ["Monitors", "Computer Monitors"]
        elif category:
            filter_cats = [category]
        else:
            filter_cats = []
        bands = [round(cap * f, 2) for f in (0.8, 0.6, 0.45, 0.3)] if cap else []
        # 1. core queries (turn 1)
        yield search(f"{brand} {phrase} {cat}")
        yield search(f"{brand} {cat}")
        yield search(f"{brand} {alts[0]} {cat}")
        yield search(f"{brand} {alts[1]} {cat}")
        yield search(f"{brand} {phrase}")
        for c in filter_cats:
            yield filt(c)
        yield filt(None)
        # 2. near-duplicates of what already verified as gold
        for row in sorted(self._tf7_rows(cap), key=lambda r: (r["rank"], r["price"]))[:4]:
            title = re.sub(re.escape(brand), " ", row["title"], flags=re.I) if brand else row["title"]
            yield search(f"{brand} {' '.join(title.split()[:8])}")
        # 3. alternative phrasings and a cheaper slice
        yield search(f"{brand} {alts[2]} {cat}")
        yield search(f"{phrase} {cat} {brand}")
        if bands:
            yield search(f"{brand} {cat}", bands[1])
            yield search(f"{brand} {phrase} {cat}", bands[1])
        yield search(f"{brand} {alts[3]} {cat}")
        if "gaming" in low_cat:
            yield search(f"{brand} {phrase} monitor")
            yield search(f"{brand} gaming monitor 144Hz")
        for band in bands:
            for c in filter_cats:
                yield filt(c, band)
            yield filt(None, band)
        # 4. common title words of the category, then price bands of the core queries
        last = cat.split()[-1] if cat.split() else ""
        for word in _tf7_vocab(cat, attr, gate):
            yield search(f"{brand} {word} {last}")
        for band in bands:
            yield search(f"{brand} {cat}", band)
            yield search(f"{brand} {phrase} {cat}", band)
            yield search(f"{brand} {alts[0]} {cat}", band)
        yield search(f"{brand} {alts[0]}")
        yield search(f"{cat} {phrase}")
        yield search(brand)

    def _tf7_compare_queue(self, cap: Optional[float]) -> list:
        """Unseen products from search/filter results, most promising first."""

        ep = self.ep
        order: list = []
        hits: dict = {}
        for (_turn, _name, _args, keys) in ep.searches:
            for key in keys:
                pid, _sku = split_key(key)
                hits[pid] = hits.get(pid, 0) + 1
                if pid not in order:
                    order.append(pid)
        scored = []
        for rank, pid in enumerate(order):
            if ep.product(pid).detailed or pid in self._tf7_compare_requested:
                continue
            score = self._tf7_summary_score(pid, cap)
            if score is None:
                continue
            scored.append((-(score + min(hits.get(pid, 1), 3) * 0.25), rank, pid))
        scored.sort()
        return [pid for _s, _r, pid in scored]

    def _tf7_min_price(self, pid: str) -> float:
        ep = self.ep
        prices = [ep.price(cand_key(pid, sku)) for sku in ep.product(pid).variants]
        prices = [float(p) for p in prices if p is not None]
        return min(prices) if prices else float("inf")

    def _tf7_summary_score(self, pid: str, cap: Optional[float]) -> Optional[float]:
        """Priority of an unseen product from its search row; None = cannot be gold."""

        ep = self.ep
        g = self.tf7
        product = ep.product(pid)
        title = str(product.title or "")
        low = title.casefold()
        if not title.strip() or any(tok in low for tok in _TF7_BAD_TITLE):
            return None
        if g.get("brand") and product.brand is not None and not brand_matches(g["brand"], product.brand):
            return None
        keys = [cand_key(pid, sku) for sku in product.variants]
        if keys and all(ep.in_stock(k) is False or k in ep.excluded for k in keys):
            return None
        prices = [ep.price(k) for k in keys if ep.price(k) is not None]
        limit = cap if cap is not None else ep.original_budget
        if prices and limit is not None and min(prices) > limit + 1e-9:
            return None
        category = str(g.get("category") or "").casefold()
        if category in ("gaming monitors", "gaming monitor") and not _tf7_gaming_title_ok(title):
            return None
        if g.get("smartphone") and _TF7_PHONE_CONFLICT_RE.search(title):
            return None
        attr, gate = g.get("attr"), g.get("gate")
        values = set(_TF7_VALUE_SETS[attr](title))
        score = 0.0
        if values == {gate}:
            score += 4.0
        elif values:
            if attr != "resolution":
                return None  # a second size/rate in the title makes the canonical value None
            score -= 5.0
        if _TF7_ACCESSORY_RE.search(title):
            score -= 3.0
        cat_word = str(g.get("cat_word") or "")
        if cat_word and all(tok in low for tok in cat_word.lower().split()[-1:]):
            score += 1.0
        if product.brand is None:
            score -= 1.0
        orig = ep.original_budget
        if (prices and ep.budget is not None and orig is not None and ep.budget < orig - 1e-9
                and min(prices) <= ep.budget + 1e-9):
            score += 1.5  # after a budget cut, possible finals come first
        return score

    # -- planning ---------------------------------------------------------------------
    def make_plan(self) -> Optional[Plan]:
        self._tf7_sync()
        ep = self.ep
        rows = self._tf7_rows(ep.original_budget)
        if not rows:
            return None
        now_rows = [r for r in rows if ep.budget is not None and r["price"] <= ep.budget + 1e-9]
        pids = {r["pid"] for r in rows}
        best = {r["pid"] for r in rows if r["rank"] == (0, 0, 0)}
        best_now = {r["pid"] for r in now_rows if r["rank"] == (0, 0, 0)}
        pending = [pid for pid in self._tf7_compare_queue(ep.original_budget)
                   if (self._tf7_summary_score(pid, ep.original_budget) or 0.0) >= 4.0]
        if ep.budget is not None and ep.original_budget is not None and ep.budget < ep.original_budget:
            # after a cut only possible finals are worth waiting for
            pending = [pid for pid in pending if self._tf7_min_price(pid) <= ep.budget + 1e-9]
        lenient = self._tf7_exhausted or ep.time_left() < 90.0 or ep.turns_left() <= 12
        two = len(pids) >= 2 and bool(now_rows)
        ready = (
            (two and len(best) >= 2 and bool(best_now))
            or (two and (not pending or self._tf7_round >= 2))
            or (lenient and bool(rows))
        )
        if not ready:
            return None
        return self._tf7_select(rows, now_rows)

    def _tf7_select(self, rows: list, now_rows: list) -> Optional[Plan]:
        """B = most reliable, cheapest final; A = most reliable other pick, priciest first."""

        ep = self.ep
        b_row = min(now_rows, key=lambda r: (r["rank"], r["price"], r["key"])) if now_rows else None
        others = [r for r in rows if b_row is None or r["pid"] != b_row["pid"]]
        if not others:
            others = [r for r in rows if b_row is None or r["key"] != b_row["key"]]
        if others:
            a_row = min(others, key=lambda r: (r["rank"], -r["price"], r["key"]))
        else:
            a_row, b_row = b_row, None
        if a_row is None:
            return None
        finals_rows = [b_row] if b_row else []
        rest = [r for r in now_rows if r["key"] not in {a_row["key"], *(x["key"] for x in finals_rows)}]
        rest.sort(key=lambda r: (r["pid"] == a_row["pid"], r["rank"], r["price"], r["key"]))
        finals_rows += rest
        commit = Candidate(pid=a_row["pid"], sku=a_row["sku"], reason="commit")
        finals = [Candidate(pid=r["pid"], sku=r["sku"]) for r in finals_rows]
        ep.notes.append(
            f"tf7 plan A={commit.key} rank={a_row['rank']} B={finals[0].key if finals else None} "
            f"rank={b_row['rank'] if b_row else None} eligible={len(rows)} budget={ep.budget}"
        )
        return Plan(commit=commit, finals=finals, preadd=True)

    def commit_group(self, plan: Plan) -> list:
        """[add A, inspect A, add B, inspect B, inspect C..]: the event lands on A only."""

        ep = self.ep
        commit = plan.commit
        group = [
            action("add_to_cart", product_id=commit.pid, sku=commit.sku),
            action("inspect_stock", product_id=commit.pid, sku=commit.sku),
        ]
        finals = [f for f in plan.finals if f.key != commit.key]
        if finals:
            group.append(action("add_to_cart", product_id=finals[0].pid, sku=finals[0].sku))
            group.append(action("inspect_stock", product_id=finals[0].pid, sku=finals[0].sku))
            for final in finals[1:6]:
                group.append(action("inspect_stock", product_id=final.pid, sku=final.sku))
        else:
            # A single verified pick: keep discovering in the commit turn (compares made
            # after the event also count as the final's post-event state read).
            group += self._tf7_discovery(max_searches=4, max_compares=1, cap=ep.budget, max_filters=2,
                                         max_calls=min(ep.max_calls, 10) - len(group))
        return group[: min(ep.max_calls, 10)]

    # -- after the event ------------------------------------------------------------
    def finals_after_event(self) -> list:
        self._tf7_sync()
        ep = self.ep
        rows = [r for r in self._tf7_rows(ep.budget) if self.final_ok(r["key"])]
        first = ep.first_add.key if ep.first_add is not None else None
        rows.sort(key=lambda r: (r["key"] == first, r["rank"], not ep.in_cart(r["key"]),
                                 r["price"], r["key"]))
        return [Candidate(pid=r["pid"], sku=r["sku"]) for r in rows]

    # -- ordering ---------------------------------------------------------------------
    def justification(self, cand: Candidate) -> Optional[dict]:
        ep = self.ep
        g = self.tf7
        row = ep.view_row(cand.pid)
        attr, gate = g.get("attr"), g.get("gate")
        price = ep.price(cand.key)
        currency = str(g.get("currency") or ep.currency or "")
        budget = ep.budget if ep.budget is not None else price
        claims = [{"field": attr, "value": str(gate)}]
        if price is not None:
            claims.append({"field": "price", "value": _tf7_price_text(price)})
        elif budget is not None:
            claims.append({"field": "price", "value": f"at most {_tf7_price_text(budget)}"})
        claims.append({"field": "in_stock", "value": "true"})
        brand = str(row.get("brand") or "").strip()
        if re.search(r"[a-z0-9]", brand, re.I):
            claims.append({"field": "brand", "value": brand})
        else:
            soft = next((f for f in _TF7_SOFT_PATTERNS if _tf7_soft_supported(row, f)), None)
            if soft:
                claims.append({"field": soft, "value": "true"})
        errors = self._tf7_self_check(claims, row, price, currency)
        if errors:
            ep.notes.append(f"tf7 claim self-check: {errors}")
            if any(e == "price" for e in errors) and budget is not None:
                for claim in claims:
                    if claim["field"] == "price":
                        claim["value"] = f"at most {_tf7_price_text(budget)}"
        return {"claims": claims}

    def _tf7_self_check(self, claims: list, row: dict, price: Optional[float], currency: str) -> list:
        """justification_faithfulness + claim_grounding shape rules on visible data."""

        g = self.tf7
        errors: list = []
        fields: set = set()
        for claim in claims:
            if set(claim) != {"field", "value"} or not all(
                    isinstance(claim[k], str) and claim[k].strip() for k in claim):
                errors.append("claim_shape")
                continue
            field, value = _tf7_claim_field(claim["field"]), claim["value"]
            fields.add(field)
            if field in _TF7_FACT_LABEL:
                claimed = norm_attr_claim_value(field, value)
                if (claimed is None or claimed != fact_attr_value(row, field)
                        or claimed != resolve_attribute_visible(row, field)):
                    errors.append(f"{field}_unsupported")
            elif field == "price":
                if price is None or not _tf7_price_claim_ok(value, float(price), currency):
                    errors.append("price")
            elif field == "in_stock":
                if _tf7_bool_value(value) is not True:
                    errors.append("in_stock")
            elif field == "brand":
                if _tf7_norm(value) != _tf7_norm(row.get("brand")):
                    errors.append("brand")
            elif field in _TF7_SOFT_PATTERNS:
                if _tf7_bool_value(value) is not True or not _tf7_soft_supported(row, field):
                    errors.append(f"{field}_unsupported")
            else:
                errors.append(f"{field}_not_allowed")
        missing = {g.get("attr"), "price", "in_stock"} - fields
        if missing:
            errors.append("missing:" + ",".join(sorted(str(m) for m in missing)))
        if not fields & (set(_TF7_SOFT_PATTERNS) | {"brand"}):
            errors.append("missing_soft")
        return errors

    def order_message(self, cand: Candidate) -> str:
        ep = self.ep
        g = self.tf7
        row = ep.view_row(cand.pid)
        attr = g.get("attr")
        price = ep.price(cand.key)
        currency = ep.currency
        fact = str((row.get("facts") or {}).get(_TF7_FACT_LABEL.get(attr, ""), "") or "")[:80]
        phrase = _tf7_phrase_for(attr, g.get("gate")) if attr and g.get("gate") else "requested"
        parts = [f"I'm ordering {str(row.get('title') or cand.pid)[:140]} (SKU {cand.sku})"]
        if price is not None:
            parts[0] += f" at {fmt_money(price)} {currency}"
        parts[0] += "."
        if fact:
            parts.append(f"Its product facts list {_TF7_FACT_LABEL.get(attr)} as '{fact}', so it has the "
                         f"{phrase} spec you asked for.")
        brand = str(row.get("brand") or "").strip()
        tail = "It is in stock right now"
        if ep.budget is not None:
            tail += f" and within your {fmt_money(ep.budget)} {currency} budget"
        if brand:
            tail += f", from {brand}"
        parts.append(tail + ".")
        if ep.event is not None:
            new_price = ep.event.new_price
            jump = f" to {fmt_money(float(new_price))} {currency}" if new_price else ""
            parts.append(f"My first pick's price jumped{jump} after I added it, above your budget, "
                         "so I re-checked and switched to this one.")
        return " ".join(parts)[:600]

