# agent.py
# ========================================================================

import traceback
from typing import Any


# Importing the family modules registers their strategies (package mode only;
# in the built single file every strategy is already defined above).


def agent_main(problem_data: dict) -> list:
    """Solve one ORO Bench task; the environment receipts are what get scored.

    The returned list is only the (untrusted) trajectory the sandbox records for
    debugging. Scores come from the validator's session receipts.
    """

    try:
        ep = run_episode(problem_data)
    except Exception as exc:  # never crash the sandbox worker
        return [{
            "role": "assistant",
            "content": f"agent error: {type(exc).__name__}: {exc}",
            "traceback": traceback.format_exc()[-2000:],
        }]
    summary: dict[str, Any] = {
        "role": "assistant",
        "content": f"family={ep.family} turns={ep.turn} done={ep.done}",
        "family": ep.family,
        "intent": ep.intent,
        "budget": ep.budget,
        "first_add": ep.first_add.key if ep.first_add else None,
        "event": vars(ep.event) if ep.event else None,
        "order": ep.order_result,
        "slot_wait_s": round(ep.slot_wait_s, 3),
        "notes": ep.notes,
    }
    return [*ep.log, summary]



__all__ = ["agent_main"]
